export const expandedQuestions = [{"prompt":"Calculate 4 + 3 × 4.","answer":16,"hint":"Do multiplication before addition.","solution":"3 × 4 = 12; then add 4 to get 16.","id":"x001-01","subject":"maths","topic":"Order of operations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"The temperature is −3°C. It falls by 5°C. What is the new temperature in °C?","answer":-8,"hint":"A fall makes the number more negative.","solution":"−3 − 5 = −8°C.","id":"x002-01","subject":"maths","topic":"Calculating with negatives","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the value of the hundreds digit in 1201?","answer":200,"hint":"Identify the digit three places from the right.","solution":"The hundreds digit is 2, so its value is 2 × 100 = 200.","id":"x003-01","subject":"maths","topic":"Place value","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 3.376 to two decimal places.","answer":3.38,"hint":"Look at the third decimal digit.","solution":"The third digit is 6, so round the hundredths up: 3.38.","id":"x004-01","subject":"maths","topic":"Rounding decimal places","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 1551 to two significant figures.","answer":1600,"hint":"Count significant digits from the first non-zero digit.","solution":"The first two significant figures are in the thousands and hundreds columns. Rounding 1551 to the nearest 100 gives 1600.","id":"x005-01","subject":"maths","topic":"Significant figures","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Estimate 3.9 × 19.8 by rounding each number to the nearest whole number first.","answer":80,"hint":"Follow the requested rounding method for both numbers.","solution":"3.9 rounds to 4; 19.8 rounds to 20. The estimate is 80.","id":"x006-01","subject":"maths","topic":"Estimating calculations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"How many positive factors does 4 have?","answer":3,"hint":"For a power of 2, list 2⁰ up to the highest power.","solution":"4 = 2^2. Its factors are 2⁰ through 2^2, giving 3 factors.","id":"x007-01","subject":"maths","topic":"Factors","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the smallest multiple of 4 that is strictly greater than 40?","answer":44,"hint":"The number given is already the tenth multiple.","solution":"The next multiple is 11 × 4 = 44.","id":"x008-01","subject":"maths","topic":"Multiples","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Which number in this list is prime? Set 1.","kind":"choice","options":["16","18","27","11"],"correct":3,"answer":null,"hint":"A prime has exactly two positive factors: 1 and itself.","solution":"11 has no positive factors except 1 and itself. The other numbers have explicit factors 4, 6 or 9.","id":"x009-01","subject":"maths","topic":"Prime numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"In the prime factorisation of 18, what is the exponent of 2?","answer":1,"hint":"Keep dividing by 2 until the remaining number is odd.","solution":"18 = 2^1 × 3², so the exponent is 1.","id":"x010-01","subject":"maths","topic":"Prime factorisation","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the highest common factor of 12 and 18.","answer":6,"hint":"Look for the largest factor that divides both numbers.","solution":"12 = 2 × 6 and 18 = 3 × 6. Since 2 and 3 are coprime, the HCF is 6.","id":"x011-01","subject":"maths","topic":"Highest common factor","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the lowest common multiple of 4 and 6.","answer":12,"hint":"Find the HCF first, or list the multiples.","solution":"The HCF is 2. LCM = (4 × 6) ÷ 2 = 12.","id":"x012-01","subject":"maths","topic":"Lowest common multiple","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 1/12 + 1/8. Give a fraction or decimal.","answer":0.2083333333,"hint":"Use a common denominator of 24.","solution":"1/12 = 2/24 and 1/8 = 3/24. The sum is 5/24.","id":"x013-01","subject":"maths","topic":"Adding fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 1/11 × 3/5. Give a fraction or decimal.","answer":0.0545454545,"hint":"Multiply numerators and denominators.","solution":"(1 × 3)/(11 × 5) = 3/55. Simplify if possible.","id":"x014-01","subject":"maths","topic":"Multiplying fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 1/12 ÷ 5/6. Give a fraction or decimal.","answer":0.1,"hint":"Multiply by the reciprocal of 5/6.","solution":"1/12 × 6/5 = 6/60 = 1/10.","id":"x015-01","subject":"maths","topic":"Dividing fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 1 3/4 as a decimal.","answer":1.75,"hint":"The fraction part is three quarters, or 0.75.","solution":"1 + 0.75 = 1.75.","id":"x016-01","subject":"maths","topic":"Mixed numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A club has 24 members. Three eighths cycle to the club. How many members cycle?","answer":9,"hint":"Divide by 8 to find one eighth, then multiply by 3.","solution":"24 ÷ 8 × 3 = 9.","id":"x017-01","subject":"maths","topic":"Fractions of quantities","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 0.111111… (the block 11 repeats) as a fraction or decimal.","answer":0.1111111111,"hint":"For a two-digit repeating block, compare 100x with x.","solution":"If x = 0.1111…, then 100x − x = 11; hence x = 11/99.","id":"x018-01","subject":"maths","topic":"Recurring decimals","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Simplify 3^2 × 3^4 to 3^k. Find k.","answer":6,"hint":"Add exponents when multiplying powers of the same base.","solution":"k = 2 + 4 = 6.","id":"x019-01","subject":"maths","topic":"Index laws","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Evaluate 2^−2. Give a fraction or decimal.","answer":0.25,"hint":"A negative exponent gives the reciprocal of the positive power.","solution":"2^−2 = 1/(2²) = 1/4.","id":"x020-01","subject":"maths","topic":"Negative indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Evaluate 27^(2/3).","answer":9,"hint":"Take the cube root, then square the result.","solution":"The cube root of 27 is 3; its square is 9.","id":"x021-01","subject":"maths","topic":"Fractional indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write √8 in the form a√2. Find a.","answer":2,"hint":"Look for a square factor inside the root.","solution":"√(4 × 2) = 2√2, so a = 2.","id":"x022-01","subject":"maths","topic":"Simplifying surds","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write 3/√3 in the form a√3. Find a.","answer":1,"hint":"Multiply numerator and denominator by √3.","solution":"(3√3)/3 = 1√3.","id":"x023-01","subject":"maths","topic":"Rationalising denominators","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate (2 × 10^1) × (3 × 10²). Write the result as 6 × 10^k. Find k.","answer":3,"hint":"Multiply the coefficients and add powers of ten.","solution":"2 × 3 = 6 and 1 + 2 = 3, so k = 3.","id":"x024-01","subject":"maths","topic":"Calculating in standard form","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A length is 11 cm to the nearest centimetre. Give the lower bound in cm.","answer":10.5,"hint":"The rounding interval extends half a centimetre either side.","solution":"The lower bound is 11 − 0.5 = 10.5 cm; the upper bound is 11.5 cm and is excluded.","id":"x025-01","subject":"maths","topic":"Error intervals","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle has length 11 cm and width 5 cm, both to the nearest centimetre. Find the upper bound for its area in cm².","answer":63.25,"hint":"Use the upper bound for each positive length.","solution":"Upper area bound = 11.5 × 5.5 = 63.25 cm².","id":"x026-01","subject":"maths","topic":"Upper and lower bounds","group":"Number","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify 3x + 5x − 3x to ax. Find a.","answer":5,"hint":"Combine only the coefficients of x.","solution":"a = 3 + 5 − 3 = 5.","id":"x027-01","subject":"maths","topic":"Collecting like terms","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand 3(x + 2). What is the constant term?","answer":6,"hint":"Multiply both terms inside the bracket.","solution":"The expansion is 3x + 6.","id":"x028-01","subject":"maths","topic":"Expanding a single bracket","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand (x + 1)(x + 4). What is the coefficient of x?","answer":5,"hint":"Multiply every term in one bracket by every term in the other.","solution":"x² + 4x + 1x + 4 = x² + 5x + 4.","id":"x029-01","subject":"maths","topic":"Expanding double brackets","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise fully 2x + 6.","kind":"choice","options":["2(x + 6)","1(x + 3)","6(x + 2)","2(x + 3)"],"correct":3,"answer":null,"hint":"Take out the highest common factor of the two coefficients.","solution":"Both terms contain 2. Dividing gives x and 3, so the result is 2(x + 3).","id":"x030-01","subject":"maths","topic":"Factorising with a common factor","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise x² + 5x + 4.","kind":"choice","options":["(x − 1)(x − 4)","(x + 2)(x + 3)","(x − 1)(x + 4)","(x + 1)(x + 4)"],"correct":3,"answer":null,"hint":"Find two numbers whose product is the constant and whose sum is the x coefficient.","solution":"1 × 4 = 4 and 1 + 4 = 5.","id":"x031-01","subject":"maths","topic":"Factorising quadratics","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Find 2a² − b when a = 1 and b = 4.","answer":-2,"hint":"Square a before multiplying by 2.","solution":"2 × 1² − 4 = -2.","id":"x032-01","subject":"maths","topic":"Substitution","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The formula is y = 3x − 1. If y = 5, find x.","answer":2,"hint":"Add the constant to y, then divide by the coefficient of x.","solution":"x = (y + 1)/3 = 6/3 = 2.","id":"x033-01","subject":"maths","topic":"Changing the subject","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the smallest integer satisfying 3x + 1 > 4.","answer":2,"hint":"Subtract the constant, divide by 3, then respect the strict inequality.","solution":"3x > 3, so x > 1. The smallest integer is 2.","id":"x034-01","subject":"maths","topic":"Linear inequalities","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Solve x + y = 4 and x − y = 2. Give x.","answer":3,"hint":"Add the two equations to eliminate y.","solution":"2x = 6, so x = 3.","id":"x035-01","subject":"maths","topic":"Simultaneous linear equations","group":"Algebra","tier":"Both","calculator":false,"marks":3},{"prompt":"The graphs y = x² and y = 1 meet. Give the positive x-coordinate.","answer":1,"hint":"Substitute to obtain x² equal to the constant.","solution":"x² = 1, so x = ±1. The positive value is 1.","id":"x036-01","subject":"maths","topic":"Simultaneous nonlinear equations","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"Write x² + 2x + 4 as (x + a)² + b. Find b.","answer":3,"hint":"Half the x coefficient gives a. Subtract a² from the constant.","solution":"a = 1. Subtract 1 from the constant 4 to get b = 3.","id":"x037-01","subject":"maths","topic":"Completing the square","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Use the quadratic formula to find the positive root of x² + x − 2 = 0.","answer":1,"hint":"Identify a, b and c. Use x = (−b ± √(b² − 4ac))/(2a).","solution":"a=1, b=1, c=−2. The discriminant is 1 + 8 = 9. The positive root is (−1 + 3)/2 = 1.","id":"x038-01","subject":"maths","topic":"Quadratic formula","group":"Algebra","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify (3x)/(6x²) for x ≠ 0, then evaluate at x = 1.","answer":0.5,"hint":"Cancel the common numerical factor and one factor of x.","solution":"The expression simplifies to 1/(2x). At x = 1, it is 1/2.","id":"x039-01","subject":"maths","topic":"Algebraic fractions","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"The difference (k + 1)² − k² simplifies to 2k + 1. Use this identity to find the difference between the squares of 5 and 6.","answer":11,"hint":"Expand the square before cancelling k².","solution":"Expanding proves (k + 1)² − k² = 2k + 1. Set k = 5: the difference is 11.","id":"x040-01","subject":"maths","topic":"Algebraic proof","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x − 1. Find f(3).","answer":8,"hint":"Replace every x with the specified input.","solution":"f(3) = 3(3) − 1 = 8.","id":"x041-01","subject":"maths","topic":"Function notation","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"f(x) = 2x + 1 and g(x) = x². Find f(g(1)).","answer":3,"hint":"Apply the inside function first.","solution":"g(1) = 1; f(1) = 3.","id":"x042-01","subject":"maths","topic":"Composite functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x + 1. Find f⁻¹(4).","answer":1,"hint":"Undo the addition, then undo the multiplication.","solution":"f⁻¹(y) = (y − 1)/3. With y = 4, this gives 1.","id":"x043-01","subject":"maths","topic":"Inverse functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"x₀ = 1. Use x_(k+1) = (x_k + 4)/2 to calculate x₂.","answer":3.25,"hint":"Calculate x₁ first and substitute that new value again.","solution":"x₁ = (1 + 4)/2 = 2.5. Then x₂ = (2.5 + 4)/2 = 3.25.","id":"x044-01","subject":"maths","topic":"Iteration","group":"Algebra","tier":"Higher","calculator":true,"marks":2},{"prompt":"A geometric sequence starts at 2 and has common ratio 3. Find its fourth term.","answer":54,"hint":"Multiply by 3 three times after the first term.","solution":"The fourth term is 2 × 3³ = 54.","id":"x045-01","subject":"maths","topic":"Geometric sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The nth term is n² + 1n + 2. Find the fifth term.","answer":32,"hint":"Replace each occurrence of n (the position variable) with 5.","solution":"5² + 1 × 5 + 2 = 32.","id":"x046-01","subject":"maths","topic":"Quadratic sequences","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sequence begins 1, 2. Each new term is the sum of the preceding two. Find the fifth term.","answer":8,"hint":"Build the third and fourth terms before the fifth.","solution":"The terms are 1, 2, 3, 5, 8.","id":"x047-01","subject":"maths","topic":"Fibonacci-type sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the x-coordinate of the midpoint of (1, 2) and (5, 8).","answer":3,"hint":"Average the two x-coordinates.","solution":"(1 + 5)/2 = 3. The full midpoint is (3, 5).","id":"x048-01","subject":"maths","topic":"Midpoints","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the distance between (0, 0) and (3, 4).","answer":5,"hint":"Use the horizontal and vertical differences in Pythagoras.","solution":"√(3² + 4²) = 5 units.","id":"x049-01","subject":"maths","topic":"Distance between coordinates","group":"Coordinate geometry","tier":"Both","calculator":true,"marks":3},{"prompt":"A line is parallel to y = 2x − 4 and passes through (0, 1). Give its gradient.","answer":2,"hint":"Parallel non-vertical lines have equal gradients.","solution":"The given line has gradient 2, so the parallel line does too.","id":"x050-01","subject":"maths","topic":"Parallel lines","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the gradient of a line perpendicular to y = 2x + 2. Give a fraction or decimal.","answer":-0.5,"hint":"For non-zero gradients, the perpendicular gradient is the negative reciprocal.","solution":"The negative reciprocal of 2 is −1/2.","id":"x051-01","subject":"maths","topic":"Perpendicular lines","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A line passes through (1, 3) and (3, 5). Write it as y = mx + c. Find c.","answer":2,"hint":"Find the gradient from the two points, then substitute a point.","solution":"m = (5 − 3)/2 = 1. Then c = 3 − 1 = 2.","id":"x052-01","subject":"maths","topic":"Equation of a line through points","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"A pack of 4 notebooks costs £8. Find the price per notebook in pounds.","answer":2,"hint":"Divide cost by number of items.","solution":"£8 ÷ 4 = £2 per notebook.","id":"x053-01","subject":"maths","topic":"Best buys and unit pricing","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"£1 exchanges for €1.20. How many euros are exchanged for £25?","answer":30,"hint":"Multiply the pound amount by the euros-per-pound rate.","solution":"25 × 1.20 = €30.","id":"x054-01","subject":"maths","topic":"Currency conversion","group":"Proportion and rates","tier":"Both","calculator":true,"marks":2},{"prompt":"A recipe for 4 people uses 100 g of rice. How many grams are needed for 6 people?","answer":150.0,"hint":"Scale every ingredient by 6/4.","solution":"100 × 6/4 = 150.0 g.","id":"x055-01","subject":"maths","topic":"Scaling recipes","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"A map has scale 1:50 000. Two places are 1 cm apart on the map. Find their real distance in kilometres.","answer":0.5,"hint":"Convert the scaled centimetres into kilometres using 100 000 cm = 1 km.","solution":"1 × 50 000 = 50000 cm = 0.5 km.","id":"x056-01","subject":"maths","topic":"Map scales","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is directly proportional to x. When x = 3, y = 6. Find y when x = 8.","answer":16,"hint":"Find k in y = kx.","solution":"k = 6/3 = 2; hence y = 2 × 8 = 16.","id":"x057-01","subject":"maths","topic":"Direct proportion","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is inversely proportional to x. When x = 2, y = 6. Find y when x = 3.","answer":4,"hint":"The product xy stays constant.","solution":"k = 2 × 6 = 12. Thus y = 12/3 = 4.","id":"x058-01","subject":"maths","topic":"Inverse proportion","group":"Proportion and rates","tier":"Higher","calculator":false,"marks":2},{"prompt":"£100 earns 5% compound interest each year. Find the balance after 2 years in pounds.","answer":110.25,"hint":"Multiply by 1.05 for each year.","solution":"£100 × 1.05² = £110.25.","id":"x059-01","subject":"maths","topic":"Compound interest","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A bicycle worth £250 loses 20% of its value each year. Find its value after 2 years in pounds.","answer":160,"hint":"Retain 80% each year, using the multiplier 0.8 twice.","solution":"£250 × 0.8² = £160.","id":"x060-01","subject":"maths","topic":"Depreciation","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A culture begins with 200 cells and increases by 10% each hour. Find the modelled count after 2 hours.","answer":242,"hint":"Use the growth multiplier 1.1 twice.","solution":"200 × 1.1² = 242 cells.","id":"x061-01","subject":"maths","topic":"Repeated percentage growth","group":"Finance","tier":"Both","calculator":true,"marks":2},{"prompt":"A block has mass 24 g and volume 12 cm³. Find its density in g/cm³.","answer":2,"hint":"Density = mass ÷ volume.","solution":"24 ÷ 12 = 2 g/cm³.","id":"x062-01","subject":"maths","topic":"Density","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A force of 45 N acts on an area of 3 m². Find pressure in N/m².","answer":15,"hint":"Pressure = force ÷ area.","solution":"45 ÷ 3 = 15 N/m².","id":"x063-01","subject":"maths","topic":"Pressure","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"Convert 2 m² into cm².","answer":20000,"hint":"Square the linear conversion: 1 m = 100 cm.","solution":"1 m² = 100² = 10 000 cm². Therefore 2 m² = 20000 cm².","id":"x064-01","subject":"maths","topic":"Metric area conversions","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A journey starts at 09:11 and ends at 11:45. Find its duration in minutes.","answer":154,"hint":"Count the full hours and the remaining minutes.","solution":"From 09:11 to 11:11 is 120 minutes, then another 34. Total = 154 minutes.","id":"x065-01","subject":"maths","topic":"Time calculations","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle is 9 cm by 5 cm. A 2 cm by 2 cm square is cut from one corner. Find the perimeter of the remaining L-shape in cm.","answer":28,"hint":"The two removed edge lengths are replaced by two equal inner edge lengths.","solution":"The perimeter stays equal to the original rectangle: 2(9 + 5) = 28 cm.","id":"x066-01","subject":"maths","topic":"Perimeter of compound shapes","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 2 cm. Express its circumference as kπ cm. Find k.","answer":4,"hint":"Circumference is 2πr.","solution":"2π × 2 = 4π cm.","id":"x067-01","subject":"maths","topic":"Circle circumference","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 3 cm. Its area is kπ cm². Find k.","answer":9,"hint":"Square the radius and multiply by π.","solution":"Area = π × 3² = 9π cm².","id":"x068-01","subject":"maths","topic":"Area of circles","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A semicircle has radius 3 cm. Its perimeter is πr + d. Find the straight-edge length d in cm.","answer":6,"hint":"The straight edge is the diameter, not the radius.","solution":"d = 2r = 2 × 3 = 6 cm. The complete perimeter is 3π + 6 cm.","id":"x069-01","subject":"maths","topic":"Semicircle perimeter","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 60° and radius 3 cm. Its arc length is kπ cm. Find k.","answer":1,"hint":"Take 60/360 of the circumference.","solution":"(60/360) × 2π × 3 = 1π cm.","id":"x070-01","subject":"maths","topic":"Arc length","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 90° and radius 2 cm. Its area is kπ cm². Find k.","answer":1,"hint":"Take one quarter of the full circle area.","solution":"(90/360) × π × 2² = 1π cm².","id":"x071-01","subject":"maths","topic":"Sector area","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A triangular prism has triangular cross-section base 3 cm, height 6 cm, and prism length 10 cm. Find its volume in cm³.","answer":90,"hint":"Find the triangle area, then multiply by the prism length.","solution":"Cross-section = ½ × 3 × 6 = 9 cm². Volume = 90 cm³.","id":"x072-01","subject":"maths","topic":"Volume of prisms","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A cylinder has radius 2 cm and height 5 cm. Its volume is kπ cm³. Find k.","answer":20,"hint":"Multiply the circular base area by the height.","solution":"πr²h = π × 2² × 5 = 20π cm³.","id":"x073-01","subject":"maths","topic":"Volume of cylinders","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A cone has radius 2 cm and perpendicular height 9 cm. Its volume is kπ cm³. Find k.","answer":12,"hint":"A cone has one third of the corresponding cylinder volume.","solution":"V = πr²h/3 = π × 2² × 9/3 = 12π cm³.","id":"x074-01","subject":"maths","topic":"Volume of cones","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sphere has radius 3 cm. Its volume is kπ cm³. Find k.","answer":36,"hint":"Use V = 4πr³/3.","solution":"(4/3) × 3³ = 36, so V = 36π cm³.","id":"x075-01","subject":"maths","topic":"Volume of spheres","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A cuboid measures 2 cm by 3 cm by 4 cm. Find its total surface area in cm².","answer":52,"hint":"There are two faces of each of the three different rectangular areas.","solution":"2[3(2) + 4(2) + 3×4] = 52 cm².","id":"x076-01","subject":"maths","topic":"Surface area of cuboids","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A closed cylinder has radius 2 cm and height 4 cm. Its total surface area is kπ cm². Find k.","answer":24,"hint":"Include two circular ends and the curved surface.","solution":"2r² + 2rh = 2(2²) + 2(2)(4) = 24.","id":"x077-01","subject":"maths","topic":"Cylinder surface area","group":"Geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"Two similar shapes have length scale factor 3 from small to large. A small side is 3 cm. Find the matching large side.","answer":9,"hint":"Multiply corresponding lengths by the length scale factor.","solution":"3 × 3 = 9 cm.","id":"x078-01","subject":"maths","topic":"Similarity of lengths","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Two similar shapes have length scale factor 2. The smaller area is 4 cm². Find the larger area.","answer":16,"hint":"Square the length scale factor for areas.","solution":"Area factor = 2² = 4. Larger area = 4 × 4 = 16 cm².","id":"x079-01","subject":"maths","topic":"Similarity of areas","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"Two similar solids have length scale factor 3. The smaller volume is 2 cm³. Find the larger volume.","answer":54,"hint":"Cube the length scale factor for volumes.","solution":"Volume factor = 3³ = 27. Larger volume = 54 cm³.","id":"x080-01","subject":"maths","topic":"Similarity of volumes","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A triangle has two angles 41° and 61°. Find the third angle in degrees.","answer":78,"hint":"Interior angles in a triangle total 180°.","solution":"180 − 41 − 61 = 78°.","id":"x081-01","subject":"maths","topic":"Triangle angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A regular polygon has 5 sides. Find its exterior angle in degrees, to 3 decimal places if needed.","answer":72.0,"hint":"The exterior angles total 360°.","solution":"Each exterior angle is 360/5 = 72.000°.","id":"x082-01","subject":"maths","topic":"Exterior angles of polygons","group":"Geometry","tier":"Both","calculator":true,"marks":2},{"prompt":"A transversal crosses two parallel lines. One of a pair of co-interior angles is 63°. Find the other angle in degrees.","answer":117,"hint":"Co-interior angles on parallel lines sum to 180°.","solution":"180 − 63 = 117°.","id":"x083-01","subject":"maths","topic":"Angles in parallel lines","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the sum of the interior angles of a polygon with 4 sides.","answer":360,"hint":"Use (number of sides − 2) × 180°.","solution":"(4 − 2) × 180 = 360°.","id":"x084-01","subject":"maths","topic":"Polygon interior-angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"The bearing of B from A is 025°. Find the bearing of A from B as a number of degrees.","answer":205,"hint":"A reverse bearing differs by 180°.","solution":"25 + 180 = 205°.","id":"x085-01","subject":"maths","topic":"Three-figure bearings","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A right-angled triangle has hypotenuse 6 cm and an angle of 30°. Find the side opposite that angle in cm.","answer":3,"hint":"Use sin(angle) = opposite/hypotenuse.","solution":"Opposite = 6 × sin30° = 3 cm.","id":"x086-01","subject":"maths","topic":"Right-angle trigonometry","group":"Trigonometry","tier":"Both","calculator":true,"marks":3},{"prompt":"In a triangle, side a = 3 cm is opposite 30°, and side b is opposite 90°. Find b in cm.","answer":6,"hint":"Use a/sin A = b/sin B.","solution":"b = 3 × sin90°/sin30° = 6 cm.","id":"x087-01","subject":"maths","topic":"Sine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides of a triangle are 3 cm each, with included angle 60°. Find the opposite side in cm.","answer":3,"hint":"Use c² = a² + b² − 2ab cos C.","solution":"c² = 2(3²) − 2(3²)cos60° = 9, so c = 3 cm.","id":"x088-01","subject":"maths","topic":"Cosine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides are 3 cm and 8 cm, with included angle 30°. Find the triangle area in cm².","answer":6,"hint":"Use area = ½ab sin C.","solution":"½ × 3 × 8 × sin30° = 6 cm².","id":"x089-01","subject":"maths","topic":"Triangle area using sine","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"An angle at the circumference is 21°. The central angle subtended by the same arc is less than 180°. Find it.","answer":42,"hint":"The angle at the centre is twice the angle at the circumference on the same arc.","solution":"2 × 21 = 42°.","id":"x090-01","subject":"maths","topic":"Angles at the centre","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"One angle of a cyclic quadrilateral is 92°. Find its opposite angle.","answer":88,"hint":"Opposite angles in a cyclic quadrilateral total 180°.","solution":"180 − 92 = 88°.","id":"x091-01","subject":"maths","topic":"Cyclic quadrilaterals","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"A tangent and chord form an angle of 27°. Find the angle subtended by that chord in the alternate segment.","answer":27,"hint":"The tangent-chord angle equals the angle in the alternate segment.","solution":"By the alternate segment theorem, the required angle is 27°.","id":"x092-01","subject":"maths","topic":"Alternate segment theorem","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"Vectors a = (1, 3) and b = (3, −1). Find the x-component of a + b.","answer":4,"hint":"Add corresponding components.","solution":"a + b = (4, 2), so the x-component is 4.","id":"x093-01","subject":"maths","topic":"Adding vectors","group":"Vectors","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the magnitude of the vector (3, 4).","answer":5,"hint":"Use Pythagoras on the two components.","solution":"√(3² + 4²) = 5.","id":"x094-01","subject":"maths","topic":"Vector magnitude","group":"Vectors","tier":"Higher","calculator":true,"marks":2},{"prompt":"Rotate (1, 3) by 90° anticlockwise about the origin. Find the new x-coordinate.","answer":-3,"hint":"The rule for 90° anticlockwise is (x,y) → (−y,x).","solution":"The image is (−3, 1), so its x-coordinate is −3.","id":"x095-01","subject":"maths","topic":"Rotations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Enlarge (1, 2) by scale factor 3 about the origin. Find the new x-coordinate.","answer":3,"hint":"Multiply both coordinates by the scale factor.","solution":"The image is (3, 6).","id":"x096-01","subject":"maths","topic":"Enlargements","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Translate (1, 4) by the vector (−3, 2). Find the new x-coordinate.","answer":-2,"hint":"Add the x-component of the vector to the x-coordinate.","solution":"The image is (-2, 6).","id":"x097-01","subject":"maths","topic":"Translations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Reflect (1, 4) in the line y = x. Find the new x-coordinate.","answer":4,"hint":"Reflection in y = x swaps the coordinates.","solution":"The image is (4, 1).","id":"x098-01","subject":"maths","topic":"Reflections","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Points must be exactly 3 cm from a fixed point P. What is their locus?","kind":"choice","options":["A circle centred at P with diameter 3 cm","A straight line through P","A perpendicular bisector through P","A circle centred at P with radius 3 cm"],"correct":3,"answer":null,"hint":"A fixed distance from one point defines a circle.","solution":"All points on a circle of radius 3 cm are exactly 3 cm from its centre P.","id":"x099-01","subject":"maths","topic":"Loci and constructions","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the median of 8, 1, 4, 10, 2.","answer":4,"hint":"Order the values, then choose the middle one.","solution":"The ordered list is 1, 2, 4, 8, 10. Its middle value is 4.","id":"x100-01","subject":"maths","topic":"Finding the median","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the mode of 1, 3, 3, 5, 3, 7.","answer":3,"hint":"Look for the value occurring most frequently.","solution":"3 occurs three times; every other value occurs once.","id":"x101-01","subject":"maths","topic":"Finding the mode","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the range of −1, 2, 5, 0.","answer":6,"hint":"Subtract the minimum from the maximum.","solution":"5 − (−1) = 6.","id":"x102-01","subject":"maths","topic":"Finding the range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A data set has lower quartile 4 and upper quartile 11. Find its interquartile range.","answer":7,"hint":"IQR = upper quartile − lower quartile.","solution":"11 − 4 = 7.","id":"x103-01","subject":"maths","topic":"Interquartile range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A grouped table has 2 values in 0 ≤ x < 10 and 3 values in 10 ≤ x < 20. Estimate the mean, to 3 decimal places.","answer":11.0,"hint":"Use class midpoints 5 and 15, multiply by frequencies, then divide by total frequency.","solution":"Estimated total = 2×5 + 3×15 = 55. Divide by 5 to get 11.000.","id":"x104-01","subject":"maths","topic":"Estimated mean from grouped data","group":"Statistics","tier":"Both","calculator":true,"marks":3},{"prompt":"A histogram class has width 5 and frequency 15. Find its frequency density.","answer":3,"hint":"Frequency density = frequency ÷ class width.","solution":"15 ÷ 5 = 3.","id":"x105-01","subject":"maths","topic":"Frequency density","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"Class frequencies, in ascending order, are 1, 3, 5, 7. Find the cumulative frequency at the end of the third class.","answer":9,"hint":"Add all frequencies up to and including the third class.","solution":"1 + 3 + 5 = 9.","id":"x106-01","subject":"maths","topic":"Cumulative frequency","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A box plot has minimum 1, lower quartile 4, median 7, upper quartile 10, maximum 16. Read off its median.","answer":7,"hint":"The median is the line inside the box.","solution":"The median line is at 7. The ends of the box are the quartiles.","id":"x107-01","subject":"maths","topic":"Box plots","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A school has 600 pupils; 30 are in a chosen group. In a proportional sample of 40 pupils, how many should come from that group?","answer":2,"hint":"Multiply the sample size by the group proportion.","solution":"40 × 30/600 = 2 pupils.","id":"x108-01","subject":"maths","topic":"Stratified sampling","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"An experiment succeeds 4 times out of 20 trials. Find the relative frequency as a fraction or decimal.","answer":0.2,"hint":"Divide the number of successes by the number of trials.","solution":"Relative frequency = 4/20 = 0.2.","id":"x109-01","subject":"maths","topic":"Relative frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"An event has probability 0.3. It is tested 20 times. Find its expected frequency.","answer":6,"hint":"Multiply probability by number of trials.","solution":"0.3 × 20 = 6. This is an expectation, not a guarantee.","id":"x110-01","subject":"maths","topic":"Expected frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Two independent events have probabilities 1/2 and 1/12. Find the probability that both occur.","answer":0.0416666667,"hint":"Multiply the probabilities of independent events.","solution":"1/2 × 1/12 = 1/24.","id":"x111-01","subject":"maths","topic":"Independent events","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A bag has 3 red counters and 3 blue counters. Two counters are drawn without replacement. Find P(both red), to 3 decimal places.","answer":0.2,"hint":"The second draw has one fewer red counter and one fewer counter altogether.","solution":"P = (3/6) × (2/5) = 0.200.","id":"x112-01","subject":"maths","topic":"Sampling without replacement","group":"Probability","tier":"Higher","calculator":true,"marks":3},{"prompt":"Of 6 club members who play tennis, 1 also swim. A member is chosen from the tennis players only. Find P(swims), as a fraction or decimal.","answer":0.1666666667,"hint":"Use the restricted tennis group as the denominator.","solution":"Given that the person plays tennis, P(swims) = 1/6.","id":"x113-01","subject":"maths","topic":"Conditional probability","group":"Probability","tier":"Higher","calculator":false,"marks":2},{"prompt":"Set A contains 11 people including 3 in A ∩ B. How many are in A only?","answer":8,"hint":"Subtract the intersection from the total in A.","solution":"11 − 3 = 8 people.","id":"x114-01","subject":"maths","topic":"Venn diagram regions","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"n(A) = 11, n(B) = 13, and n(A ∩ B) = 4. Find n(A ∪ B).","answer":20,"hint":"Add the two set sizes and subtract the overlap once.","solution":"11 + 13 − 4 = 20.","id":"x115-01","subject":"maths","topic":"Set union","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A fair coin is tossed, then a fair 4-sided die numbered 1 to 4 is rolled. Find P(heads and a 1).","answer":0.125,"hint":"Multiply the branch probabilities along the path.","solution":"(1/2) × (1/4) = 1/8.","id":"x116-01","subject":"maths","topic":"Tree diagrams","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Plot the listed points for y = x³ − 4. Use x = -2, -1, 0, 1, 2. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[-2,-12],[-1,-5],[0,-4],[1,-3],[2,4]],"curve":"quadratic","range":[-3,3,-14,14],"expression":"y = x³ − 4","hint":"Cube each x, preserving its sign, then add the constant.","solution":"The coordinates are (-2, -12), (-1, -5), (0, -4), (1, -3), (2, 4). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x117-01","subject":"maths","topic":"Cubic graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 12/x + 0 for 1 ≤ x ≤ 6. Use x = 1, 2, 3, 4, 6. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[1,12.0],[2,6.0],[3,4.0],[4,3.0],[6,2.0]],"curve":"quadratic","range":[0,7,0,23],"expression":"y = 12/x + 0 for 1 ≤ x ≤ 6","hint":"Divide 12 by x, then add the constant; x = 0 is not allowed.","solution":"The coordinates are (1, 12.0), (2, 6.0), (3, 4.0), (4, 3.0), (6, 2.0). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x118-01","subject":"maths","topic":"Reciprocal graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 2^x + 0. Use x = 0, 1, 2, 3. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[0,1],[1,2],[2,4],[3,8]],"curve":"quadratic","range":[-1,4,0,18],"expression":"y = 2^x + 0","hint":"Calculate the power of 2 first, then add the constant.","solution":"The coordinates are (0, 1), (1, 2), (2, 4), (3, 8). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x119-01","subject":"maths","topic":"Exponential graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"The graph y = x² is translated upward by 3 units. Find the new y-coordinate of its turning point.","answer":3,"hint":"An upward translation adds the same amount to every y-coordinate.","solution":"The old turning point is (0, 0); the new one is (0, 3).","id":"x120-01","subject":"maths","topic":"Translating graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A straight segment on a distance-time graph runs from (0 hours, 0 km) to (2 hours, 12 km). Find the speed in km/h.","answer":6,"hint":"Speed is the gradient: distance change divided by time change.","solution":"12 km ÷ 2 h = 6 km/h.","id":"x121-01","subject":"maths","topic":"Distance-time graphs","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A velocity-time graph rises in a straight line from 0 m/s to 5 m/s in 5 seconds. Find acceleration in m/s².","answer":1,"hint":"Acceleration is change in velocity divided by time.","solution":"(5 − 0)/5 = 1 m/s².","id":"x122-01","subject":"maths","topic":"Velocity-time gradients","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A tangent to a curve passes through (1, 1) and (3, 5). Estimate the gradient of the curve at the contact point.","answer":2,"hint":"Use the gradient of the tangent, not a chord through two curve points.","solution":"(5 − 1)/(3 − 1) = 2.","id":"x123-01","subject":"maths","topic":"Tangents and rates of change","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A velocity-time graph forms a triangle with base 6 seconds and maximum velocity 2 m/s. Find the displacement in metres.","answer":6,"hint":"Displacement is the signed area under a velocity-time graph.","solution":"Area = ½ × 6 × 2 = 6 m.","id":"x124-01","subject":"maths","topic":"Area under velocity-time graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"The lines y = x + 1 and y = 3x intersect. Find the x-coordinate of the intersection.","answer":0.5,"hint":"At the intersection, both expressions for y are equal.","solution":"x + 1 = 3x, so 2x = 1 and x = 0.5.","id":"x125-01","subject":"maths","topic":"Graphical simultaneous equations","group":"Graphs","tier":"Both","calculator":false,"marks":3},{"prompt":"Which point satisfies both x > 1 and y < 3?","kind":"choice","options":["(1, 2)","(2, 4)","(0, 0)","(2, 2)"],"correct":3,"answer":null,"hint":"Test both strict inequalities for each coordinate pair.","solution":"Only (2, 2) has x strictly greater than 1 and y strictly less than 3.","id":"x126-01","subject":"maths","topic":"Regions satisfying inequalities","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate 5 + 4 × 4.","answer":21,"hint":"Do multiplication before addition.","solution":"4 × 4 = 16; then add 5 to get 21.","id":"x001-02","subject":"maths","topic":"Order of operations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"The temperature is −4°C. It falls by 6°C. What is the new temperature in °C?","answer":-10,"hint":"A fall makes the number more negative.","solution":"−4 − 6 = −10°C.","id":"x002-02","subject":"maths","topic":"Calculating with negatives","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the value of the hundreds digit in 1302?","answer":300,"hint":"Identify the digit three places from the right.","solution":"The hundreds digit is 3, so its value is 3 × 100 = 300.","id":"x003-02","subject":"maths","topic":"Place value","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 4.376 to two decimal places.","answer":4.38,"hint":"Look at the third decimal digit.","solution":"The third digit is 6, so round the hundredths up: 4.38.","id":"x004-02","subject":"maths","topic":"Rounding decimal places","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 1868 to two significant figures.","answer":1900,"hint":"Count significant digits from the first non-zero digit.","solution":"The first two significant figures are in the thousands and hundreds columns. Rounding 1868 to the nearest 100 gives 1900.","id":"x005-02","subject":"maths","topic":"Significant figures","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Estimate 4.9 × 19.8 by rounding each number to the nearest whole number first.","answer":100,"hint":"Follow the requested rounding method for both numbers.","solution":"4.9 rounds to 5; 19.8 rounds to 20. The estimate is 100.","id":"x006-02","subject":"maths","topic":"Estimating calculations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"How many positive factors does 8 have?","answer":4,"hint":"For a power of 2, list 2⁰ up to the highest power.","solution":"8 = 2^3. Its factors are 2⁰ through 2^3, giving 4 factors.","id":"x007-02","subject":"maths","topic":"Factors","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the smallest multiple of 5 that is strictly greater than 50?","answer":55,"hint":"The number given is already the tenth multiple.","solution":"The next multiple is 11 × 5 = 55.","id":"x008-02","subject":"maths","topic":"Multiples","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Which number in this list is prime? Set 2.","kind":"choice","options":["24","36","13","20"],"correct":2,"answer":null,"hint":"A prime has exactly two positive factors: 1 and itself.","solution":"13 has no positive factors except 1 and itself. The other numbers have explicit factors 4, 6 or 9.","id":"x009-02","subject":"maths","topic":"Prime numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"In the prime factorisation of 36, what is the exponent of 2?","answer":2,"hint":"Keep dividing by 2 until the remaining number is odd.","solution":"36 = 2^2 × 3², so the exponent is 2.","id":"x010-02","subject":"maths","topic":"Prime factorisation","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the highest common factor of 24 and 36.","answer":12,"hint":"Look for the largest factor that divides both numbers.","solution":"24 = 2 × 12 and 36 = 3 × 12. Since 2 and 3 are coprime, the HCF is 12.","id":"x011-02","subject":"maths","topic":"Highest common factor","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the lowest common multiple of 8 and 12.","answer":24,"hint":"Find the HCF first, or list the multiples.","solution":"The HCF is 4. LCM = (8 × 12) ÷ 4 = 24.","id":"x012-02","subject":"maths","topic":"Lowest common multiple","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 2/12 + 1/8. Give a fraction or decimal.","answer":0.2916666667,"hint":"Use a common denominator of 24.","solution":"2/12 = 4/24 and 1/8 = 3/24. The sum is 7/24.","id":"x013-02","subject":"maths","topic":"Adding fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 2/11 × 3/5. Give a fraction or decimal.","answer":0.1090909091,"hint":"Multiply numerators and denominators.","solution":"(2 × 3)/(11 × 5) = 6/55. Simplify if possible.","id":"x014-02","subject":"maths","topic":"Multiplying fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 2/12 ÷ 5/6. Give a fraction or decimal.","answer":0.2,"hint":"Multiply by the reciprocal of 5/6.","solution":"2/12 × 6/5 = 12/60 = 2/10.","id":"x015-02","subject":"maths","topic":"Dividing fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 2 3/4 as a decimal.","answer":2.75,"hint":"The fraction part is three quarters, or 0.75.","solution":"2 + 0.75 = 2.75.","id":"x016-02","subject":"maths","topic":"Mixed numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A club has 48 members. Three eighths cycle to the club. How many members cycle?","answer":18,"hint":"Divide by 8 to find one eighth, then multiply by 3.","solution":"48 ÷ 8 × 3 = 18.","id":"x017-02","subject":"maths","topic":"Fractions of quantities","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 0.121212… (the block 12 repeats) as a fraction or decimal.","answer":0.1212121212,"hint":"For a two-digit repeating block, compare 100x with x.","solution":"If x = 0.1212…, then 100x − x = 12; hence x = 12/99.","id":"x018-02","subject":"maths","topic":"Recurring decimals","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Simplify 3^3 × 3^5 to 3^k. Find k.","answer":8,"hint":"Add exponents when multiplying powers of the same base.","solution":"k = 3 + 5 = 8.","id":"x019-02","subject":"maths","topic":"Index laws","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Evaluate 3^−2. Give a fraction or decimal.","answer":0.1111111111,"hint":"A negative exponent gives the reciprocal of the positive power.","solution":"3^−2 = 1/(3²) = 1/9.","id":"x020-02","subject":"maths","topic":"Negative indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Evaluate 64^(2/3).","answer":16,"hint":"Take the cube root, then square the result.","solution":"The cube root of 64 is 4; its square is 16.","id":"x021-02","subject":"maths","topic":"Fractional indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write √18 in the form a√2. Find a.","answer":3,"hint":"Look for a square factor inside the root.","solution":"√(9 × 2) = 3√2, so a = 3.","id":"x022-02","subject":"maths","topic":"Simplifying surds","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write 6/√3 in the form a√3. Find a.","answer":2,"hint":"Multiply numerator and denominator by √3.","solution":"(6√3)/3 = 2√3.","id":"x023-02","subject":"maths","topic":"Rationalising denominators","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate (2 × 10^2) × (3 × 10²). Write the result as 6 × 10^k. Find k.","answer":4,"hint":"Multiply the coefficients and add powers of ten.","solution":"2 × 3 = 6 and 2 + 2 = 4, so k = 4.","id":"x024-02","subject":"maths","topic":"Calculating in standard form","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A length is 12 cm to the nearest centimetre. Give the lower bound in cm.","answer":11.5,"hint":"The rounding interval extends half a centimetre either side.","solution":"The lower bound is 12 − 0.5 = 11.5 cm; the upper bound is 12.5 cm and is excluded.","id":"x025-02","subject":"maths","topic":"Error intervals","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle has length 12 cm and width 6 cm, both to the nearest centimetre. Find the upper bound for its area in cm².","answer":81.25,"hint":"Use the upper bound for each positive length.","solution":"Upper area bound = 12.5 × 6.5 = 81.25 cm².","id":"x026-02","subject":"maths","topic":"Upper and lower bounds","group":"Number","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify 4x + 6x − 3x to ax. Find a.","answer":7,"hint":"Combine only the coefficients of x.","solution":"a = 4 + 6 − 3 = 7.","id":"x027-02","subject":"maths","topic":"Collecting like terms","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand 4(x + 3). What is the constant term?","answer":12,"hint":"Multiply both terms inside the bracket.","solution":"The expansion is 4x + 12.","id":"x028-02","subject":"maths","topic":"Expanding a single bracket","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand (x + 2)(x + 5). What is the coefficient of x?","answer":7,"hint":"Multiply every term in one bracket by every term in the other.","solution":"x² + 5x + 2x + 10 = x² + 7x + 10.","id":"x029-02","subject":"maths","topic":"Expanding double brackets","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise fully 4x + 12.","kind":"choice","options":["2(x + 3)","12(x + 2)","4(x + 3)","4(x + 6)"],"correct":2,"answer":null,"hint":"Take out the highest common factor of the two coefficients.","solution":"Both terms contain 4. Dividing gives x and 3, so the result is 4(x + 3).","id":"x030-02","subject":"maths","topic":"Factorising with a common factor","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise x² + 7x + 10.","kind":"choice","options":["(x + 3)(x + 4)","(x − 2)(x + 5)","(x + 2)(x + 5)","(x − 2)(x − 5)"],"correct":2,"answer":null,"hint":"Find two numbers whose product is the constant and whose sum is the x coefficient.","solution":"2 × 5 = 10 and 2 + 5 = 7.","id":"x031-02","subject":"maths","topic":"Factorising quadratics","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Find 2a² − b when a = 2 and b = 5.","answer":3,"hint":"Square a before multiplying by 2.","solution":"2 × 2² − 5 = 3.","id":"x032-02","subject":"maths","topic":"Substitution","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The formula is y = 4x − 2. If y = 10, find x.","answer":3,"hint":"Add the constant to y, then divide by the coefficient of x.","solution":"x = (y + 2)/4 = 12/4 = 3.","id":"x033-02","subject":"maths","topic":"Changing the subject","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the smallest integer satisfying 3x + 2 > 8.","answer":3,"hint":"Subtract the constant, divide by 3, then respect the strict inequality.","solution":"3x > 6, so x > 2. The smallest integer is 3.","id":"x034-02","subject":"maths","topic":"Linear inequalities","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Solve x + y = 7 and x − y = 3. Give x.","answer":5,"hint":"Add the two equations to eliminate y.","solution":"2x = 10, so x = 5.","id":"x035-02","subject":"maths","topic":"Simultaneous linear equations","group":"Algebra","tier":"Both","calculator":false,"marks":3},{"prompt":"The graphs y = x² and y = 4 meet. Give the positive x-coordinate.","answer":2,"hint":"Substitute to obtain x² equal to the constant.","solution":"x² = 4, so x = ±2. The positive value is 2.","id":"x036-02","subject":"maths","topic":"Simultaneous nonlinear equations","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"Write x² + 4x + 8 as (x + a)² + b. Find b.","answer":4,"hint":"Half the x coefficient gives a. Subtract a² from the constant.","solution":"a = 2. Subtract 4 from the constant 8 to get b = 4.","id":"x037-02","subject":"maths","topic":"Completing the square","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Use the quadratic formula to find the positive root of x² + x − 6 = 0.","answer":2,"hint":"Identify a, b and c. Use x = (−b ± √(b² − 4ac))/(2a).","solution":"a=1, b=1, c=−6. The discriminant is 1 + 24 = 25. The positive root is (−1 + 5)/2 = 2.","id":"x038-02","subject":"maths","topic":"Quadratic formula","group":"Algebra","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify (4x)/(8x²) for x ≠ 0, then evaluate at x = 2.","answer":0.25,"hint":"Cancel the common numerical factor and one factor of x.","solution":"The expression simplifies to 1/(2x). At x = 2, it is 1/4.","id":"x039-02","subject":"maths","topic":"Algebraic fractions","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"The difference (k + 1)² − k² simplifies to 2k + 1. Use this identity to find the difference between the squares of 6 and 7.","answer":13,"hint":"Expand the square before cancelling k².","solution":"Expanding proves (k + 1)² − k² = 2k + 1. Set k = 6: the difference is 13.","id":"x040-02","subject":"maths","topic":"Algebraic proof","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x − 2. Find f(4).","answer":10,"hint":"Replace every x with the specified input.","solution":"f(4) = 3(4) − 2 = 10.","id":"x041-02","subject":"maths","topic":"Function notation","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"f(x) = 2x + 1 and g(x) = x². Find f(g(2)).","answer":9,"hint":"Apply the inside function first.","solution":"g(2) = 4; f(4) = 9.","id":"x042-02","subject":"maths","topic":"Composite functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x + 2. Find f⁻¹(8).","answer":2,"hint":"Undo the addition, then undo the multiplication.","solution":"f⁻¹(y) = (y − 2)/3. With y = 8, this gives 2.","id":"x043-02","subject":"maths","topic":"Inverse functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"x₀ = 2. Use x_(k+1) = (x_k + 4)/2 to calculate x₂.","answer":3.5,"hint":"Calculate x₁ first and substitute that new value again.","solution":"x₁ = (2 + 4)/2 = 3.0. Then x₂ = (3.0 + 4)/2 = 3.5.","id":"x044-02","subject":"maths","topic":"Iteration","group":"Algebra","tier":"Higher","calculator":true,"marks":2},{"prompt":"A geometric sequence starts at 3 and has common ratio 3. Find its fourth term.","answer":81,"hint":"Multiply by 3 three times after the first term.","solution":"The fourth term is 3 × 3³ = 81.","id":"x045-02","subject":"maths","topic":"Geometric sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The nth term is n² + 2n + 2. Find the fifth term.","answer":37,"hint":"Replace each occurrence of n (the position variable) with 5.","solution":"5² + 2 × 5 + 2 = 37.","id":"x046-02","subject":"maths","topic":"Quadratic sequences","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sequence begins 2, 3. Each new term is the sum of the preceding two. Find the fifth term.","answer":13,"hint":"Build the third and fourth terms before the fifth.","solution":"The terms are 2, 3, 5, 8, 13.","id":"x047-02","subject":"maths","topic":"Fibonacci-type sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the x-coordinate of the midpoint of (2, 2) and (8, 8).","answer":5,"hint":"Average the two x-coordinates.","solution":"(2 + 8)/2 = 5. The full midpoint is (5, 5).","id":"x048-02","subject":"maths","topic":"Midpoints","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the distance between (0, 0) and (6, 8).","answer":10,"hint":"Use the horizontal and vertical differences in Pythagoras.","solution":"√(6² + 8²) = 10 units.","id":"x049-02","subject":"maths","topic":"Distance between coordinates","group":"Coordinate geometry","tier":"Both","calculator":true,"marks":3},{"prompt":"A line is parallel to y = 3x − 4 and passes through (0, 2). Give its gradient.","answer":3,"hint":"Parallel non-vertical lines have equal gradients.","solution":"The given line has gradient 3, so the parallel line does too.","id":"x050-02","subject":"maths","topic":"Parallel lines","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the gradient of a line perpendicular to y = 3x + 2. Give a fraction or decimal.","answer":-0.3333333333,"hint":"For non-zero gradients, the perpendicular gradient is the negative reciprocal.","solution":"The negative reciprocal of 3 is −1/3.","id":"x051-02","subject":"maths","topic":"Perpendicular lines","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A line passes through (1, 5) and (3, 9). Write it as y = mx + c. Find c.","answer":3,"hint":"Find the gradient from the two points, then substitute a point.","solution":"m = (9 − 5)/2 = 2. Then c = 5 − 2 = 3.","id":"x052-02","subject":"maths","topic":"Equation of a line through points","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"A pack of 5 notebooks costs £15. Find the price per notebook in pounds.","answer":3,"hint":"Divide cost by number of items.","solution":"£15 ÷ 5 = £3 per notebook.","id":"x053-02","subject":"maths","topic":"Best buys and unit pricing","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"£1 exchanges for €1.20. How many euros are exchanged for £50?","answer":60,"hint":"Multiply the pound amount by the euros-per-pound rate.","solution":"50 × 1.20 = €60.","id":"x054-02","subject":"maths","topic":"Currency conversion","group":"Proportion and rates","tier":"Both","calculator":true,"marks":2},{"prompt":"A recipe for 4 people uses 120 g of rice. How many grams are needed for 6 people?","answer":180.0,"hint":"Scale every ingredient by 6/4.","solution":"120 × 6/4 = 180.0 g.","id":"x055-02","subject":"maths","topic":"Scaling recipes","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"A map has scale 1:50 000. Two places are 2 cm apart on the map. Find their real distance in kilometres.","answer":1.0,"hint":"Convert the scaled centimetres into kilometres using 100 000 cm = 1 km.","solution":"2 × 50 000 = 100000 cm = 1.0 km.","id":"x056-02","subject":"maths","topic":"Map scales","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is directly proportional to x. When x = 3, y = 9. Find y when x = 8.","answer":24,"hint":"Find k in y = kx.","solution":"k = 9/3 = 3; hence y = 3 × 8 = 24.","id":"x057-02","subject":"maths","topic":"Direct proportion","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is inversely proportional to x. When x = 2, y = 12. Find y when x = 3.","answer":8,"hint":"The product xy stays constant.","solution":"k = 2 × 12 = 24. Thus y = 24/3 = 8.","id":"x058-02","subject":"maths","topic":"Inverse proportion","group":"Proportion and rates","tier":"Higher","calculator":false,"marks":2},{"prompt":"£200 earns 5% compound interest each year. Find the balance after 2 years in pounds.","answer":220.5,"hint":"Multiply by 1.05 for each year.","solution":"£200 × 1.05² = £220.50.","id":"x059-02","subject":"maths","topic":"Compound interest","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A bicycle worth £500 loses 20% of its value each year. Find its value after 2 years in pounds.","answer":320,"hint":"Retain 80% each year, using the multiplier 0.8 twice.","solution":"£500 × 0.8² = £320.","id":"x060-02","subject":"maths","topic":"Depreciation","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A culture begins with 400 cells and increases by 10% each hour. Find the modelled count after 2 hours.","answer":484,"hint":"Use the growth multiplier 1.1 twice.","solution":"400 × 1.1² = 484 cells.","id":"x061-02","subject":"maths","topic":"Repeated percentage growth","group":"Finance","tier":"Both","calculator":true,"marks":2},{"prompt":"A block has mass 72 g and volume 24 cm³. Find its density in g/cm³.","answer":3,"hint":"Density = mass ÷ volume.","solution":"72 ÷ 24 = 3 g/cm³.","id":"x062-02","subject":"maths","topic":"Density","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A force of 120 N acts on an area of 6 m². Find pressure in N/m².","answer":20,"hint":"Pressure = force ÷ area.","solution":"120 ÷ 6 = 20 N/m².","id":"x063-02","subject":"maths","topic":"Pressure","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"Convert 3 m² into cm².","answer":30000,"hint":"Square the linear conversion: 1 m = 100 cm.","solution":"1 m² = 100² = 10 000 cm². Therefore 3 m² = 30000 cm².","id":"x064-02","subject":"maths","topic":"Metric area conversions","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A journey starts at 09:12 and ends at 11:45. Find its duration in minutes.","answer":153,"hint":"Count the full hours and the remaining minutes.","solution":"From 09:12 to 11:12 is 120 minutes, then another 33. Total = 153 minutes.","id":"x065-02","subject":"maths","topic":"Time calculations","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle is 10 cm by 6 cm. A 2 cm by 2 cm square is cut from one corner. Find the perimeter of the remaining L-shape in cm.","answer":32,"hint":"The two removed edge lengths are replaced by two equal inner edge lengths.","solution":"The perimeter stays equal to the original rectangle: 2(10 + 6) = 32 cm.","id":"x066-02","subject":"maths","topic":"Perimeter of compound shapes","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 3 cm. Express its circumference as kπ cm. Find k.","answer":6,"hint":"Circumference is 2πr.","solution":"2π × 3 = 6π cm.","id":"x067-02","subject":"maths","topic":"Circle circumference","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 4 cm. Its area is kπ cm². Find k.","answer":16,"hint":"Square the radius and multiply by π.","solution":"Area = π × 4² = 16π cm².","id":"x068-02","subject":"maths","topic":"Area of circles","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A semicircle has radius 4 cm. Its perimeter is πr + d. Find the straight-edge length d in cm.","answer":8,"hint":"The straight edge is the diameter, not the radius.","solution":"d = 2r = 2 × 4 = 8 cm. The complete perimeter is 4π + 8 cm.","id":"x069-02","subject":"maths","topic":"Semicircle perimeter","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 60° and radius 6 cm. Its arc length is kπ cm. Find k.","answer":2,"hint":"Take 60/360 of the circumference.","solution":"(60/360) × 2π × 6 = 2π cm.","id":"x070-02","subject":"maths","topic":"Arc length","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 90° and radius 4 cm. Its area is kπ cm². Find k.","answer":4,"hint":"Take one quarter of the full circle area.","solution":"(90/360) × π × 4² = 4π cm².","id":"x071-02","subject":"maths","topic":"Sector area","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A triangular prism has triangular cross-section base 4 cm, height 6 cm, and prism length 10 cm. Find its volume in cm³.","answer":120,"hint":"Find the triangle area, then multiply by the prism length.","solution":"Cross-section = ½ × 4 × 6 = 12 cm². Volume = 120 cm³.","id":"x072-02","subject":"maths","topic":"Volume of prisms","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A cylinder has radius 3 cm and height 5 cm. Its volume is kπ cm³. Find k.","answer":45,"hint":"Multiply the circular base area by the height.","solution":"πr²h = π × 3² × 5 = 45π cm³.","id":"x073-02","subject":"maths","topic":"Volume of cylinders","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A cone has radius 3 cm and perpendicular height 9 cm. Its volume is kπ cm³. Find k.","answer":27,"hint":"A cone has one third of the corresponding cylinder volume.","solution":"V = πr²h/3 = π × 3² × 9/3 = 27π cm³.","id":"x074-02","subject":"maths","topic":"Volume of cones","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sphere has radius 6 cm. Its volume is kπ cm³. Find k.","answer":288,"hint":"Use V = 4πr³/3.","solution":"(4/3) × 6³ = 288, so V = 288π cm³.","id":"x075-02","subject":"maths","topic":"Volume of spheres","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A cuboid measures 3 cm by 3 cm by 4 cm. Find its total surface area in cm².","answer":66,"hint":"There are two faces of each of the three different rectangular areas.","solution":"2[3(3) + 4(3) + 3×4] = 66 cm².","id":"x076-02","subject":"maths","topic":"Surface area of cuboids","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A closed cylinder has radius 3 cm and height 4 cm. Its total surface area is kπ cm². Find k.","answer":42,"hint":"Include two circular ends and the curved surface.","solution":"2r² + 2rh = 2(3²) + 2(3)(4) = 42.","id":"x077-02","subject":"maths","topic":"Cylinder surface area","group":"Geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"Two similar shapes have length scale factor 3 from small to large. A small side is 4 cm. Find the matching large side.","answer":12,"hint":"Multiply corresponding lengths by the length scale factor.","solution":"4 × 3 = 12 cm.","id":"x078-02","subject":"maths","topic":"Similarity of lengths","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Two similar shapes have length scale factor 2. The smaller area is 5 cm². Find the larger area.","answer":20,"hint":"Square the length scale factor for areas.","solution":"Area factor = 2² = 4. Larger area = 5 × 4 = 20 cm².","id":"x079-02","subject":"maths","topic":"Similarity of areas","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"Two similar solids have length scale factor 3. The smaller volume is 3 cm³. Find the larger volume.","answer":81,"hint":"Cube the length scale factor for volumes.","solution":"Volume factor = 3³ = 27. Larger volume = 81 cm³.","id":"x080-02","subject":"maths","topic":"Similarity of volumes","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A triangle has two angles 42° and 62°. Find the third angle in degrees.","answer":76,"hint":"Interior angles in a triangle total 180°.","solution":"180 − 42 − 62 = 76°.","id":"x081-02","subject":"maths","topic":"Triangle angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A regular polygon has 6 sides. Find its exterior angle in degrees, to 3 decimal places if needed.","answer":60.0,"hint":"The exterior angles total 360°.","solution":"Each exterior angle is 360/6 = 60.000°.","id":"x082-02","subject":"maths","topic":"Exterior angles of polygons","group":"Geometry","tier":"Both","calculator":true,"marks":2},{"prompt":"A transversal crosses two parallel lines. One of a pair of co-interior angles is 66°. Find the other angle in degrees.","answer":114,"hint":"Co-interior angles on parallel lines sum to 180°.","solution":"180 − 66 = 114°.","id":"x083-02","subject":"maths","topic":"Angles in parallel lines","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the sum of the interior angles of a polygon with 5 sides.","answer":540,"hint":"Use (number of sides − 2) × 180°.","solution":"(5 − 2) × 180 = 540°.","id":"x084-02","subject":"maths","topic":"Polygon interior-angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"The bearing of B from A is 030°. Find the bearing of A from B as a number of degrees.","answer":210,"hint":"A reverse bearing differs by 180°.","solution":"30 + 180 = 210°.","id":"x085-02","subject":"maths","topic":"Three-figure bearings","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A right-angled triangle has hypotenuse 8 cm and an angle of 30°. Find the side opposite that angle in cm.","answer":4,"hint":"Use sin(angle) = opposite/hypotenuse.","solution":"Opposite = 8 × sin30° = 4 cm.","id":"x086-02","subject":"maths","topic":"Right-angle trigonometry","group":"Trigonometry","tier":"Both","calculator":true,"marks":3},{"prompt":"In a triangle, side a = 4 cm is opposite 30°, and side b is opposite 90°. Find b in cm.","answer":8,"hint":"Use a/sin A = b/sin B.","solution":"b = 4 × sin90°/sin30° = 8 cm.","id":"x087-02","subject":"maths","topic":"Sine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides of a triangle are 4 cm each, with included angle 60°. Find the opposite side in cm.","answer":4,"hint":"Use c² = a² + b² − 2ab cos C.","solution":"c² = 2(4²) − 2(4²)cos60° = 16, so c = 4 cm.","id":"x088-02","subject":"maths","topic":"Cosine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides are 4 cm and 8 cm, with included angle 30°. Find the triangle area in cm².","answer":8,"hint":"Use area = ½ab sin C.","solution":"½ × 4 × 8 × sin30° = 8 cm².","id":"x089-02","subject":"maths","topic":"Triangle area using sine","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"An angle at the circumference is 22°. The central angle subtended by the same arc is less than 180°. Find it.","answer":44,"hint":"The angle at the centre is twice the angle at the circumference on the same arc.","solution":"2 × 22 = 44°.","id":"x090-02","subject":"maths","topic":"Angles at the centre","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"One angle of a cyclic quadrilateral is 94°. Find its opposite angle.","answer":86,"hint":"Opposite angles in a cyclic quadrilateral total 180°.","solution":"180 − 94 = 86°.","id":"x091-02","subject":"maths","topic":"Cyclic quadrilaterals","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"A tangent and chord form an angle of 29°. Find the angle subtended by that chord in the alternate segment.","answer":29,"hint":"The tangent-chord angle equals the angle in the alternate segment.","solution":"By the alternate segment theorem, the required angle is 29°.","id":"x092-02","subject":"maths","topic":"Alternate segment theorem","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"Vectors a = (2, 3) and b = (4, −1). Find the x-component of a + b.","answer":6,"hint":"Add corresponding components.","solution":"a + b = (6, 2), so the x-component is 6.","id":"x093-02","subject":"maths","topic":"Adding vectors","group":"Vectors","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the magnitude of the vector (6, 8).","answer":10,"hint":"Use Pythagoras on the two components.","solution":"√(6² + 8²) = 10.","id":"x094-02","subject":"maths","topic":"Vector magnitude","group":"Vectors","tier":"Higher","calculator":true,"marks":2},{"prompt":"Rotate (2, 4) by 90° anticlockwise about the origin. Find the new x-coordinate.","answer":-4,"hint":"The rule for 90° anticlockwise is (x,y) → (−y,x).","solution":"The image is (−4, 2), so its x-coordinate is −4.","id":"x095-02","subject":"maths","topic":"Rotations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Enlarge (2, 2) by scale factor 3 about the origin. Find the new x-coordinate.","answer":6,"hint":"Multiply both coordinates by the scale factor.","solution":"The image is (6, 6).","id":"x096-02","subject":"maths","topic":"Enlargements","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Translate (2, 4) by the vector (−3, 2). Find the new x-coordinate.","answer":-1,"hint":"Add the x-component of the vector to the x-coordinate.","solution":"The image is (-1, 6).","id":"x097-02","subject":"maths","topic":"Translations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Reflect (2, 5) in the line y = x. Find the new x-coordinate.","answer":5,"hint":"Reflection in y = x swaps the coordinates.","solution":"The image is (5, 2).","id":"x098-02","subject":"maths","topic":"Reflections","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Points must be exactly 4 cm from a fixed point P. What is their locus?","kind":"choice","options":["A straight line through P","A perpendicular bisector through P","A circle centred at P with radius 4 cm","A circle centred at P with diameter 4 cm"],"correct":2,"answer":null,"hint":"A fixed distance from one point defines a circle.","solution":"All points on a circle of radius 4 cm are exactly 4 cm from its centre P.","id":"x099-02","subject":"maths","topic":"Loci and constructions","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the median of 9, 2, 5, 11, 3.","answer":5,"hint":"Order the values, then choose the middle one.","solution":"The ordered list is 2, 3, 5, 9, 11. Its middle value is 5.","id":"x100-02","subject":"maths","topic":"Finding the median","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the mode of 2, 4, 4, 6, 4, 8.","answer":4,"hint":"Look for the value occurring most frequently.","solution":"4 occurs three times; every other value occurs once.","id":"x101-02","subject":"maths","topic":"Finding the mode","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the range of −2, 2, 6, 0.","answer":8,"hint":"Subtract the minimum from the maximum.","solution":"6 − (−2) = 8.","id":"x102-02","subject":"maths","topic":"Finding the range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A data set has lower quartile 5 and upper quartile 15. Find its interquartile range.","answer":10,"hint":"IQR = upper quartile − lower quartile.","solution":"15 − 5 = 10.","id":"x103-02","subject":"maths","topic":"Interquartile range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A grouped table has 2 values in 0 ≤ x < 10 and 4 values in 10 ≤ x < 20. Estimate the mean, to 3 decimal places.","answer":11.667,"hint":"Use class midpoints 5 and 15, multiply by frequencies, then divide by total frequency.","solution":"Estimated total = 2×5 + 4×15 = 70. Divide by 6 to get 11.667.","id":"x104-02","subject":"maths","topic":"Estimated mean from grouped data","group":"Statistics","tier":"Both","calculator":true,"marks":3},{"prompt":"A histogram class has width 5 and frequency 20. Find its frequency density.","answer":4,"hint":"Frequency density = frequency ÷ class width.","solution":"20 ÷ 5 = 4.","id":"x105-02","subject":"maths","topic":"Frequency density","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"Class frequencies, in ascending order, are 2, 4, 6, 8. Find the cumulative frequency at the end of the third class.","answer":12,"hint":"Add all frequencies up to and including the third class.","solution":"2 + 4 + 6 = 12.","id":"x106-02","subject":"maths","topic":"Cumulative frequency","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A box plot has minimum 2, lower quartile 5, median 8, upper quartile 11, maximum 17. Read off its median.","answer":8,"hint":"The median is the line inside the box.","solution":"The median line is at 8. The ends of the box are the quartiles.","id":"x107-02","subject":"maths","topic":"Box plots","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A school has 600 pupils; 60 are in a chosen group. In a proportional sample of 40 pupils, how many should come from that group?","answer":4,"hint":"Multiply the sample size by the group proportion.","solution":"40 × 60/600 = 4 pupils.","id":"x108-02","subject":"maths","topic":"Stratified sampling","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"An experiment succeeds 5 times out of 20 trials. Find the relative frequency as a fraction or decimal.","answer":0.25,"hint":"Divide the number of successes by the number of trials.","solution":"Relative frequency = 5/20 = 0.25.","id":"x109-02","subject":"maths","topic":"Relative frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"An event has probability 0.3. It is tested 40 times. Find its expected frequency.","answer":12,"hint":"Multiply probability by number of trials.","solution":"0.3 × 40 = 12. This is an expectation, not a guarantee.","id":"x110-02","subject":"maths","topic":"Expected frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Two independent events have probabilities 1/2 and 2/12. Find the probability that both occur.","answer":0.0833333333,"hint":"Multiply the probabilities of independent events.","solution":"1/2 × 2/12 = 2/24.","id":"x111-02","subject":"maths","topic":"Independent events","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A bag has 4 red counters and 3 blue counters. Two counters are drawn without replacement. Find P(both red), to 3 decimal places.","answer":0.286,"hint":"The second draw has one fewer red counter and one fewer counter altogether.","solution":"P = (4/7) × (3/6) = 0.286.","id":"x112-02","subject":"maths","topic":"Sampling without replacement","group":"Probability","tier":"Higher","calculator":true,"marks":3},{"prompt":"Of 7 club members who play tennis, 2 also swim. A member is chosen from the tennis players only. Find P(swims), as a fraction or decimal.","answer":0.2857142857,"hint":"Use the restricted tennis group as the denominator.","solution":"Given that the person plays tennis, P(swims) = 2/7.","id":"x113-02","subject":"maths","topic":"Conditional probability","group":"Probability","tier":"Higher","calculator":false,"marks":2},{"prompt":"Set A contains 14 people including 4 in A ∩ B. How many are in A only?","answer":10,"hint":"Subtract the intersection from the total in A.","solution":"14 − 4 = 10 people.","id":"x114-02","subject":"maths","topic":"Venn diagram regions","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"n(A) = 12, n(B) = 14, and n(A ∩ B) = 5. Find n(A ∪ B).","answer":21,"hint":"Add the two set sizes and subtract the overlap once.","solution":"12 + 14 − 5 = 21.","id":"x115-02","subject":"maths","topic":"Set union","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A fair coin is tossed, then a fair 5-sided die numbered 1 to 5 is rolled. Find P(heads and a 1).","answer":0.1,"hint":"Multiply the branch probabilities along the path.","solution":"(1/2) × (1/5) = 1/10.","id":"x116-02","subject":"maths","topic":"Tree diagrams","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Plot the listed points for y = x³ − 3. Use x = -2, -1, 0, 1, 2. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[-2,-11],[-1,-4],[0,-3],[1,-2],[2,5]],"curve":"quadratic","range":[-3,3,-14,14],"expression":"y = x³ − 3","hint":"Cube each x, preserving its sign, then add the constant.","solution":"The coordinates are (-2, -11), (-1, -4), (0, -3), (1, -2), (2, 5). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x117-02","subject":"maths","topic":"Cubic graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 12/x + 1 for 1 ≤ x ≤ 6. Use x = 1, 2, 3, 4, 6. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[1,13.0],[2,7.0],[3,5.0],[4,4.0],[6,3.0]],"curve":"quadratic","range":[0,7,0,23],"expression":"y = 12/x + 1 for 1 ≤ x ≤ 6","hint":"Divide 12 by x, then add the constant; x = 0 is not allowed.","solution":"The coordinates are (1, 13.0), (2, 7.0), (3, 5.0), (4, 4.0), (6, 3.0). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x118-02","subject":"maths","topic":"Reciprocal graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 2^x + 1. Use x = 0, 1, 2, 3. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[0,2],[1,3],[2,5],[3,9]],"curve":"quadratic","range":[-1,4,0,18],"expression":"y = 2^x + 1","hint":"Calculate the power of 2 first, then add the constant.","solution":"The coordinates are (0, 2), (1, 3), (2, 5), (3, 9). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x119-02","subject":"maths","topic":"Exponential graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"The graph y = x² is translated upward by 4 units. Find the new y-coordinate of its turning point.","answer":4,"hint":"An upward translation adds the same amount to every y-coordinate.","solution":"The old turning point is (0, 0); the new one is (0, 4).","id":"x120-02","subject":"maths","topic":"Translating graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A straight segment on a distance-time graph runs from (0 hours, 0 km) to (2 hours, 24 km). Find the speed in km/h.","answer":12,"hint":"Speed is the gradient: distance change divided by time change.","solution":"24 km ÷ 2 h = 12 km/h.","id":"x121-02","subject":"maths","topic":"Distance-time graphs","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A velocity-time graph rises in a straight line from 0 m/s to 10 m/s in 5 seconds. Find acceleration in m/s².","answer":2,"hint":"Acceleration is change in velocity divided by time.","solution":"(10 − 0)/5 = 2 m/s².","id":"x122-02","subject":"maths","topic":"Velocity-time gradients","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A tangent to a curve passes through (1, 2) and (3, 8). Estimate the gradient of the curve at the contact point.","answer":3,"hint":"Use the gradient of the tangent, not a chord through two curve points.","solution":"(8 − 2)/(3 − 1) = 3.","id":"x123-02","subject":"maths","topic":"Tangents and rates of change","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A velocity-time graph forms a triangle with base 6 seconds and maximum velocity 4 m/s. Find the displacement in metres.","answer":12,"hint":"Displacement is the signed area under a velocity-time graph.","solution":"Area = ½ × 6 × 4 = 12 m.","id":"x124-02","subject":"maths","topic":"Area under velocity-time graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"The lines y = x + 2 and y = 3x intersect. Find the x-coordinate of the intersection.","answer":1.0,"hint":"At the intersection, both expressions for y are equal.","solution":"x + 2 = 3x, so 2x = 2 and x = 1.0.","id":"x125-02","subject":"maths","topic":"Graphical simultaneous equations","group":"Graphs","tier":"Both","calculator":false,"marks":3},{"prompt":"Which point satisfies both x > 2 and y < 3?","kind":"choice","options":["(3, 4)","(1, 0)","(3, 2)","(2, 2)"],"correct":2,"answer":null,"hint":"Test both strict inequalities for each coordinate pair.","solution":"Only (3, 2) has x strictly greater than 2 and y strictly less than 3.","id":"x126-02","subject":"maths","topic":"Regions satisfying inequalities","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate 6 + 5 × 4.","answer":26,"hint":"Do multiplication before addition.","solution":"5 × 4 = 20; then add 6 to get 26.","id":"x001-03","subject":"maths","topic":"Order of operations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"The temperature is −5°C. It falls by 7°C. What is the new temperature in °C?","answer":-12,"hint":"A fall makes the number more negative.","solution":"−5 − 7 = −12°C.","id":"x002-03","subject":"maths","topic":"Calculating with negatives","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the value of the hundreds digit in 1403?","answer":400,"hint":"Identify the digit three places from the right.","solution":"The hundreds digit is 4, so its value is 4 × 100 = 400.","id":"x003-03","subject":"maths","topic":"Place value","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 5.376 to two decimal places.","answer":5.38,"hint":"Look at the third decimal digit.","solution":"The third digit is 6, so round the hundredths up: 5.38.","id":"x004-03","subject":"maths","topic":"Rounding decimal places","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 2185 to two significant figures.","answer":2200,"hint":"Count significant digits from the first non-zero digit.","solution":"The first two significant figures are in the thousands and hundreds columns. Rounding 2185 to the nearest 100 gives 2200.","id":"x005-03","subject":"maths","topic":"Significant figures","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Estimate 5.9 × 19.8 by rounding each number to the nearest whole number first.","answer":120,"hint":"Follow the requested rounding method for both numbers.","solution":"5.9 rounds to 6; 19.8 rounds to 20. The estimate is 120.","id":"x006-03","subject":"maths","topic":"Estimating calculations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"How many positive factors does 16 have?","answer":5,"hint":"For a power of 2, list 2⁰ up to the highest power.","solution":"16 = 2^4. Its factors are 2⁰ through 2^4, giving 5 factors.","id":"x007-03","subject":"maths","topic":"Factors","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the smallest multiple of 6 that is strictly greater than 60?","answer":66,"hint":"The number given is already the tenth multiple.","solution":"The next multiple is 11 × 6 = 66.","id":"x008-03","subject":"maths","topic":"Multiples","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Which number in this list is prime? Set 3.","kind":"choice","options":["45","17","24","30"],"correct":1,"answer":null,"hint":"A prime has exactly two positive factors: 1 and itself.","solution":"17 has no positive factors except 1 and itself. The other numbers have explicit factors 4, 6 or 9.","id":"x009-03","subject":"maths","topic":"Prime numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"In the prime factorisation of 72, what is the exponent of 2?","answer":3,"hint":"Keep dividing by 2 until the remaining number is odd.","solution":"72 = 2^3 × 3², so the exponent is 3.","id":"x010-03","subject":"maths","topic":"Prime factorisation","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the highest common factor of 36 and 54.","answer":18,"hint":"Look for the largest factor that divides both numbers.","solution":"36 = 2 × 18 and 54 = 3 × 18. Since 2 and 3 are coprime, the HCF is 18.","id":"x011-03","subject":"maths","topic":"Highest common factor","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the lowest common multiple of 12 and 18.","answer":36,"hint":"Find the HCF first, or list the multiples.","solution":"The HCF is 6. LCM = (12 × 18) ÷ 6 = 36.","id":"x012-03","subject":"maths","topic":"Lowest common multiple","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 3/12 + 1/8. Give a fraction or decimal.","answer":0.375,"hint":"Use a common denominator of 24.","solution":"3/12 = 6/24 and 1/8 = 3/24. The sum is 9/24.","id":"x013-03","subject":"maths","topic":"Adding fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 3/11 × 3/5. Give a fraction or decimal.","answer":0.1636363636,"hint":"Multiply numerators and denominators.","solution":"(3 × 3)/(11 × 5) = 9/55. Simplify if possible.","id":"x014-03","subject":"maths","topic":"Multiplying fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 3/12 ÷ 5/6. Give a fraction or decimal.","answer":0.3,"hint":"Multiply by the reciprocal of 5/6.","solution":"3/12 × 6/5 = 18/60 = 3/10.","id":"x015-03","subject":"maths","topic":"Dividing fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 3 3/4 as a decimal.","answer":3.75,"hint":"The fraction part is three quarters, or 0.75.","solution":"3 + 0.75 = 3.75.","id":"x016-03","subject":"maths","topic":"Mixed numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A club has 72 members. Three eighths cycle to the club. How many members cycle?","answer":27,"hint":"Divide by 8 to find one eighth, then multiply by 3.","solution":"72 ÷ 8 × 3 = 27.","id":"x017-03","subject":"maths","topic":"Fractions of quantities","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 0.131313… (the block 13 repeats) as a fraction or decimal.","answer":0.1313131313,"hint":"For a two-digit repeating block, compare 100x with x.","solution":"If x = 0.1313…, then 100x − x = 13; hence x = 13/99.","id":"x018-03","subject":"maths","topic":"Recurring decimals","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Simplify 3^4 × 3^6 to 3^k. Find k.","answer":10,"hint":"Add exponents when multiplying powers of the same base.","solution":"k = 4 + 6 = 10.","id":"x019-03","subject":"maths","topic":"Index laws","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Evaluate 4^−2. Give a fraction or decimal.","answer":0.0625,"hint":"A negative exponent gives the reciprocal of the positive power.","solution":"4^−2 = 1/(4²) = 1/16.","id":"x020-03","subject":"maths","topic":"Negative indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Evaluate 125^(2/3).","answer":25,"hint":"Take the cube root, then square the result.","solution":"The cube root of 125 is 5; its square is 25.","id":"x021-03","subject":"maths","topic":"Fractional indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write √32 in the form a√2. Find a.","answer":4,"hint":"Look for a square factor inside the root.","solution":"√(16 × 2) = 4√2, so a = 4.","id":"x022-03","subject":"maths","topic":"Simplifying surds","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write 9/√3 in the form a√3. Find a.","answer":3,"hint":"Multiply numerator and denominator by √3.","solution":"(9√3)/3 = 3√3.","id":"x023-03","subject":"maths","topic":"Rationalising denominators","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate (2 × 10^3) × (3 × 10²). Write the result as 6 × 10^k. Find k.","answer":5,"hint":"Multiply the coefficients and add powers of ten.","solution":"2 × 3 = 6 and 3 + 2 = 5, so k = 5.","id":"x024-03","subject":"maths","topic":"Calculating in standard form","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A length is 13 cm to the nearest centimetre. Give the lower bound in cm.","answer":12.5,"hint":"The rounding interval extends half a centimetre either side.","solution":"The lower bound is 13 − 0.5 = 12.5 cm; the upper bound is 13.5 cm and is excluded.","id":"x025-03","subject":"maths","topic":"Error intervals","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle has length 13 cm and width 7 cm, both to the nearest centimetre. Find the upper bound for its area in cm².","answer":101.25,"hint":"Use the upper bound for each positive length.","solution":"Upper area bound = 13.5 × 7.5 = 101.25 cm².","id":"x026-03","subject":"maths","topic":"Upper and lower bounds","group":"Number","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify 5x + 7x − 3x to ax. Find a.","answer":9,"hint":"Combine only the coefficients of x.","solution":"a = 5 + 7 − 3 = 9.","id":"x027-03","subject":"maths","topic":"Collecting like terms","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand 5(x + 4). What is the constant term?","answer":20,"hint":"Multiply both terms inside the bracket.","solution":"The expansion is 5x + 20.","id":"x028-03","subject":"maths","topic":"Expanding a single bracket","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand (x + 3)(x + 6). What is the coefficient of x?","answer":9,"hint":"Multiply every term in one bracket by every term in the other.","solution":"x² + 6x + 3x + 18 = x² + 9x + 18.","id":"x029-03","subject":"maths","topic":"Expanding double brackets","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise fully 6x + 18.","kind":"choice","options":["18(x + 2)","6(x + 3)","6(x + 6)","3(x + 3)"],"correct":1,"answer":null,"hint":"Take out the highest common factor of the two coefficients.","solution":"Both terms contain 6. Dividing gives x and 3, so the result is 6(x + 3).","id":"x030-03","subject":"maths","topic":"Factorising with a common factor","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise x² + 9x + 18.","kind":"choice","options":["(x − 3)(x + 6)","(x + 3)(x + 6)","(x − 3)(x − 6)","(x + 4)(x + 5)"],"correct":1,"answer":null,"hint":"Find two numbers whose product is the constant and whose sum is the x coefficient.","solution":"3 × 6 = 18 and 3 + 6 = 9.","id":"x031-03","subject":"maths","topic":"Factorising quadratics","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Find 2a² − b when a = 3 and b = 6.","answer":12,"hint":"Square a before multiplying by 2.","solution":"2 × 3² − 6 = 12.","id":"x032-03","subject":"maths","topic":"Substitution","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The formula is y = 5x − 3. If y = 17, find x.","answer":4,"hint":"Add the constant to y, then divide by the coefficient of x.","solution":"x = (y + 3)/5 = 20/5 = 4.","id":"x033-03","subject":"maths","topic":"Changing the subject","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the smallest integer satisfying 3x + 3 > 12.","answer":4,"hint":"Subtract the constant, divide by 3, then respect the strict inequality.","solution":"3x > 9, so x > 3. The smallest integer is 4.","id":"x034-03","subject":"maths","topic":"Linear inequalities","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Solve x + y = 10 and x − y = 4. Give x.","answer":7,"hint":"Add the two equations to eliminate y.","solution":"2x = 14, so x = 7.","id":"x035-03","subject":"maths","topic":"Simultaneous linear equations","group":"Algebra","tier":"Both","calculator":false,"marks":3},{"prompt":"The graphs y = x² and y = 9 meet. Give the positive x-coordinate.","answer":3,"hint":"Substitute to obtain x² equal to the constant.","solution":"x² = 9, so x = ±3. The positive value is 3.","id":"x036-03","subject":"maths","topic":"Simultaneous nonlinear equations","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"Write x² + 6x + 14 as (x + a)² + b. Find b.","answer":5,"hint":"Half the x coefficient gives a. Subtract a² from the constant.","solution":"a = 3. Subtract 9 from the constant 14 to get b = 5.","id":"x037-03","subject":"maths","topic":"Completing the square","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Use the quadratic formula to find the positive root of x² + x − 12 = 0.","answer":3,"hint":"Identify a, b and c. Use x = (−b ± √(b² − 4ac))/(2a).","solution":"a=1, b=1, c=−12. The discriminant is 1 + 48 = 49. The positive root is (−1 + 7)/2 = 3.","id":"x038-03","subject":"maths","topic":"Quadratic formula","group":"Algebra","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify (5x)/(10x²) for x ≠ 0, then evaluate at x = 3.","answer":0.1666666667,"hint":"Cancel the common numerical factor and one factor of x.","solution":"The expression simplifies to 1/(2x). At x = 3, it is 1/6.","id":"x039-03","subject":"maths","topic":"Algebraic fractions","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"The difference (k + 1)² − k² simplifies to 2k + 1. Use this identity to find the difference between the squares of 7 and 8.","answer":15,"hint":"Expand the square before cancelling k².","solution":"Expanding proves (k + 1)² − k² = 2k + 1. Set k = 7: the difference is 15.","id":"x040-03","subject":"maths","topic":"Algebraic proof","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x − 3. Find f(5).","answer":12,"hint":"Replace every x with the specified input.","solution":"f(5) = 3(5) − 3 = 12.","id":"x041-03","subject":"maths","topic":"Function notation","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"f(x) = 2x + 1 and g(x) = x². Find f(g(3)).","answer":19,"hint":"Apply the inside function first.","solution":"g(3) = 9; f(9) = 19.","id":"x042-03","subject":"maths","topic":"Composite functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x + 3. Find f⁻¹(12).","answer":3,"hint":"Undo the addition, then undo the multiplication.","solution":"f⁻¹(y) = (y − 3)/3. With y = 12, this gives 3.","id":"x043-03","subject":"maths","topic":"Inverse functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"x₀ = 3. Use x_(k+1) = (x_k + 4)/2 to calculate x₂.","answer":3.75,"hint":"Calculate x₁ first and substitute that new value again.","solution":"x₁ = (3 + 4)/2 = 3.5. Then x₂ = (3.5 + 4)/2 = 3.75.","id":"x044-03","subject":"maths","topic":"Iteration","group":"Algebra","tier":"Higher","calculator":true,"marks":2},{"prompt":"A geometric sequence starts at 4 and has common ratio 3. Find its fourth term.","answer":108,"hint":"Multiply by 3 three times after the first term.","solution":"The fourth term is 4 × 3³ = 108.","id":"x045-03","subject":"maths","topic":"Geometric sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The nth term is n² + 3n + 2. Find the fifth term.","answer":42,"hint":"Replace each occurrence of n (the position variable) with 5.","solution":"5² + 3 × 5 + 2 = 42.","id":"x046-03","subject":"maths","topic":"Quadratic sequences","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sequence begins 3, 4. Each new term is the sum of the preceding two. Find the fifth term.","answer":18,"hint":"Build the third and fourth terms before the fifth.","solution":"The terms are 3, 4, 7, 11, 18.","id":"x047-03","subject":"maths","topic":"Fibonacci-type sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the x-coordinate of the midpoint of (3, 2) and (11, 8).","answer":7,"hint":"Average the two x-coordinates.","solution":"(3 + 11)/2 = 7. The full midpoint is (7, 5).","id":"x048-03","subject":"maths","topic":"Midpoints","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the distance between (0, 0) and (9, 12).","answer":15,"hint":"Use the horizontal and vertical differences in Pythagoras.","solution":"√(9² + 12²) = 15 units.","id":"x049-03","subject":"maths","topic":"Distance between coordinates","group":"Coordinate geometry","tier":"Both","calculator":true,"marks":3},{"prompt":"A line is parallel to y = 4x − 4 and passes through (0, 3). Give its gradient.","answer":4,"hint":"Parallel non-vertical lines have equal gradients.","solution":"The given line has gradient 4, so the parallel line does too.","id":"x050-03","subject":"maths","topic":"Parallel lines","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the gradient of a line perpendicular to y = 4x + 2. Give a fraction or decimal.","answer":-0.25,"hint":"For non-zero gradients, the perpendicular gradient is the negative reciprocal.","solution":"The negative reciprocal of 4 is −1/4.","id":"x051-03","subject":"maths","topic":"Perpendicular lines","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A line passes through (1, 7) and (3, 13). Write it as y = mx + c. Find c.","answer":4,"hint":"Find the gradient from the two points, then substitute a point.","solution":"m = (13 − 7)/2 = 3. Then c = 7 − 3 = 4.","id":"x052-03","subject":"maths","topic":"Equation of a line through points","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"A pack of 6 notebooks costs £24. Find the price per notebook in pounds.","answer":4,"hint":"Divide cost by number of items.","solution":"£24 ÷ 6 = £4 per notebook.","id":"x053-03","subject":"maths","topic":"Best buys and unit pricing","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"£1 exchanges for €1.20. How many euros are exchanged for £75?","answer":90,"hint":"Multiply the pound amount by the euros-per-pound rate.","solution":"75 × 1.20 = €90.","id":"x054-03","subject":"maths","topic":"Currency conversion","group":"Proportion and rates","tier":"Both","calculator":true,"marks":2},{"prompt":"A recipe for 4 people uses 140 g of rice. How many grams are needed for 6 people?","answer":210.0,"hint":"Scale every ingredient by 6/4.","solution":"140 × 6/4 = 210.0 g.","id":"x055-03","subject":"maths","topic":"Scaling recipes","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"A map has scale 1:50 000. Two places are 3 cm apart on the map. Find their real distance in kilometres.","answer":1.5,"hint":"Convert the scaled centimetres into kilometres using 100 000 cm = 1 km.","solution":"3 × 50 000 = 150000 cm = 1.5 km.","id":"x056-03","subject":"maths","topic":"Map scales","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is directly proportional to x. When x = 3, y = 12. Find y when x = 8.","answer":32,"hint":"Find k in y = kx.","solution":"k = 12/3 = 4; hence y = 4 × 8 = 32.","id":"x057-03","subject":"maths","topic":"Direct proportion","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is inversely proportional to x. When x = 2, y = 18. Find y when x = 3.","answer":12,"hint":"The product xy stays constant.","solution":"k = 2 × 18 = 36. Thus y = 36/3 = 12.","id":"x058-03","subject":"maths","topic":"Inverse proportion","group":"Proportion and rates","tier":"Higher","calculator":false,"marks":2},{"prompt":"£300 earns 5% compound interest each year. Find the balance after 2 years in pounds.","answer":330.75,"hint":"Multiply by 1.05 for each year.","solution":"£300 × 1.05² = £330.75.","id":"x059-03","subject":"maths","topic":"Compound interest","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A bicycle worth £750 loses 20% of its value each year. Find its value after 2 years in pounds.","answer":480,"hint":"Retain 80% each year, using the multiplier 0.8 twice.","solution":"£750 × 0.8² = £480.","id":"x060-03","subject":"maths","topic":"Depreciation","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A culture begins with 600 cells and increases by 10% each hour. Find the modelled count after 2 hours.","answer":726,"hint":"Use the growth multiplier 1.1 twice.","solution":"600 × 1.1² = 726 cells.","id":"x061-03","subject":"maths","topic":"Repeated percentage growth","group":"Finance","tier":"Both","calculator":true,"marks":2},{"prompt":"A block has mass 144 g and volume 36 cm³. Find its density in g/cm³.","answer":4,"hint":"Density = mass ÷ volume.","solution":"144 ÷ 36 = 4 g/cm³.","id":"x062-03","subject":"maths","topic":"Density","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A force of 225 N acts on an area of 9 m². Find pressure in N/m².","answer":25,"hint":"Pressure = force ÷ area.","solution":"225 ÷ 9 = 25 N/m².","id":"x063-03","subject":"maths","topic":"Pressure","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"Convert 4 m² into cm².","answer":40000,"hint":"Square the linear conversion: 1 m = 100 cm.","solution":"1 m² = 100² = 10 000 cm². Therefore 4 m² = 40000 cm².","id":"x064-03","subject":"maths","topic":"Metric area conversions","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A journey starts at 09:13 and ends at 11:45. Find its duration in minutes.","answer":152,"hint":"Count the full hours and the remaining minutes.","solution":"From 09:13 to 11:13 is 120 minutes, then another 32. Total = 152 minutes.","id":"x065-03","subject":"maths","topic":"Time calculations","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle is 11 cm by 7 cm. A 2 cm by 2 cm square is cut from one corner. Find the perimeter of the remaining L-shape in cm.","answer":36,"hint":"The two removed edge lengths are replaced by two equal inner edge lengths.","solution":"The perimeter stays equal to the original rectangle: 2(11 + 7) = 36 cm.","id":"x066-03","subject":"maths","topic":"Perimeter of compound shapes","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 4 cm. Express its circumference as kπ cm. Find k.","answer":8,"hint":"Circumference is 2πr.","solution":"2π × 4 = 8π cm.","id":"x067-03","subject":"maths","topic":"Circle circumference","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 5 cm. Its area is kπ cm². Find k.","answer":25,"hint":"Square the radius and multiply by π.","solution":"Area = π × 5² = 25π cm².","id":"x068-03","subject":"maths","topic":"Area of circles","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A semicircle has radius 5 cm. Its perimeter is πr + d. Find the straight-edge length d in cm.","answer":10,"hint":"The straight edge is the diameter, not the radius.","solution":"d = 2r = 2 × 5 = 10 cm. The complete perimeter is 5π + 10 cm.","id":"x069-03","subject":"maths","topic":"Semicircle perimeter","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 60° and radius 9 cm. Its arc length is kπ cm. Find k.","answer":3,"hint":"Take 60/360 of the circumference.","solution":"(60/360) × 2π × 9 = 3π cm.","id":"x070-03","subject":"maths","topic":"Arc length","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 90° and radius 6 cm. Its area is kπ cm². Find k.","answer":9,"hint":"Take one quarter of the full circle area.","solution":"(90/360) × π × 6² = 9π cm².","id":"x071-03","subject":"maths","topic":"Sector area","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A triangular prism has triangular cross-section base 5 cm, height 6 cm, and prism length 10 cm. Find its volume in cm³.","answer":150,"hint":"Find the triangle area, then multiply by the prism length.","solution":"Cross-section = ½ × 5 × 6 = 15 cm². Volume = 150 cm³.","id":"x072-03","subject":"maths","topic":"Volume of prisms","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A cylinder has radius 4 cm and height 5 cm. Its volume is kπ cm³. Find k.","answer":80,"hint":"Multiply the circular base area by the height.","solution":"πr²h = π × 4² × 5 = 80π cm³.","id":"x073-03","subject":"maths","topic":"Volume of cylinders","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A cone has radius 4 cm and perpendicular height 9 cm. Its volume is kπ cm³. Find k.","answer":48,"hint":"A cone has one third of the corresponding cylinder volume.","solution":"V = πr²h/3 = π × 4² × 9/3 = 48π cm³.","id":"x074-03","subject":"maths","topic":"Volume of cones","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sphere has radius 9 cm. Its volume is kπ cm³. Find k.","answer":972,"hint":"Use V = 4πr³/3.","solution":"(4/3) × 9³ = 972, so V = 972π cm³.","id":"x075-03","subject":"maths","topic":"Volume of spheres","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A cuboid measures 4 cm by 3 cm by 4 cm. Find its total surface area in cm².","answer":80,"hint":"There are two faces of each of the three different rectangular areas.","solution":"2[3(4) + 4(4) + 3×4] = 80 cm².","id":"x076-03","subject":"maths","topic":"Surface area of cuboids","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A closed cylinder has radius 4 cm and height 4 cm. Its total surface area is kπ cm². Find k.","answer":64,"hint":"Include two circular ends and the curved surface.","solution":"2r² + 2rh = 2(4²) + 2(4)(4) = 64.","id":"x077-03","subject":"maths","topic":"Cylinder surface area","group":"Geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"Two similar shapes have length scale factor 3 from small to large. A small side is 5 cm. Find the matching large side.","answer":15,"hint":"Multiply corresponding lengths by the length scale factor.","solution":"5 × 3 = 15 cm.","id":"x078-03","subject":"maths","topic":"Similarity of lengths","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Two similar shapes have length scale factor 2. The smaller area is 6 cm². Find the larger area.","answer":24,"hint":"Square the length scale factor for areas.","solution":"Area factor = 2² = 4. Larger area = 6 × 4 = 24 cm².","id":"x079-03","subject":"maths","topic":"Similarity of areas","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"Two similar solids have length scale factor 3. The smaller volume is 4 cm³. Find the larger volume.","answer":108,"hint":"Cube the length scale factor for volumes.","solution":"Volume factor = 3³ = 27. Larger volume = 108 cm³.","id":"x080-03","subject":"maths","topic":"Similarity of volumes","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A triangle has two angles 43° and 63°. Find the third angle in degrees.","answer":74,"hint":"Interior angles in a triangle total 180°.","solution":"180 − 43 − 63 = 74°.","id":"x081-03","subject":"maths","topic":"Triangle angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A regular polygon has 7 sides. Find its exterior angle in degrees, to 3 decimal places if needed.","answer":51.429,"hint":"The exterior angles total 360°.","solution":"Each exterior angle is 360/7 = 51.429°.","id":"x082-03","subject":"maths","topic":"Exterior angles of polygons","group":"Geometry","tier":"Both","calculator":true,"marks":2},{"prompt":"A transversal crosses two parallel lines. One of a pair of co-interior angles is 69°. Find the other angle in degrees.","answer":111,"hint":"Co-interior angles on parallel lines sum to 180°.","solution":"180 − 69 = 111°.","id":"x083-03","subject":"maths","topic":"Angles in parallel lines","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the sum of the interior angles of a polygon with 6 sides.","answer":720,"hint":"Use (number of sides − 2) × 180°.","solution":"(6 − 2) × 180 = 720°.","id":"x084-03","subject":"maths","topic":"Polygon interior-angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"The bearing of B from A is 035°. Find the bearing of A from B as a number of degrees.","answer":215,"hint":"A reverse bearing differs by 180°.","solution":"35 + 180 = 215°.","id":"x085-03","subject":"maths","topic":"Three-figure bearings","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A right-angled triangle has hypotenuse 10 cm and an angle of 30°. Find the side opposite that angle in cm.","answer":5,"hint":"Use sin(angle) = opposite/hypotenuse.","solution":"Opposite = 10 × sin30° = 5 cm.","id":"x086-03","subject":"maths","topic":"Right-angle trigonometry","group":"Trigonometry","tier":"Both","calculator":true,"marks":3},{"prompt":"In a triangle, side a = 5 cm is opposite 30°, and side b is opposite 90°. Find b in cm.","answer":10,"hint":"Use a/sin A = b/sin B.","solution":"b = 5 × sin90°/sin30° = 10 cm.","id":"x087-03","subject":"maths","topic":"Sine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides of a triangle are 5 cm each, with included angle 60°. Find the opposite side in cm.","answer":5,"hint":"Use c² = a² + b² − 2ab cos C.","solution":"c² = 2(5²) − 2(5²)cos60° = 25, so c = 5 cm.","id":"x088-03","subject":"maths","topic":"Cosine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides are 5 cm and 8 cm, with included angle 30°. Find the triangle area in cm².","answer":10,"hint":"Use area = ½ab sin C.","solution":"½ × 5 × 8 × sin30° = 10 cm².","id":"x089-03","subject":"maths","topic":"Triangle area using sine","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"An angle at the circumference is 23°. The central angle subtended by the same arc is less than 180°. Find it.","answer":46,"hint":"The angle at the centre is twice the angle at the circumference on the same arc.","solution":"2 × 23 = 46°.","id":"x090-03","subject":"maths","topic":"Angles at the centre","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"One angle of a cyclic quadrilateral is 96°. Find its opposite angle.","answer":84,"hint":"Opposite angles in a cyclic quadrilateral total 180°.","solution":"180 − 96 = 84°.","id":"x091-03","subject":"maths","topic":"Cyclic quadrilaterals","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"A tangent and chord form an angle of 31°. Find the angle subtended by that chord in the alternate segment.","answer":31,"hint":"The tangent-chord angle equals the angle in the alternate segment.","solution":"By the alternate segment theorem, the required angle is 31°.","id":"x092-03","subject":"maths","topic":"Alternate segment theorem","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"Vectors a = (3, 3) and b = (5, −1). Find the x-component of a + b.","answer":8,"hint":"Add corresponding components.","solution":"a + b = (8, 2), so the x-component is 8.","id":"x093-03","subject":"maths","topic":"Adding vectors","group":"Vectors","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the magnitude of the vector (9, 12).","answer":15,"hint":"Use Pythagoras on the two components.","solution":"√(9² + 12²) = 15.","id":"x094-03","subject":"maths","topic":"Vector magnitude","group":"Vectors","tier":"Higher","calculator":true,"marks":2},{"prompt":"Rotate (3, 5) by 90° anticlockwise about the origin. Find the new x-coordinate.","answer":-5,"hint":"The rule for 90° anticlockwise is (x,y) → (−y,x).","solution":"The image is (−5, 3), so its x-coordinate is −5.","id":"x095-03","subject":"maths","topic":"Rotations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Enlarge (3, 2) by scale factor 3 about the origin. Find the new x-coordinate.","answer":9,"hint":"Multiply both coordinates by the scale factor.","solution":"The image is (9, 6).","id":"x096-03","subject":"maths","topic":"Enlargements","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Translate (3, 4) by the vector (−3, 2). Find the new x-coordinate.","answer":0,"hint":"Add the x-component of the vector to the x-coordinate.","solution":"The image is (0, 6).","id":"x097-03","subject":"maths","topic":"Translations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Reflect (3, 6) in the line y = x. Find the new x-coordinate.","answer":6,"hint":"Reflection in y = x swaps the coordinates.","solution":"The image is (6, 3).","id":"x098-03","subject":"maths","topic":"Reflections","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Points must be exactly 5 cm from a fixed point P. What is their locus?","kind":"choice","options":["A perpendicular bisector through P","A circle centred at P with radius 5 cm","A circle centred at P with diameter 5 cm","A straight line through P"],"correct":1,"answer":null,"hint":"A fixed distance from one point defines a circle.","solution":"All points on a circle of radius 5 cm are exactly 5 cm from its centre P.","id":"x099-03","subject":"maths","topic":"Loci and constructions","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the median of 10, 3, 6, 12, 4.","answer":6,"hint":"Order the values, then choose the middle one.","solution":"The ordered list is 3, 4, 6, 10, 12. Its middle value is 6.","id":"x100-03","subject":"maths","topic":"Finding the median","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the mode of 3, 5, 5, 7, 5, 9.","answer":5,"hint":"Look for the value occurring most frequently.","solution":"5 occurs three times; every other value occurs once.","id":"x101-03","subject":"maths","topic":"Finding the mode","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the range of −3, 2, 7, 0.","answer":10,"hint":"Subtract the minimum from the maximum.","solution":"7 − (−3) = 10.","id":"x102-03","subject":"maths","topic":"Finding the range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A data set has lower quartile 6 and upper quartile 19. Find its interquartile range.","answer":13,"hint":"IQR = upper quartile − lower quartile.","solution":"19 − 6 = 13.","id":"x103-03","subject":"maths","topic":"Interquartile range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A grouped table has 2 values in 0 ≤ x < 10 and 5 values in 10 ≤ x < 20. Estimate the mean, to 3 decimal places.","answer":12.143,"hint":"Use class midpoints 5 and 15, multiply by frequencies, then divide by total frequency.","solution":"Estimated total = 2×5 + 5×15 = 85. Divide by 7 to get 12.143.","id":"x104-03","subject":"maths","topic":"Estimated mean from grouped data","group":"Statistics","tier":"Both","calculator":true,"marks":3},{"prompt":"A histogram class has width 5 and frequency 25. Find its frequency density.","answer":5,"hint":"Frequency density = frequency ÷ class width.","solution":"25 ÷ 5 = 5.","id":"x105-03","subject":"maths","topic":"Frequency density","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"Class frequencies, in ascending order, are 3, 5, 7, 9. Find the cumulative frequency at the end of the third class.","answer":15,"hint":"Add all frequencies up to and including the third class.","solution":"3 + 5 + 7 = 15.","id":"x106-03","subject":"maths","topic":"Cumulative frequency","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A box plot has minimum 3, lower quartile 6, median 9, upper quartile 12, maximum 18. Read off its median.","answer":9,"hint":"The median is the line inside the box.","solution":"The median line is at 9. The ends of the box are the quartiles.","id":"x107-03","subject":"maths","topic":"Box plots","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A school has 600 pupils; 90 are in a chosen group. In a proportional sample of 40 pupils, how many should come from that group?","answer":6,"hint":"Multiply the sample size by the group proportion.","solution":"40 × 90/600 = 6 pupils.","id":"x108-03","subject":"maths","topic":"Stratified sampling","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"An experiment succeeds 6 times out of 20 trials. Find the relative frequency as a fraction or decimal.","answer":0.3,"hint":"Divide the number of successes by the number of trials.","solution":"Relative frequency = 6/20 = 0.3.","id":"x109-03","subject":"maths","topic":"Relative frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"An event has probability 0.3. It is tested 60 times. Find its expected frequency.","answer":18,"hint":"Multiply probability by number of trials.","solution":"0.3 × 60 = 18. This is an expectation, not a guarantee.","id":"x110-03","subject":"maths","topic":"Expected frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Two independent events have probabilities 1/2 and 3/12. Find the probability that both occur.","answer":0.125,"hint":"Multiply the probabilities of independent events.","solution":"1/2 × 3/12 = 3/24.","id":"x111-03","subject":"maths","topic":"Independent events","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A bag has 5 red counters and 3 blue counters. Two counters are drawn without replacement. Find P(both red), to 3 decimal places.","answer":0.357,"hint":"The second draw has one fewer red counter and one fewer counter altogether.","solution":"P = (5/8) × (4/7) = 0.357.","id":"x112-03","subject":"maths","topic":"Sampling without replacement","group":"Probability","tier":"Higher","calculator":true,"marks":3},{"prompt":"Of 8 club members who play tennis, 3 also swim. A member is chosen from the tennis players only. Find P(swims), as a fraction or decimal.","answer":0.375,"hint":"Use the restricted tennis group as the denominator.","solution":"Given that the person plays tennis, P(swims) = 3/8.","id":"x113-03","subject":"maths","topic":"Conditional probability","group":"Probability","tier":"Higher","calculator":false,"marks":2},{"prompt":"Set A contains 17 people including 5 in A ∩ B. How many are in A only?","answer":12,"hint":"Subtract the intersection from the total in A.","solution":"17 − 5 = 12 people.","id":"x114-03","subject":"maths","topic":"Venn diagram regions","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"n(A) = 13, n(B) = 15, and n(A ∩ B) = 6. Find n(A ∪ B).","answer":22,"hint":"Add the two set sizes and subtract the overlap once.","solution":"13 + 15 − 6 = 22.","id":"x115-03","subject":"maths","topic":"Set union","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A fair coin is tossed, then a fair 6-sided die numbered 1 to 6 is rolled. Find P(heads and a 1).","answer":0.0833333333,"hint":"Multiply the branch probabilities along the path.","solution":"(1/2) × (1/6) = 1/12.","id":"x116-03","subject":"maths","topic":"Tree diagrams","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Plot the listed points for y = x³ − 2. Use x = -2, -1, 0, 1, 2. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[-2,-10],[-1,-3],[0,-2],[1,-1],[2,6]],"curve":"quadratic","range":[-3,3,-14,14],"expression":"y = x³ − 2","hint":"Cube each x, preserving its sign, then add the constant.","solution":"The coordinates are (-2, -10), (-1, -3), (0, -2), (1, -1), (2, 6). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x117-03","subject":"maths","topic":"Cubic graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 12/x + 2 for 1 ≤ x ≤ 6. Use x = 1, 2, 3, 4, 6. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[1,14.0],[2,8.0],[3,6.0],[4,5.0],[6,4.0]],"curve":"quadratic","range":[0,7,0,23],"expression":"y = 12/x + 2 for 1 ≤ x ≤ 6","hint":"Divide 12 by x, then add the constant; x = 0 is not allowed.","solution":"The coordinates are (1, 14.0), (2, 8.0), (3, 6.0), (4, 5.0), (6, 4.0). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x118-03","subject":"maths","topic":"Reciprocal graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 2^x + 2. Use x = 0, 1, 2, 3. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[0,3],[1,4],[2,6],[3,10]],"curve":"quadratic","range":[-1,4,0,18],"expression":"y = 2^x + 2","hint":"Calculate the power of 2 first, then add the constant.","solution":"The coordinates are (0, 3), (1, 4), (2, 6), (3, 10). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x119-03","subject":"maths","topic":"Exponential graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"The graph y = x² is translated upward by 5 units. Find the new y-coordinate of its turning point.","answer":5,"hint":"An upward translation adds the same amount to every y-coordinate.","solution":"The old turning point is (0, 0); the new one is (0, 5).","id":"x120-03","subject":"maths","topic":"Translating graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A straight segment on a distance-time graph runs from (0 hours, 0 km) to (2 hours, 36 km). Find the speed in km/h.","answer":18,"hint":"Speed is the gradient: distance change divided by time change.","solution":"36 km ÷ 2 h = 18 km/h.","id":"x121-03","subject":"maths","topic":"Distance-time graphs","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A velocity-time graph rises in a straight line from 0 m/s to 15 m/s in 5 seconds. Find acceleration in m/s².","answer":3,"hint":"Acceleration is change in velocity divided by time.","solution":"(15 − 0)/5 = 3 m/s².","id":"x122-03","subject":"maths","topic":"Velocity-time gradients","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A tangent to a curve passes through (1, 3) and (3, 11). Estimate the gradient of the curve at the contact point.","answer":4,"hint":"Use the gradient of the tangent, not a chord through two curve points.","solution":"(11 − 3)/(3 − 1) = 4.","id":"x123-03","subject":"maths","topic":"Tangents and rates of change","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A velocity-time graph forms a triangle with base 6 seconds and maximum velocity 6 m/s. Find the displacement in metres.","answer":18,"hint":"Displacement is the signed area under a velocity-time graph.","solution":"Area = ½ × 6 × 6 = 18 m.","id":"x124-03","subject":"maths","topic":"Area under velocity-time graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"The lines y = x + 3 and y = 3x intersect. Find the x-coordinate of the intersection.","answer":1.5,"hint":"At the intersection, both expressions for y are equal.","solution":"x + 3 = 3x, so 2x = 3 and x = 1.5.","id":"x125-03","subject":"maths","topic":"Graphical simultaneous equations","group":"Graphs","tier":"Both","calculator":false,"marks":3},{"prompt":"Which point satisfies both x > 3 and y < 3?","kind":"choice","options":["(2, 0)","(4, 2)","(3, 2)","(4, 4)"],"correct":1,"answer":null,"hint":"Test both strict inequalities for each coordinate pair.","solution":"Only (4, 2) has x strictly greater than 3 and y strictly less than 3.","id":"x126-03","subject":"maths","topic":"Regions satisfying inequalities","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate 7 + 6 × 4.","answer":31,"hint":"Do multiplication before addition.","solution":"6 × 4 = 24; then add 7 to get 31.","id":"x001-04","subject":"maths","topic":"Order of operations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"The temperature is −6°C. It falls by 8°C. What is the new temperature in °C?","answer":-14,"hint":"A fall makes the number more negative.","solution":"−6 − 8 = −14°C.","id":"x002-04","subject":"maths","topic":"Calculating with negatives","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the value of the hundreds digit in 1504?","answer":500,"hint":"Identify the digit three places from the right.","solution":"The hundreds digit is 5, so its value is 5 × 100 = 500.","id":"x003-04","subject":"maths","topic":"Place value","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 6.376 to two decimal places.","answer":6.38,"hint":"Look at the third decimal digit.","solution":"The third digit is 6, so round the hundredths up: 6.38.","id":"x004-04","subject":"maths","topic":"Rounding decimal places","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 2502 to two significant figures.","answer":2500,"hint":"Count significant digits from the first non-zero digit.","solution":"The first two significant figures are in the thousands and hundreds columns. Rounding 2502 to the nearest 100 gives 2500.","id":"x005-04","subject":"maths","topic":"Significant figures","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Estimate 6.9 × 19.8 by rounding each number to the nearest whole number first.","answer":140,"hint":"Follow the requested rounding method for both numbers.","solution":"6.9 rounds to 7; 19.8 rounds to 20. The estimate is 140.","id":"x006-04","subject":"maths","topic":"Estimating calculations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"How many positive factors does 32 have?","answer":6,"hint":"For a power of 2, list 2⁰ up to the highest power.","solution":"32 = 2^5. Its factors are 2⁰ through 2^5, giving 6 factors.","id":"x007-04","subject":"maths","topic":"Factors","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the smallest multiple of 7 that is strictly greater than 70?","answer":77,"hint":"The number given is already the tenth multiple.","solution":"The next multiple is 11 × 7 = 77.","id":"x008-04","subject":"maths","topic":"Multiples","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Which number in this list is prime? Set 4.","kind":"choice","options":["19","28","36","54"],"correct":0,"answer":null,"hint":"A prime has exactly two positive factors: 1 and itself.","solution":"19 has no positive factors except 1 and itself. The other numbers have explicit factors 4, 6 or 9.","id":"x009-04","subject":"maths","topic":"Prime numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"In the prime factorisation of 144, what is the exponent of 2?","answer":4,"hint":"Keep dividing by 2 until the remaining number is odd.","solution":"144 = 2^4 × 3², so the exponent is 4.","id":"x010-04","subject":"maths","topic":"Prime factorisation","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the highest common factor of 48 and 72.","answer":24,"hint":"Look for the largest factor that divides both numbers.","solution":"48 = 2 × 24 and 72 = 3 × 24. Since 2 and 3 are coprime, the HCF is 24.","id":"x011-04","subject":"maths","topic":"Highest common factor","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the lowest common multiple of 16 and 24.","answer":48,"hint":"Find the HCF first, or list the multiples.","solution":"The HCF is 8. LCM = (16 × 24) ÷ 8 = 48.","id":"x012-04","subject":"maths","topic":"Lowest common multiple","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 4/12 + 1/8. Give a fraction or decimal.","answer":0.4583333333,"hint":"Use a common denominator of 24.","solution":"4/12 = 8/24 and 1/8 = 3/24. The sum is 11/24.","id":"x013-04","subject":"maths","topic":"Adding fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 4/11 × 3/5. Give a fraction or decimal.","answer":0.2181818182,"hint":"Multiply numerators and denominators.","solution":"(4 × 3)/(11 × 5) = 12/55. Simplify if possible.","id":"x014-04","subject":"maths","topic":"Multiplying fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 4/12 ÷ 5/6. Give a fraction or decimal.","answer":0.4,"hint":"Multiply by the reciprocal of 5/6.","solution":"4/12 × 6/5 = 24/60 = 4/10.","id":"x015-04","subject":"maths","topic":"Dividing fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 4 3/4 as a decimal.","answer":4.75,"hint":"The fraction part is three quarters, or 0.75.","solution":"4 + 0.75 = 4.75.","id":"x016-04","subject":"maths","topic":"Mixed numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A club has 96 members. Three eighths cycle to the club. How many members cycle?","answer":36,"hint":"Divide by 8 to find one eighth, then multiply by 3.","solution":"96 ÷ 8 × 3 = 36.","id":"x017-04","subject":"maths","topic":"Fractions of quantities","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 0.141414… (the block 14 repeats) as a fraction or decimal.","answer":0.1414141414,"hint":"For a two-digit repeating block, compare 100x with x.","solution":"If x = 0.1414…, then 100x − x = 14; hence x = 14/99.","id":"x018-04","subject":"maths","topic":"Recurring decimals","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Simplify 3^5 × 3^7 to 3^k. Find k.","answer":12,"hint":"Add exponents when multiplying powers of the same base.","solution":"k = 5 + 7 = 12.","id":"x019-04","subject":"maths","topic":"Index laws","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Evaluate 5^−2. Give a fraction or decimal.","answer":0.04,"hint":"A negative exponent gives the reciprocal of the positive power.","solution":"5^−2 = 1/(5²) = 1/25.","id":"x020-04","subject":"maths","topic":"Negative indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Evaluate 216^(2/3).","answer":36,"hint":"Take the cube root, then square the result.","solution":"The cube root of 216 is 6; its square is 36.","id":"x021-04","subject":"maths","topic":"Fractional indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write √50 in the form a√2. Find a.","answer":5,"hint":"Look for a square factor inside the root.","solution":"√(25 × 2) = 5√2, so a = 5.","id":"x022-04","subject":"maths","topic":"Simplifying surds","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write 12/√3 in the form a√3. Find a.","answer":4,"hint":"Multiply numerator and denominator by √3.","solution":"(12√3)/3 = 4√3.","id":"x023-04","subject":"maths","topic":"Rationalising denominators","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate (2 × 10^4) × (3 × 10²). Write the result as 6 × 10^k. Find k.","answer":6,"hint":"Multiply the coefficients and add powers of ten.","solution":"2 × 3 = 6 and 4 + 2 = 6, so k = 6.","id":"x024-04","subject":"maths","topic":"Calculating in standard form","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A length is 14 cm to the nearest centimetre. Give the lower bound in cm.","answer":13.5,"hint":"The rounding interval extends half a centimetre either side.","solution":"The lower bound is 14 − 0.5 = 13.5 cm; the upper bound is 14.5 cm and is excluded.","id":"x025-04","subject":"maths","topic":"Error intervals","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle has length 14 cm and width 8 cm, both to the nearest centimetre. Find the upper bound for its area in cm².","answer":123.25,"hint":"Use the upper bound for each positive length.","solution":"Upper area bound = 14.5 × 8.5 = 123.25 cm².","id":"x026-04","subject":"maths","topic":"Upper and lower bounds","group":"Number","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify 6x + 8x − 3x to ax. Find a.","answer":11,"hint":"Combine only the coefficients of x.","solution":"a = 6 + 8 − 3 = 11.","id":"x027-04","subject":"maths","topic":"Collecting like terms","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand 6(x + 5). What is the constant term?","answer":30,"hint":"Multiply both terms inside the bracket.","solution":"The expansion is 6x + 30.","id":"x028-04","subject":"maths","topic":"Expanding a single bracket","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand (x + 4)(x + 7). What is the coefficient of x?","answer":11,"hint":"Multiply every term in one bracket by every term in the other.","solution":"x² + 7x + 4x + 28 = x² + 11x + 28.","id":"x029-04","subject":"maths","topic":"Expanding double brackets","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise fully 8x + 24.","kind":"choice","options":["8(x + 3)","8(x + 6)","4(x + 3)","24(x + 2)"],"correct":0,"answer":null,"hint":"Take out the highest common factor of the two coefficients.","solution":"Both terms contain 8. Dividing gives x and 3, so the result is 8(x + 3).","id":"x030-04","subject":"maths","topic":"Factorising with a common factor","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise x² + 11x + 28.","kind":"choice","options":["(x + 4)(x + 7)","(x − 4)(x − 7)","(x + 5)(x + 6)","(x − 4)(x + 7)"],"correct":0,"answer":null,"hint":"Find two numbers whose product is the constant and whose sum is the x coefficient.","solution":"4 × 7 = 28 and 4 + 7 = 11.","id":"x031-04","subject":"maths","topic":"Factorising quadratics","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Find 2a² − b when a = 4 and b = 7.","answer":25,"hint":"Square a before multiplying by 2.","solution":"2 × 4² − 7 = 25.","id":"x032-04","subject":"maths","topic":"Substitution","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The formula is y = 6x − 4. If y = 26, find x.","answer":5,"hint":"Add the constant to y, then divide by the coefficient of x.","solution":"x = (y + 4)/6 = 30/6 = 5.","id":"x033-04","subject":"maths","topic":"Changing the subject","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the smallest integer satisfying 3x + 4 > 16.","answer":5,"hint":"Subtract the constant, divide by 3, then respect the strict inequality.","solution":"3x > 12, so x > 4. The smallest integer is 5.","id":"x034-04","subject":"maths","topic":"Linear inequalities","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Solve x + y = 13 and x − y = 5. Give x.","answer":9,"hint":"Add the two equations to eliminate y.","solution":"2x = 18, so x = 9.","id":"x035-04","subject":"maths","topic":"Simultaneous linear equations","group":"Algebra","tier":"Both","calculator":false,"marks":3},{"prompt":"The graphs y = x² and y = 16 meet. Give the positive x-coordinate.","answer":4,"hint":"Substitute to obtain x² equal to the constant.","solution":"x² = 16, so x = ±4. The positive value is 4.","id":"x036-04","subject":"maths","topic":"Simultaneous nonlinear equations","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"Write x² + 8x + 22 as (x + a)² + b. Find b.","answer":6,"hint":"Half the x coefficient gives a. Subtract a² from the constant.","solution":"a = 4. Subtract 16 from the constant 22 to get b = 6.","id":"x037-04","subject":"maths","topic":"Completing the square","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Use the quadratic formula to find the positive root of x² + x − 20 = 0.","answer":4,"hint":"Identify a, b and c. Use x = (−b ± √(b² − 4ac))/(2a).","solution":"a=1, b=1, c=−20. The discriminant is 1 + 80 = 81. The positive root is (−1 + 9)/2 = 4.","id":"x038-04","subject":"maths","topic":"Quadratic formula","group":"Algebra","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify (6x)/(12x²) for x ≠ 0, then evaluate at x = 4.","answer":0.125,"hint":"Cancel the common numerical factor and one factor of x.","solution":"The expression simplifies to 1/(2x). At x = 4, it is 1/8.","id":"x039-04","subject":"maths","topic":"Algebraic fractions","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"The difference (k + 1)² − k² simplifies to 2k + 1. Use this identity to find the difference between the squares of 8 and 9.","answer":17,"hint":"Expand the square before cancelling k².","solution":"Expanding proves (k + 1)² − k² = 2k + 1. Set k = 8: the difference is 17.","id":"x040-04","subject":"maths","topic":"Algebraic proof","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x − 4. Find f(6).","answer":14,"hint":"Replace every x with the specified input.","solution":"f(6) = 3(6) − 4 = 14.","id":"x041-04","subject":"maths","topic":"Function notation","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"f(x) = 2x + 1 and g(x) = x². Find f(g(4)).","answer":33,"hint":"Apply the inside function first.","solution":"g(4) = 16; f(16) = 33.","id":"x042-04","subject":"maths","topic":"Composite functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x + 4. Find f⁻¹(16).","answer":4,"hint":"Undo the addition, then undo the multiplication.","solution":"f⁻¹(y) = (y − 4)/3. With y = 16, this gives 4.","id":"x043-04","subject":"maths","topic":"Inverse functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"x₀ = 4. Use x_(k+1) = (x_k + 4)/2 to calculate x₂.","answer":4.0,"hint":"Calculate x₁ first and substitute that new value again.","solution":"x₁ = (4 + 4)/2 = 4.0. Then x₂ = (4.0 + 4)/2 = 4.0.","id":"x044-04","subject":"maths","topic":"Iteration","group":"Algebra","tier":"Higher","calculator":true,"marks":2},{"prompt":"A geometric sequence starts at 5 and has common ratio 3. Find its fourth term.","answer":135,"hint":"Multiply by 3 three times after the first term.","solution":"The fourth term is 5 × 3³ = 135.","id":"x045-04","subject":"maths","topic":"Geometric sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The nth term is n² + 4n + 2. Find the fifth term.","answer":47,"hint":"Replace each occurrence of n (the position variable) with 5.","solution":"5² + 4 × 5 + 2 = 47.","id":"x046-04","subject":"maths","topic":"Quadratic sequences","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sequence begins 4, 5. Each new term is the sum of the preceding two. Find the fifth term.","answer":23,"hint":"Build the third and fourth terms before the fifth.","solution":"The terms are 4, 5, 9, 14, 23.","id":"x047-04","subject":"maths","topic":"Fibonacci-type sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the x-coordinate of the midpoint of (4, 2) and (14, 8).","answer":9,"hint":"Average the two x-coordinates.","solution":"(4 + 14)/2 = 9. The full midpoint is (9, 5).","id":"x048-04","subject":"maths","topic":"Midpoints","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the distance between (0, 0) and (12, 16).","answer":20,"hint":"Use the horizontal and vertical differences in Pythagoras.","solution":"√(12² + 16²) = 20 units.","id":"x049-04","subject":"maths","topic":"Distance between coordinates","group":"Coordinate geometry","tier":"Both","calculator":true,"marks":3},{"prompt":"A line is parallel to y = 5x − 4 and passes through (0, 4). Give its gradient.","answer":5,"hint":"Parallel non-vertical lines have equal gradients.","solution":"The given line has gradient 5, so the parallel line does too.","id":"x050-04","subject":"maths","topic":"Parallel lines","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the gradient of a line perpendicular to y = 5x + 2. Give a fraction or decimal.","answer":-0.2,"hint":"For non-zero gradients, the perpendicular gradient is the negative reciprocal.","solution":"The negative reciprocal of 5 is −1/5.","id":"x051-04","subject":"maths","topic":"Perpendicular lines","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A line passes through (1, 9) and (3, 17). Write it as y = mx + c. Find c.","answer":5,"hint":"Find the gradient from the two points, then substitute a point.","solution":"m = (17 − 9)/2 = 4. Then c = 9 − 4 = 5.","id":"x052-04","subject":"maths","topic":"Equation of a line through points","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"A pack of 7 notebooks costs £35. Find the price per notebook in pounds.","answer":5,"hint":"Divide cost by number of items.","solution":"£35 ÷ 7 = £5 per notebook.","id":"x053-04","subject":"maths","topic":"Best buys and unit pricing","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"£1 exchanges for €1.20. How many euros are exchanged for £100?","answer":120,"hint":"Multiply the pound amount by the euros-per-pound rate.","solution":"100 × 1.20 = €120.","id":"x054-04","subject":"maths","topic":"Currency conversion","group":"Proportion and rates","tier":"Both","calculator":true,"marks":2},{"prompt":"A recipe for 4 people uses 160 g of rice. How many grams are needed for 6 people?","answer":240.0,"hint":"Scale every ingredient by 6/4.","solution":"160 × 6/4 = 240.0 g.","id":"x055-04","subject":"maths","topic":"Scaling recipes","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"A map has scale 1:50 000. Two places are 4 cm apart on the map. Find their real distance in kilometres.","answer":2.0,"hint":"Convert the scaled centimetres into kilometres using 100 000 cm = 1 km.","solution":"4 × 50 000 = 200000 cm = 2.0 km.","id":"x056-04","subject":"maths","topic":"Map scales","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is directly proportional to x. When x = 3, y = 15. Find y when x = 8.","answer":40,"hint":"Find k in y = kx.","solution":"k = 15/3 = 5; hence y = 5 × 8 = 40.","id":"x057-04","subject":"maths","topic":"Direct proportion","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is inversely proportional to x. When x = 2, y = 24. Find y when x = 3.","answer":16,"hint":"The product xy stays constant.","solution":"k = 2 × 24 = 48. Thus y = 48/3 = 16.","id":"x058-04","subject":"maths","topic":"Inverse proportion","group":"Proportion and rates","tier":"Higher","calculator":false,"marks":2},{"prompt":"£400 earns 5% compound interest each year. Find the balance after 2 years in pounds.","answer":441.0,"hint":"Multiply by 1.05 for each year.","solution":"£400 × 1.05² = £441.00.","id":"x059-04","subject":"maths","topic":"Compound interest","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A bicycle worth £1000 loses 20% of its value each year. Find its value after 2 years in pounds.","answer":640,"hint":"Retain 80% each year, using the multiplier 0.8 twice.","solution":"£1000 × 0.8² = £640.","id":"x060-04","subject":"maths","topic":"Depreciation","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A culture begins with 800 cells and increases by 10% each hour. Find the modelled count after 2 hours.","answer":968,"hint":"Use the growth multiplier 1.1 twice.","solution":"800 × 1.1² = 968 cells.","id":"x061-04","subject":"maths","topic":"Repeated percentage growth","group":"Finance","tier":"Both","calculator":true,"marks":2},{"prompt":"A block has mass 240 g and volume 48 cm³. Find its density in g/cm³.","answer":5,"hint":"Density = mass ÷ volume.","solution":"240 ÷ 48 = 5 g/cm³.","id":"x062-04","subject":"maths","topic":"Density","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A force of 360 N acts on an area of 12 m². Find pressure in N/m².","answer":30,"hint":"Pressure = force ÷ area.","solution":"360 ÷ 12 = 30 N/m².","id":"x063-04","subject":"maths","topic":"Pressure","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"Convert 5 m² into cm².","answer":50000,"hint":"Square the linear conversion: 1 m = 100 cm.","solution":"1 m² = 100² = 10 000 cm². Therefore 5 m² = 50000 cm².","id":"x064-04","subject":"maths","topic":"Metric area conversions","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A journey starts at 09:14 and ends at 11:45. Find its duration in minutes.","answer":151,"hint":"Count the full hours and the remaining minutes.","solution":"From 09:14 to 11:14 is 120 minutes, then another 31. Total = 151 minutes.","id":"x065-04","subject":"maths","topic":"Time calculations","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle is 12 cm by 8 cm. A 2 cm by 2 cm square is cut from one corner. Find the perimeter of the remaining L-shape in cm.","answer":40,"hint":"The two removed edge lengths are replaced by two equal inner edge lengths.","solution":"The perimeter stays equal to the original rectangle: 2(12 + 8) = 40 cm.","id":"x066-04","subject":"maths","topic":"Perimeter of compound shapes","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 5 cm. Express its circumference as kπ cm. Find k.","answer":10,"hint":"Circumference is 2πr.","solution":"2π × 5 = 10π cm.","id":"x067-04","subject":"maths","topic":"Circle circumference","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 6 cm. Its area is kπ cm². Find k.","answer":36,"hint":"Square the radius and multiply by π.","solution":"Area = π × 6² = 36π cm².","id":"x068-04","subject":"maths","topic":"Area of circles","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A semicircle has radius 6 cm. Its perimeter is πr + d. Find the straight-edge length d in cm.","answer":12,"hint":"The straight edge is the diameter, not the radius.","solution":"d = 2r = 2 × 6 = 12 cm. The complete perimeter is 6π + 12 cm.","id":"x069-04","subject":"maths","topic":"Semicircle perimeter","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 60° and radius 12 cm. Its arc length is kπ cm. Find k.","answer":4,"hint":"Take 60/360 of the circumference.","solution":"(60/360) × 2π × 12 = 4π cm.","id":"x070-04","subject":"maths","topic":"Arc length","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 90° and radius 8 cm. Its area is kπ cm². Find k.","answer":16,"hint":"Take one quarter of the full circle area.","solution":"(90/360) × π × 8² = 16π cm².","id":"x071-04","subject":"maths","topic":"Sector area","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A triangular prism has triangular cross-section base 6 cm, height 6 cm, and prism length 10 cm. Find its volume in cm³.","answer":180,"hint":"Find the triangle area, then multiply by the prism length.","solution":"Cross-section = ½ × 6 × 6 = 18 cm². Volume = 180 cm³.","id":"x072-04","subject":"maths","topic":"Volume of prisms","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A cylinder has radius 5 cm and height 5 cm. Its volume is kπ cm³. Find k.","answer":125,"hint":"Multiply the circular base area by the height.","solution":"πr²h = π × 5² × 5 = 125π cm³.","id":"x073-04","subject":"maths","topic":"Volume of cylinders","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A cone has radius 5 cm and perpendicular height 9 cm. Its volume is kπ cm³. Find k.","answer":75,"hint":"A cone has one third of the corresponding cylinder volume.","solution":"V = πr²h/3 = π × 5² × 9/3 = 75π cm³.","id":"x074-04","subject":"maths","topic":"Volume of cones","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sphere has radius 12 cm. Its volume is kπ cm³. Find k.","answer":2304,"hint":"Use V = 4πr³/3.","solution":"(4/3) × 12³ = 2304, so V = 2304π cm³.","id":"x075-04","subject":"maths","topic":"Volume of spheres","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A cuboid measures 5 cm by 3 cm by 4 cm. Find its total surface area in cm².","answer":94,"hint":"There are two faces of each of the three different rectangular areas.","solution":"2[3(5) + 4(5) + 3×4] = 94 cm².","id":"x076-04","subject":"maths","topic":"Surface area of cuboids","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A closed cylinder has radius 5 cm and height 4 cm. Its total surface area is kπ cm². Find k.","answer":90,"hint":"Include two circular ends and the curved surface.","solution":"2r² + 2rh = 2(5²) + 2(5)(4) = 90.","id":"x077-04","subject":"maths","topic":"Cylinder surface area","group":"Geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"Two similar shapes have length scale factor 3 from small to large. A small side is 6 cm. Find the matching large side.","answer":18,"hint":"Multiply corresponding lengths by the length scale factor.","solution":"6 × 3 = 18 cm.","id":"x078-04","subject":"maths","topic":"Similarity of lengths","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Two similar shapes have length scale factor 2. The smaller area is 7 cm². Find the larger area.","answer":28,"hint":"Square the length scale factor for areas.","solution":"Area factor = 2² = 4. Larger area = 7 × 4 = 28 cm².","id":"x079-04","subject":"maths","topic":"Similarity of areas","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"Two similar solids have length scale factor 3. The smaller volume is 5 cm³. Find the larger volume.","answer":135,"hint":"Cube the length scale factor for volumes.","solution":"Volume factor = 3³ = 27. Larger volume = 135 cm³.","id":"x080-04","subject":"maths","topic":"Similarity of volumes","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A triangle has two angles 44° and 64°. Find the third angle in degrees.","answer":72,"hint":"Interior angles in a triangle total 180°.","solution":"180 − 44 − 64 = 72°.","id":"x081-04","subject":"maths","topic":"Triangle angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A regular polygon has 8 sides. Find its exterior angle in degrees, to 3 decimal places if needed.","answer":45.0,"hint":"The exterior angles total 360°.","solution":"Each exterior angle is 360/8 = 45.000°.","id":"x082-04","subject":"maths","topic":"Exterior angles of polygons","group":"Geometry","tier":"Both","calculator":true,"marks":2},{"prompt":"A transversal crosses two parallel lines. One of a pair of co-interior angles is 72°. Find the other angle in degrees.","answer":108,"hint":"Co-interior angles on parallel lines sum to 180°.","solution":"180 − 72 = 108°.","id":"x083-04","subject":"maths","topic":"Angles in parallel lines","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the sum of the interior angles of a polygon with 7 sides.","answer":900,"hint":"Use (number of sides − 2) × 180°.","solution":"(7 − 2) × 180 = 900°.","id":"x084-04","subject":"maths","topic":"Polygon interior-angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"The bearing of B from A is 040°. Find the bearing of A from B as a number of degrees.","answer":220,"hint":"A reverse bearing differs by 180°.","solution":"40 + 180 = 220°.","id":"x085-04","subject":"maths","topic":"Three-figure bearings","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A right-angled triangle has hypotenuse 12 cm and an angle of 30°. Find the side opposite that angle in cm.","answer":6,"hint":"Use sin(angle) = opposite/hypotenuse.","solution":"Opposite = 12 × sin30° = 6 cm.","id":"x086-04","subject":"maths","topic":"Right-angle trigonometry","group":"Trigonometry","tier":"Both","calculator":true,"marks":3},{"prompt":"In a triangle, side a = 6 cm is opposite 30°, and side b is opposite 90°. Find b in cm.","answer":12,"hint":"Use a/sin A = b/sin B.","solution":"b = 6 × sin90°/sin30° = 12 cm.","id":"x087-04","subject":"maths","topic":"Sine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides of a triangle are 6 cm each, with included angle 60°. Find the opposite side in cm.","answer":6,"hint":"Use c² = a² + b² − 2ab cos C.","solution":"c² = 2(6²) − 2(6²)cos60° = 36, so c = 6 cm.","id":"x088-04","subject":"maths","topic":"Cosine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides are 6 cm and 8 cm, with included angle 30°. Find the triangle area in cm².","answer":12,"hint":"Use area = ½ab sin C.","solution":"½ × 6 × 8 × sin30° = 12 cm².","id":"x089-04","subject":"maths","topic":"Triangle area using sine","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"An angle at the circumference is 24°. The central angle subtended by the same arc is less than 180°. Find it.","answer":48,"hint":"The angle at the centre is twice the angle at the circumference on the same arc.","solution":"2 × 24 = 48°.","id":"x090-04","subject":"maths","topic":"Angles at the centre","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"One angle of a cyclic quadrilateral is 98°. Find its opposite angle.","answer":82,"hint":"Opposite angles in a cyclic quadrilateral total 180°.","solution":"180 − 98 = 82°.","id":"x091-04","subject":"maths","topic":"Cyclic quadrilaterals","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"A tangent and chord form an angle of 33°. Find the angle subtended by that chord in the alternate segment.","answer":33,"hint":"The tangent-chord angle equals the angle in the alternate segment.","solution":"By the alternate segment theorem, the required angle is 33°.","id":"x092-04","subject":"maths","topic":"Alternate segment theorem","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"Vectors a = (4, 3) and b = (6, −1). Find the x-component of a + b.","answer":10,"hint":"Add corresponding components.","solution":"a + b = (10, 2), so the x-component is 10.","id":"x093-04","subject":"maths","topic":"Adding vectors","group":"Vectors","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the magnitude of the vector (12, 16).","answer":20,"hint":"Use Pythagoras on the two components.","solution":"√(12² + 16²) = 20.","id":"x094-04","subject":"maths","topic":"Vector magnitude","group":"Vectors","tier":"Higher","calculator":true,"marks":2},{"prompt":"Rotate (4, 6) by 90° anticlockwise about the origin. Find the new x-coordinate.","answer":-6,"hint":"The rule for 90° anticlockwise is (x,y) → (−y,x).","solution":"The image is (−6, 4), so its x-coordinate is −6.","id":"x095-04","subject":"maths","topic":"Rotations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Enlarge (4, 2) by scale factor 3 about the origin. Find the new x-coordinate.","answer":12,"hint":"Multiply both coordinates by the scale factor.","solution":"The image is (12, 6).","id":"x096-04","subject":"maths","topic":"Enlargements","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Translate (4, 4) by the vector (−3, 2). Find the new x-coordinate.","answer":1,"hint":"Add the x-component of the vector to the x-coordinate.","solution":"The image is (1, 6).","id":"x097-04","subject":"maths","topic":"Translations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Reflect (4, 7) in the line y = x. Find the new x-coordinate.","answer":7,"hint":"Reflection in y = x swaps the coordinates.","solution":"The image is (7, 4).","id":"x098-04","subject":"maths","topic":"Reflections","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Points must be exactly 6 cm from a fixed point P. What is their locus?","kind":"choice","options":["A circle centred at P with radius 6 cm","A circle centred at P with diameter 6 cm","A straight line through P","A perpendicular bisector through P"],"correct":0,"answer":null,"hint":"A fixed distance from one point defines a circle.","solution":"All points on a circle of radius 6 cm are exactly 6 cm from its centre P.","id":"x099-04","subject":"maths","topic":"Loci and constructions","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the median of 11, 4, 7, 13, 5.","answer":7,"hint":"Order the values, then choose the middle one.","solution":"The ordered list is 4, 5, 7, 11, 13. Its middle value is 7.","id":"x100-04","subject":"maths","topic":"Finding the median","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the mode of 4, 6, 6, 8, 6, 10.","answer":6,"hint":"Look for the value occurring most frequently.","solution":"6 occurs three times; every other value occurs once.","id":"x101-04","subject":"maths","topic":"Finding the mode","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the range of −4, 2, 8, 0.","answer":12,"hint":"Subtract the minimum from the maximum.","solution":"8 − (−4) = 12.","id":"x102-04","subject":"maths","topic":"Finding the range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A data set has lower quartile 7 and upper quartile 23. Find its interquartile range.","answer":16,"hint":"IQR = upper quartile − lower quartile.","solution":"23 − 7 = 16.","id":"x103-04","subject":"maths","topic":"Interquartile range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A grouped table has 2 values in 0 ≤ x < 10 and 6 values in 10 ≤ x < 20. Estimate the mean, to 3 decimal places.","answer":12.5,"hint":"Use class midpoints 5 and 15, multiply by frequencies, then divide by total frequency.","solution":"Estimated total = 2×5 + 6×15 = 100. Divide by 8 to get 12.500.","id":"x104-04","subject":"maths","topic":"Estimated mean from grouped data","group":"Statistics","tier":"Both","calculator":true,"marks":3},{"prompt":"A histogram class has width 5 and frequency 30. Find its frequency density.","answer":6,"hint":"Frequency density = frequency ÷ class width.","solution":"30 ÷ 5 = 6.","id":"x105-04","subject":"maths","topic":"Frequency density","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"Class frequencies, in ascending order, are 4, 6, 8, 10. Find the cumulative frequency at the end of the third class.","answer":18,"hint":"Add all frequencies up to and including the third class.","solution":"4 + 6 + 8 = 18.","id":"x106-04","subject":"maths","topic":"Cumulative frequency","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A box plot has minimum 4, lower quartile 7, median 10, upper quartile 13, maximum 19. Read off its median.","answer":10,"hint":"The median is the line inside the box.","solution":"The median line is at 10. The ends of the box are the quartiles.","id":"x107-04","subject":"maths","topic":"Box plots","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A school has 600 pupils; 120 are in a chosen group. In a proportional sample of 40 pupils, how many should come from that group?","answer":8,"hint":"Multiply the sample size by the group proportion.","solution":"40 × 120/600 = 8 pupils.","id":"x108-04","subject":"maths","topic":"Stratified sampling","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"An experiment succeeds 7 times out of 20 trials. Find the relative frequency as a fraction or decimal.","answer":0.35,"hint":"Divide the number of successes by the number of trials.","solution":"Relative frequency = 7/20 = 0.35.","id":"x109-04","subject":"maths","topic":"Relative frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"An event has probability 0.3. It is tested 80 times. Find its expected frequency.","answer":24,"hint":"Multiply probability by number of trials.","solution":"0.3 × 80 = 24. This is an expectation, not a guarantee.","id":"x110-04","subject":"maths","topic":"Expected frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Two independent events have probabilities 1/2 and 4/12. Find the probability that both occur.","answer":0.1666666667,"hint":"Multiply the probabilities of independent events.","solution":"1/2 × 4/12 = 4/24.","id":"x111-04","subject":"maths","topic":"Independent events","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A bag has 6 red counters and 3 blue counters. Two counters are drawn without replacement. Find P(both red), to 3 decimal places.","answer":0.417,"hint":"The second draw has one fewer red counter and one fewer counter altogether.","solution":"P = (6/9) × (5/8) = 0.417.","id":"x112-04","subject":"maths","topic":"Sampling without replacement","group":"Probability","tier":"Higher","calculator":true,"marks":3},{"prompt":"Of 9 club members who play tennis, 4 also swim. A member is chosen from the tennis players only. Find P(swims), as a fraction or decimal.","answer":0.4444444444,"hint":"Use the restricted tennis group as the denominator.","solution":"Given that the person plays tennis, P(swims) = 4/9.","id":"x113-04","subject":"maths","topic":"Conditional probability","group":"Probability","tier":"Higher","calculator":false,"marks":2},{"prompt":"Set A contains 20 people including 6 in A ∩ B. How many are in A only?","answer":14,"hint":"Subtract the intersection from the total in A.","solution":"20 − 6 = 14 people.","id":"x114-04","subject":"maths","topic":"Venn diagram regions","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"n(A) = 14, n(B) = 16, and n(A ∩ B) = 7. Find n(A ∪ B).","answer":23,"hint":"Add the two set sizes and subtract the overlap once.","solution":"14 + 16 − 7 = 23.","id":"x115-04","subject":"maths","topic":"Set union","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A fair coin is tossed, then a fair 7-sided die numbered 1 to 7 is rolled. Find P(heads and a 1).","answer":0.0714285714,"hint":"Multiply the branch probabilities along the path.","solution":"(1/2) × (1/7) = 1/14.","id":"x116-04","subject":"maths","topic":"Tree diagrams","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Plot the listed points for y = x³ − 1. Use x = -2, -1, 0, 1, 2. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[-2,-9],[-1,-2],[0,-1],[1,0],[2,7]],"curve":"quadratic","range":[-3,3,-14,14],"expression":"y = x³ − 1","hint":"Cube each x, preserving its sign, then add the constant.","solution":"The coordinates are (-2, -9), (-1, -2), (0, -1), (1, 0), (2, 7). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x117-04","subject":"maths","topic":"Cubic graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 12/x + 3 for 1 ≤ x ≤ 6. Use x = 1, 2, 3, 4, 6. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[1,15.0],[2,9.0],[3,7.0],[4,6.0],[6,5.0]],"curve":"quadratic","range":[0,7,0,23],"expression":"y = 12/x + 3 for 1 ≤ x ≤ 6","hint":"Divide 12 by x, then add the constant; x = 0 is not allowed.","solution":"The coordinates are (1, 15.0), (2, 9.0), (3, 7.0), (4, 6.0), (6, 5.0). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x118-04","subject":"maths","topic":"Reciprocal graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 2^x + 3. Use x = 0, 1, 2, 3. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[0,4],[1,5],[2,7],[3,11]],"curve":"quadratic","range":[-1,4,0,18],"expression":"y = 2^x + 3","hint":"Calculate the power of 2 first, then add the constant.","solution":"The coordinates are (0, 4), (1, 5), (2, 7), (3, 11). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x119-04","subject":"maths","topic":"Exponential graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"The graph y = x² is translated upward by 6 units. Find the new y-coordinate of its turning point.","answer":6,"hint":"An upward translation adds the same amount to every y-coordinate.","solution":"The old turning point is (0, 0); the new one is (0, 6).","id":"x120-04","subject":"maths","topic":"Translating graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A straight segment on a distance-time graph runs from (0 hours, 0 km) to (2 hours, 48 km). Find the speed in km/h.","answer":24,"hint":"Speed is the gradient: distance change divided by time change.","solution":"48 km ÷ 2 h = 24 km/h.","id":"x121-04","subject":"maths","topic":"Distance-time graphs","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A velocity-time graph rises in a straight line from 0 m/s to 20 m/s in 5 seconds. Find acceleration in m/s².","answer":4,"hint":"Acceleration is change in velocity divided by time.","solution":"(20 − 0)/5 = 4 m/s².","id":"x122-04","subject":"maths","topic":"Velocity-time gradients","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A tangent to a curve passes through (1, 4) and (3, 14). Estimate the gradient of the curve at the contact point.","answer":5,"hint":"Use the gradient of the tangent, not a chord through two curve points.","solution":"(14 − 4)/(3 − 1) = 5.","id":"x123-04","subject":"maths","topic":"Tangents and rates of change","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A velocity-time graph forms a triangle with base 6 seconds and maximum velocity 8 m/s. Find the displacement in metres.","answer":24,"hint":"Displacement is the signed area under a velocity-time graph.","solution":"Area = ½ × 6 × 8 = 24 m.","id":"x124-04","subject":"maths","topic":"Area under velocity-time graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"The lines y = x + 4 and y = 3x intersect. Find the x-coordinate of the intersection.","answer":2.0,"hint":"At the intersection, both expressions for y are equal.","solution":"x + 4 = 3x, so 2x = 4 and x = 2.0.","id":"x125-04","subject":"maths","topic":"Graphical simultaneous equations","group":"Graphs","tier":"Both","calculator":false,"marks":3},{"prompt":"Which point satisfies both x > 4 and y < 3?","kind":"choice","options":["(5, 2)","(4, 2)","(5, 4)","(3, 0)"],"correct":0,"answer":null,"hint":"Test both strict inequalities for each coordinate pair.","solution":"Only (5, 2) has x strictly greater than 4 and y strictly less than 3.","id":"x126-04","subject":"maths","topic":"Regions satisfying inequalities","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate 8 + 7 × 4.","answer":36,"hint":"Do multiplication before addition.","solution":"7 × 4 = 28; then add 8 to get 36.","id":"x001-05","subject":"maths","topic":"Order of operations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"The temperature is −7°C. It falls by 9°C. What is the new temperature in °C?","answer":-16,"hint":"A fall makes the number more negative.","solution":"−7 − 9 = −16°C.","id":"x002-05","subject":"maths","topic":"Calculating with negatives","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the value of the hundreds digit in 1605?","answer":600,"hint":"Identify the digit three places from the right.","solution":"The hundreds digit is 6, so its value is 6 × 100 = 600.","id":"x003-05","subject":"maths","topic":"Place value","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 7.376 to two decimal places.","answer":7.38,"hint":"Look at the third decimal digit.","solution":"The third digit is 6, so round the hundredths up: 7.38.","id":"x004-05","subject":"maths","topic":"Rounding decimal places","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 2819 to two significant figures.","answer":2800,"hint":"Count significant digits from the first non-zero digit.","solution":"The first two significant figures are in the thousands and hundreds columns. Rounding 2819 to the nearest 100 gives 2800.","id":"x005-05","subject":"maths","topic":"Significant figures","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Estimate 7.9 × 19.8 by rounding each number to the nearest whole number first.","answer":160,"hint":"Follow the requested rounding method for both numbers.","solution":"7.9 rounds to 8; 19.8 rounds to 20. The estimate is 160.","id":"x006-05","subject":"maths","topic":"Estimating calculations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"How many positive factors does 64 have?","answer":7,"hint":"For a power of 2, list 2⁰ up to the highest power.","solution":"64 = 2^6. Its factors are 2⁰ through 2^6, giving 7 factors.","id":"x007-05","subject":"maths","topic":"Factors","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the smallest multiple of 8 that is strictly greater than 80?","answer":88,"hint":"The number given is already the tenth multiple.","solution":"The next multiple is 11 × 8 = 88.","id":"x008-05","subject":"maths","topic":"Multiples","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Which number in this list is prime? Set 5.","kind":"choice","options":["32","42","63","23"],"correct":3,"answer":null,"hint":"A prime has exactly two positive factors: 1 and itself.","solution":"23 has no positive factors except 1 and itself. The other numbers have explicit factors 4, 6 or 9.","id":"x009-05","subject":"maths","topic":"Prime numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"In the prime factorisation of 288, what is the exponent of 2?","answer":5,"hint":"Keep dividing by 2 until the remaining number is odd.","solution":"288 = 2^5 × 3², so the exponent is 5.","id":"x010-05","subject":"maths","topic":"Prime factorisation","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the highest common factor of 60 and 90.","answer":30,"hint":"Look for the largest factor that divides both numbers.","solution":"60 = 2 × 30 and 90 = 3 × 30. Since 2 and 3 are coprime, the HCF is 30.","id":"x011-05","subject":"maths","topic":"Highest common factor","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the lowest common multiple of 20 and 30.","answer":60,"hint":"Find the HCF first, or list the multiples.","solution":"The HCF is 10. LCM = (20 × 30) ÷ 10 = 60.","id":"x012-05","subject":"maths","topic":"Lowest common multiple","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 5/12 + 1/8. Give a fraction or decimal.","answer":0.5416666667,"hint":"Use a common denominator of 24.","solution":"5/12 = 10/24 and 1/8 = 3/24. The sum is 13/24.","id":"x013-05","subject":"maths","topic":"Adding fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 5/11 × 3/5. Give a fraction or decimal.","answer":0.2727272727,"hint":"Multiply numerators and denominators.","solution":"(5 × 3)/(11 × 5) = 15/55. Simplify if possible.","id":"x014-05","subject":"maths","topic":"Multiplying fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 5/12 ÷ 5/6. Give a fraction or decimal.","answer":0.5,"hint":"Multiply by the reciprocal of 5/6.","solution":"5/12 × 6/5 = 30/60 = 5/10.","id":"x015-05","subject":"maths","topic":"Dividing fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 5 3/4 as a decimal.","answer":5.75,"hint":"The fraction part is three quarters, or 0.75.","solution":"5 + 0.75 = 5.75.","id":"x016-05","subject":"maths","topic":"Mixed numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A club has 120 members. Three eighths cycle to the club. How many members cycle?","answer":45,"hint":"Divide by 8 to find one eighth, then multiply by 3.","solution":"120 ÷ 8 × 3 = 45.","id":"x017-05","subject":"maths","topic":"Fractions of quantities","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 0.151515… (the block 15 repeats) as a fraction or decimal.","answer":0.1515151515,"hint":"For a two-digit repeating block, compare 100x with x.","solution":"If x = 0.1515…, then 100x − x = 15; hence x = 15/99.","id":"x018-05","subject":"maths","topic":"Recurring decimals","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Simplify 3^6 × 3^8 to 3^k. Find k.","answer":14,"hint":"Add exponents when multiplying powers of the same base.","solution":"k = 6 + 8 = 14.","id":"x019-05","subject":"maths","topic":"Index laws","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Evaluate 6^−2. Give a fraction or decimal.","answer":0.0277777778,"hint":"A negative exponent gives the reciprocal of the positive power.","solution":"6^−2 = 1/(6²) = 1/36.","id":"x020-05","subject":"maths","topic":"Negative indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Evaluate 343^(2/3).","answer":49,"hint":"Take the cube root, then square the result.","solution":"The cube root of 343 is 7; its square is 49.","id":"x021-05","subject":"maths","topic":"Fractional indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write √72 in the form a√2. Find a.","answer":6,"hint":"Look for a square factor inside the root.","solution":"√(36 × 2) = 6√2, so a = 6.","id":"x022-05","subject":"maths","topic":"Simplifying surds","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write 15/√3 in the form a√3. Find a.","answer":5,"hint":"Multiply numerator and denominator by √3.","solution":"(15√3)/3 = 5√3.","id":"x023-05","subject":"maths","topic":"Rationalising denominators","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate (2 × 10^5) × (3 × 10²). Write the result as 6 × 10^k. Find k.","answer":7,"hint":"Multiply the coefficients and add powers of ten.","solution":"2 × 3 = 6 and 5 + 2 = 7, so k = 7.","id":"x024-05","subject":"maths","topic":"Calculating in standard form","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A length is 15 cm to the nearest centimetre. Give the lower bound in cm.","answer":14.5,"hint":"The rounding interval extends half a centimetre either side.","solution":"The lower bound is 15 − 0.5 = 14.5 cm; the upper bound is 15.5 cm and is excluded.","id":"x025-05","subject":"maths","topic":"Error intervals","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle has length 15 cm and width 9 cm, both to the nearest centimetre. Find the upper bound for its area in cm².","answer":147.25,"hint":"Use the upper bound for each positive length.","solution":"Upper area bound = 15.5 × 9.5 = 147.25 cm².","id":"x026-05","subject":"maths","topic":"Upper and lower bounds","group":"Number","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify 7x + 9x − 3x to ax. Find a.","answer":13,"hint":"Combine only the coefficients of x.","solution":"a = 7 + 9 − 3 = 13.","id":"x027-05","subject":"maths","topic":"Collecting like terms","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand 7(x + 6). What is the constant term?","answer":42,"hint":"Multiply both terms inside the bracket.","solution":"The expansion is 7x + 42.","id":"x028-05","subject":"maths","topic":"Expanding a single bracket","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand (x + 5)(x + 8). What is the coefficient of x?","answer":13,"hint":"Multiply every term in one bracket by every term in the other.","solution":"x² + 8x + 5x + 40 = x² + 13x + 40.","id":"x029-05","subject":"maths","topic":"Expanding double brackets","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise fully 10x + 30.","kind":"choice","options":["10(x + 6)","5(x + 3)","30(x + 2)","10(x + 3)"],"correct":3,"answer":null,"hint":"Take out the highest common factor of the two coefficients.","solution":"Both terms contain 10. Dividing gives x and 3, so the result is 10(x + 3).","id":"x030-05","subject":"maths","topic":"Factorising with a common factor","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise x² + 13x + 40.","kind":"choice","options":["(x − 5)(x − 8)","(x + 6)(x + 7)","(x − 5)(x + 8)","(x + 5)(x + 8)"],"correct":3,"answer":null,"hint":"Find two numbers whose product is the constant and whose sum is the x coefficient.","solution":"5 × 8 = 40 and 5 + 8 = 13.","id":"x031-05","subject":"maths","topic":"Factorising quadratics","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Find 2a² − b when a = 5 and b = 8.","answer":42,"hint":"Square a before multiplying by 2.","solution":"2 × 5² − 8 = 42.","id":"x032-05","subject":"maths","topic":"Substitution","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The formula is y = 7x − 5. If y = 37, find x.","answer":6,"hint":"Add the constant to y, then divide by the coefficient of x.","solution":"x = (y + 5)/7 = 42/7 = 6.","id":"x033-05","subject":"maths","topic":"Changing the subject","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the smallest integer satisfying 3x + 5 > 20.","answer":6,"hint":"Subtract the constant, divide by 3, then respect the strict inequality.","solution":"3x > 15, so x > 5. The smallest integer is 6.","id":"x034-05","subject":"maths","topic":"Linear inequalities","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Solve x + y = 16 and x − y = 6. Give x.","answer":11,"hint":"Add the two equations to eliminate y.","solution":"2x = 22, so x = 11.","id":"x035-05","subject":"maths","topic":"Simultaneous linear equations","group":"Algebra","tier":"Both","calculator":false,"marks":3},{"prompt":"The graphs y = x² and y = 25 meet. Give the positive x-coordinate.","answer":5,"hint":"Substitute to obtain x² equal to the constant.","solution":"x² = 25, so x = ±5. The positive value is 5.","id":"x036-05","subject":"maths","topic":"Simultaneous nonlinear equations","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"Write x² + 10x + 32 as (x + a)² + b. Find b.","answer":7,"hint":"Half the x coefficient gives a. Subtract a² from the constant.","solution":"a = 5. Subtract 25 from the constant 32 to get b = 7.","id":"x037-05","subject":"maths","topic":"Completing the square","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Use the quadratic formula to find the positive root of x² + x − 30 = 0.","answer":5,"hint":"Identify a, b and c. Use x = (−b ± √(b² − 4ac))/(2a).","solution":"a=1, b=1, c=−30. The discriminant is 1 + 120 = 121. The positive root is (−1 + 11)/2 = 5.","id":"x038-05","subject":"maths","topic":"Quadratic formula","group":"Algebra","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify (7x)/(14x²) for x ≠ 0, then evaluate at x = 5.","answer":0.1,"hint":"Cancel the common numerical factor and one factor of x.","solution":"The expression simplifies to 1/(2x). At x = 5, it is 1/10.","id":"x039-05","subject":"maths","topic":"Algebraic fractions","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"The difference (k + 1)² − k² simplifies to 2k + 1. Use this identity to find the difference between the squares of 9 and 10.","answer":19,"hint":"Expand the square before cancelling k².","solution":"Expanding proves (k + 1)² − k² = 2k + 1. Set k = 9: the difference is 19.","id":"x040-05","subject":"maths","topic":"Algebraic proof","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x − 5. Find f(7).","answer":16,"hint":"Replace every x with the specified input.","solution":"f(7) = 3(7) − 5 = 16.","id":"x041-05","subject":"maths","topic":"Function notation","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"f(x) = 2x + 1 and g(x) = x². Find f(g(5)).","answer":51,"hint":"Apply the inside function first.","solution":"g(5) = 25; f(25) = 51.","id":"x042-05","subject":"maths","topic":"Composite functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x + 5. Find f⁻¹(20).","answer":5,"hint":"Undo the addition, then undo the multiplication.","solution":"f⁻¹(y) = (y − 5)/3. With y = 20, this gives 5.","id":"x043-05","subject":"maths","topic":"Inverse functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"x₀ = 5. Use x_(k+1) = (x_k + 4)/2 to calculate x₂.","answer":4.25,"hint":"Calculate x₁ first and substitute that new value again.","solution":"x₁ = (5 + 4)/2 = 4.5. Then x₂ = (4.5 + 4)/2 = 4.25.","id":"x044-05","subject":"maths","topic":"Iteration","group":"Algebra","tier":"Higher","calculator":true,"marks":2},{"prompt":"A geometric sequence starts at 6 and has common ratio 3. Find its fourth term.","answer":162,"hint":"Multiply by 3 three times after the first term.","solution":"The fourth term is 6 × 3³ = 162.","id":"x045-05","subject":"maths","topic":"Geometric sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The nth term is n² + 5n + 2. Find the fifth term.","answer":52,"hint":"Replace each occurrence of n (the position variable) with 5.","solution":"5² + 5 × 5 + 2 = 52.","id":"x046-05","subject":"maths","topic":"Quadratic sequences","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sequence begins 5, 6. Each new term is the sum of the preceding two. Find the fifth term.","answer":28,"hint":"Build the third and fourth terms before the fifth.","solution":"The terms are 5, 6, 11, 17, 28.","id":"x047-05","subject":"maths","topic":"Fibonacci-type sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the x-coordinate of the midpoint of (5, 2) and (17, 8).","answer":11,"hint":"Average the two x-coordinates.","solution":"(5 + 17)/2 = 11. The full midpoint is (11, 5).","id":"x048-05","subject":"maths","topic":"Midpoints","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the distance between (0, 0) and (15, 20).","answer":25,"hint":"Use the horizontal and vertical differences in Pythagoras.","solution":"√(15² + 20²) = 25 units.","id":"x049-05","subject":"maths","topic":"Distance between coordinates","group":"Coordinate geometry","tier":"Both","calculator":true,"marks":3},{"prompt":"A line is parallel to y = 6x − 4 and passes through (0, 5). Give its gradient.","answer":6,"hint":"Parallel non-vertical lines have equal gradients.","solution":"The given line has gradient 6, so the parallel line does too.","id":"x050-05","subject":"maths","topic":"Parallel lines","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the gradient of a line perpendicular to y = 6x + 2. Give a fraction or decimal.","answer":-0.1666666667,"hint":"For non-zero gradients, the perpendicular gradient is the negative reciprocal.","solution":"The negative reciprocal of 6 is −1/6.","id":"x051-05","subject":"maths","topic":"Perpendicular lines","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A line passes through (1, 11) and (3, 21). Write it as y = mx + c. Find c.","answer":6,"hint":"Find the gradient from the two points, then substitute a point.","solution":"m = (21 − 11)/2 = 5. Then c = 11 − 5 = 6.","id":"x052-05","subject":"maths","topic":"Equation of a line through points","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"A pack of 8 notebooks costs £48. Find the price per notebook in pounds.","answer":6,"hint":"Divide cost by number of items.","solution":"£48 ÷ 8 = £6 per notebook.","id":"x053-05","subject":"maths","topic":"Best buys and unit pricing","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"£1 exchanges for €1.20. How many euros are exchanged for £125?","answer":150,"hint":"Multiply the pound amount by the euros-per-pound rate.","solution":"125 × 1.20 = €150.","id":"x054-05","subject":"maths","topic":"Currency conversion","group":"Proportion and rates","tier":"Both","calculator":true,"marks":2},{"prompt":"A recipe for 4 people uses 180 g of rice. How many grams are needed for 6 people?","answer":270.0,"hint":"Scale every ingredient by 6/4.","solution":"180 × 6/4 = 270.0 g.","id":"x055-05","subject":"maths","topic":"Scaling recipes","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"A map has scale 1:50 000. Two places are 5 cm apart on the map. Find their real distance in kilometres.","answer":2.5,"hint":"Convert the scaled centimetres into kilometres using 100 000 cm = 1 km.","solution":"5 × 50 000 = 250000 cm = 2.5 km.","id":"x056-05","subject":"maths","topic":"Map scales","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is directly proportional to x. When x = 3, y = 18. Find y when x = 8.","answer":48,"hint":"Find k in y = kx.","solution":"k = 18/3 = 6; hence y = 6 × 8 = 48.","id":"x057-05","subject":"maths","topic":"Direct proportion","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is inversely proportional to x. When x = 2, y = 30. Find y when x = 3.","answer":20,"hint":"The product xy stays constant.","solution":"k = 2 × 30 = 60. Thus y = 60/3 = 20.","id":"x058-05","subject":"maths","topic":"Inverse proportion","group":"Proportion and rates","tier":"Higher","calculator":false,"marks":2},{"prompt":"£500 earns 5% compound interest each year. Find the balance after 2 years in pounds.","answer":551.25,"hint":"Multiply by 1.05 for each year.","solution":"£500 × 1.05² = £551.25.","id":"x059-05","subject":"maths","topic":"Compound interest","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A bicycle worth £1250 loses 20% of its value each year. Find its value after 2 years in pounds.","answer":800,"hint":"Retain 80% each year, using the multiplier 0.8 twice.","solution":"£1250 × 0.8² = £800.","id":"x060-05","subject":"maths","topic":"Depreciation","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A culture begins with 1000 cells and increases by 10% each hour. Find the modelled count after 2 hours.","answer":1210,"hint":"Use the growth multiplier 1.1 twice.","solution":"1000 × 1.1² = 1210 cells.","id":"x061-05","subject":"maths","topic":"Repeated percentage growth","group":"Finance","tier":"Both","calculator":true,"marks":2},{"prompt":"A block has mass 360 g and volume 60 cm³. Find its density in g/cm³.","answer":6,"hint":"Density = mass ÷ volume.","solution":"360 ÷ 60 = 6 g/cm³.","id":"x062-05","subject":"maths","topic":"Density","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A force of 525 N acts on an area of 15 m². Find pressure in N/m².","answer":35,"hint":"Pressure = force ÷ area.","solution":"525 ÷ 15 = 35 N/m².","id":"x063-05","subject":"maths","topic":"Pressure","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"Convert 6 m² into cm².","answer":60000,"hint":"Square the linear conversion: 1 m = 100 cm.","solution":"1 m² = 100² = 10 000 cm². Therefore 6 m² = 60000 cm².","id":"x064-05","subject":"maths","topic":"Metric area conversions","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A journey starts at 09:15 and ends at 11:45. Find its duration in minutes.","answer":150,"hint":"Count the full hours and the remaining minutes.","solution":"From 09:15 to 11:15 is 120 minutes, then another 30. Total = 150 minutes.","id":"x065-05","subject":"maths","topic":"Time calculations","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle is 13 cm by 9 cm. A 2 cm by 2 cm square is cut from one corner. Find the perimeter of the remaining L-shape in cm.","answer":44,"hint":"The two removed edge lengths are replaced by two equal inner edge lengths.","solution":"The perimeter stays equal to the original rectangle: 2(13 + 9) = 44 cm.","id":"x066-05","subject":"maths","topic":"Perimeter of compound shapes","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 6 cm. Express its circumference as kπ cm. Find k.","answer":12,"hint":"Circumference is 2πr.","solution":"2π × 6 = 12π cm.","id":"x067-05","subject":"maths","topic":"Circle circumference","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 7 cm. Its area is kπ cm². Find k.","answer":49,"hint":"Square the radius and multiply by π.","solution":"Area = π × 7² = 49π cm².","id":"x068-05","subject":"maths","topic":"Area of circles","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A semicircle has radius 7 cm. Its perimeter is πr + d. Find the straight-edge length d in cm.","answer":14,"hint":"The straight edge is the diameter, not the radius.","solution":"d = 2r = 2 × 7 = 14 cm. The complete perimeter is 7π + 14 cm.","id":"x069-05","subject":"maths","topic":"Semicircle perimeter","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 60° and radius 15 cm. Its arc length is kπ cm. Find k.","answer":5,"hint":"Take 60/360 of the circumference.","solution":"(60/360) × 2π × 15 = 5π cm.","id":"x070-05","subject":"maths","topic":"Arc length","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 90° and radius 10 cm. Its area is kπ cm². Find k.","answer":25,"hint":"Take one quarter of the full circle area.","solution":"(90/360) × π × 10² = 25π cm².","id":"x071-05","subject":"maths","topic":"Sector area","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A triangular prism has triangular cross-section base 7 cm, height 6 cm, and prism length 10 cm. Find its volume in cm³.","answer":210,"hint":"Find the triangle area, then multiply by the prism length.","solution":"Cross-section = ½ × 7 × 6 = 21 cm². Volume = 210 cm³.","id":"x072-05","subject":"maths","topic":"Volume of prisms","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A cylinder has radius 6 cm and height 5 cm. Its volume is kπ cm³. Find k.","answer":180,"hint":"Multiply the circular base area by the height.","solution":"πr²h = π × 6² × 5 = 180π cm³.","id":"x073-05","subject":"maths","topic":"Volume of cylinders","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A cone has radius 6 cm and perpendicular height 9 cm. Its volume is kπ cm³. Find k.","answer":108,"hint":"A cone has one third of the corresponding cylinder volume.","solution":"V = πr²h/3 = π × 6² × 9/3 = 108π cm³.","id":"x074-05","subject":"maths","topic":"Volume of cones","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sphere has radius 15 cm. Its volume is kπ cm³. Find k.","answer":4500,"hint":"Use V = 4πr³/3.","solution":"(4/3) × 15³ = 4500, so V = 4500π cm³.","id":"x075-05","subject":"maths","topic":"Volume of spheres","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A cuboid measures 6 cm by 3 cm by 4 cm. Find its total surface area in cm².","answer":108,"hint":"There are two faces of each of the three different rectangular areas.","solution":"2[3(6) + 4(6) + 3×4] = 108 cm².","id":"x076-05","subject":"maths","topic":"Surface area of cuboids","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A closed cylinder has radius 6 cm and height 4 cm. Its total surface area is kπ cm². Find k.","answer":120,"hint":"Include two circular ends and the curved surface.","solution":"2r² + 2rh = 2(6²) + 2(6)(4) = 120.","id":"x077-05","subject":"maths","topic":"Cylinder surface area","group":"Geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"Two similar shapes have length scale factor 3 from small to large. A small side is 7 cm. Find the matching large side.","answer":21,"hint":"Multiply corresponding lengths by the length scale factor.","solution":"7 × 3 = 21 cm.","id":"x078-05","subject":"maths","topic":"Similarity of lengths","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Two similar shapes have length scale factor 2. The smaller area is 8 cm². Find the larger area.","answer":32,"hint":"Square the length scale factor for areas.","solution":"Area factor = 2² = 4. Larger area = 8 × 4 = 32 cm².","id":"x079-05","subject":"maths","topic":"Similarity of areas","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"Two similar solids have length scale factor 3. The smaller volume is 6 cm³. Find the larger volume.","answer":162,"hint":"Cube the length scale factor for volumes.","solution":"Volume factor = 3³ = 27. Larger volume = 162 cm³.","id":"x080-05","subject":"maths","topic":"Similarity of volumes","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A triangle has two angles 45° and 65°. Find the third angle in degrees.","answer":70,"hint":"Interior angles in a triangle total 180°.","solution":"180 − 45 − 65 = 70°.","id":"x081-05","subject":"maths","topic":"Triangle angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A regular polygon has 9 sides. Find its exterior angle in degrees, to 3 decimal places if needed.","answer":40.0,"hint":"The exterior angles total 360°.","solution":"Each exterior angle is 360/9 = 40.000°.","id":"x082-05","subject":"maths","topic":"Exterior angles of polygons","group":"Geometry","tier":"Both","calculator":true,"marks":2},{"prompt":"A transversal crosses two parallel lines. One of a pair of co-interior angles is 75°. Find the other angle in degrees.","answer":105,"hint":"Co-interior angles on parallel lines sum to 180°.","solution":"180 − 75 = 105°.","id":"x083-05","subject":"maths","topic":"Angles in parallel lines","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the sum of the interior angles of a polygon with 8 sides.","answer":1080,"hint":"Use (number of sides − 2) × 180°.","solution":"(8 − 2) × 180 = 1080°.","id":"x084-05","subject":"maths","topic":"Polygon interior-angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"The bearing of B from A is 045°. Find the bearing of A from B as a number of degrees.","answer":225,"hint":"A reverse bearing differs by 180°.","solution":"45 + 180 = 225°.","id":"x085-05","subject":"maths","topic":"Three-figure bearings","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A right-angled triangle has hypotenuse 14 cm and an angle of 30°. Find the side opposite that angle in cm.","answer":7,"hint":"Use sin(angle) = opposite/hypotenuse.","solution":"Opposite = 14 × sin30° = 7 cm.","id":"x086-05","subject":"maths","topic":"Right-angle trigonometry","group":"Trigonometry","tier":"Both","calculator":true,"marks":3},{"prompt":"In a triangle, side a = 7 cm is opposite 30°, and side b is opposite 90°. Find b in cm.","answer":14,"hint":"Use a/sin A = b/sin B.","solution":"b = 7 × sin90°/sin30° = 14 cm.","id":"x087-05","subject":"maths","topic":"Sine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides of a triangle are 7 cm each, with included angle 60°. Find the opposite side in cm.","answer":7,"hint":"Use c² = a² + b² − 2ab cos C.","solution":"c² = 2(7²) − 2(7²)cos60° = 49, so c = 7 cm.","id":"x088-05","subject":"maths","topic":"Cosine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides are 7 cm and 8 cm, with included angle 30°. Find the triangle area in cm².","answer":14,"hint":"Use area = ½ab sin C.","solution":"½ × 7 × 8 × sin30° = 14 cm².","id":"x089-05","subject":"maths","topic":"Triangle area using sine","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"An angle at the circumference is 25°. The central angle subtended by the same arc is less than 180°. Find it.","answer":50,"hint":"The angle at the centre is twice the angle at the circumference on the same arc.","solution":"2 × 25 = 50°.","id":"x090-05","subject":"maths","topic":"Angles at the centre","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"One angle of a cyclic quadrilateral is 100°. Find its opposite angle.","answer":80,"hint":"Opposite angles in a cyclic quadrilateral total 180°.","solution":"180 − 100 = 80°.","id":"x091-05","subject":"maths","topic":"Cyclic quadrilaterals","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"A tangent and chord form an angle of 35°. Find the angle subtended by that chord in the alternate segment.","answer":35,"hint":"The tangent-chord angle equals the angle in the alternate segment.","solution":"By the alternate segment theorem, the required angle is 35°.","id":"x092-05","subject":"maths","topic":"Alternate segment theorem","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"Vectors a = (5, 3) and b = (7, −1). Find the x-component of a + b.","answer":12,"hint":"Add corresponding components.","solution":"a + b = (12, 2), so the x-component is 12.","id":"x093-05","subject":"maths","topic":"Adding vectors","group":"Vectors","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the magnitude of the vector (15, 20).","answer":25,"hint":"Use Pythagoras on the two components.","solution":"√(15² + 20²) = 25.","id":"x094-05","subject":"maths","topic":"Vector magnitude","group":"Vectors","tier":"Higher","calculator":true,"marks":2},{"prompt":"Rotate (5, 7) by 90° anticlockwise about the origin. Find the new x-coordinate.","answer":-7,"hint":"The rule for 90° anticlockwise is (x,y) → (−y,x).","solution":"The image is (−7, 5), so its x-coordinate is −7.","id":"x095-05","subject":"maths","topic":"Rotations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Enlarge (5, 2) by scale factor 3 about the origin. Find the new x-coordinate.","answer":15,"hint":"Multiply both coordinates by the scale factor.","solution":"The image is (15, 6).","id":"x096-05","subject":"maths","topic":"Enlargements","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Translate (5, 4) by the vector (−3, 2). Find the new x-coordinate.","answer":2,"hint":"Add the x-component of the vector to the x-coordinate.","solution":"The image is (2, 6).","id":"x097-05","subject":"maths","topic":"Translations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Reflect (5, 8) in the line y = x. Find the new x-coordinate.","answer":8,"hint":"Reflection in y = x swaps the coordinates.","solution":"The image is (8, 5).","id":"x098-05","subject":"maths","topic":"Reflections","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Points must be exactly 7 cm from a fixed point P. What is their locus?","kind":"choice","options":["A circle centred at P with diameter 7 cm","A straight line through P","A perpendicular bisector through P","A circle centred at P with radius 7 cm"],"correct":3,"answer":null,"hint":"A fixed distance from one point defines a circle.","solution":"All points on a circle of radius 7 cm are exactly 7 cm from its centre P.","id":"x099-05","subject":"maths","topic":"Loci and constructions","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the median of 12, 5, 8, 14, 6.","answer":8,"hint":"Order the values, then choose the middle one.","solution":"The ordered list is 5, 6, 8, 12, 14. Its middle value is 8.","id":"x100-05","subject":"maths","topic":"Finding the median","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the mode of 5, 7, 7, 9, 7, 11.","answer":7,"hint":"Look for the value occurring most frequently.","solution":"7 occurs three times; every other value occurs once.","id":"x101-05","subject":"maths","topic":"Finding the mode","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the range of −5, 2, 9, 0.","answer":14,"hint":"Subtract the minimum from the maximum.","solution":"9 − (−5) = 14.","id":"x102-05","subject":"maths","topic":"Finding the range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A data set has lower quartile 8 and upper quartile 27. Find its interquartile range.","answer":19,"hint":"IQR = upper quartile − lower quartile.","solution":"27 − 8 = 19.","id":"x103-05","subject":"maths","topic":"Interquartile range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A grouped table has 2 values in 0 ≤ x < 10 and 7 values in 10 ≤ x < 20. Estimate the mean, to 3 decimal places.","answer":12.778,"hint":"Use class midpoints 5 and 15, multiply by frequencies, then divide by total frequency.","solution":"Estimated total = 2×5 + 7×15 = 115. Divide by 9 to get 12.778.","id":"x104-05","subject":"maths","topic":"Estimated mean from grouped data","group":"Statistics","tier":"Both","calculator":true,"marks":3},{"prompt":"A histogram class has width 5 and frequency 35. Find its frequency density.","answer":7,"hint":"Frequency density = frequency ÷ class width.","solution":"35 ÷ 5 = 7.","id":"x105-05","subject":"maths","topic":"Frequency density","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"Class frequencies, in ascending order, are 5, 7, 9, 11. Find the cumulative frequency at the end of the third class.","answer":21,"hint":"Add all frequencies up to and including the third class.","solution":"5 + 7 + 9 = 21.","id":"x106-05","subject":"maths","topic":"Cumulative frequency","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A box plot has minimum 5, lower quartile 8, median 11, upper quartile 14, maximum 20. Read off its median.","answer":11,"hint":"The median is the line inside the box.","solution":"The median line is at 11. The ends of the box are the quartiles.","id":"x107-05","subject":"maths","topic":"Box plots","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A school has 600 pupils; 150 are in a chosen group. In a proportional sample of 40 pupils, how many should come from that group?","answer":10,"hint":"Multiply the sample size by the group proportion.","solution":"40 × 150/600 = 10 pupils.","id":"x108-05","subject":"maths","topic":"Stratified sampling","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"An experiment succeeds 8 times out of 20 trials. Find the relative frequency as a fraction or decimal.","answer":0.4,"hint":"Divide the number of successes by the number of trials.","solution":"Relative frequency = 8/20 = 0.4.","id":"x109-05","subject":"maths","topic":"Relative frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"An event has probability 0.3. It is tested 100 times. Find its expected frequency.","answer":30,"hint":"Multiply probability by number of trials.","solution":"0.3 × 100 = 30. This is an expectation, not a guarantee.","id":"x110-05","subject":"maths","topic":"Expected frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Two independent events have probabilities 1/2 and 5/12. Find the probability that both occur.","answer":0.2083333333,"hint":"Multiply the probabilities of independent events.","solution":"1/2 × 5/12 = 5/24.","id":"x111-05","subject":"maths","topic":"Independent events","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A bag has 7 red counters and 3 blue counters. Two counters are drawn without replacement. Find P(both red), to 3 decimal places.","answer":0.467,"hint":"The second draw has one fewer red counter and one fewer counter altogether.","solution":"P = (7/10) × (6/9) = 0.467.","id":"x112-05","subject":"maths","topic":"Sampling without replacement","group":"Probability","tier":"Higher","calculator":true,"marks":3},{"prompt":"Of 10 club members who play tennis, 5 also swim. A member is chosen from the tennis players only. Find P(swims), as a fraction or decimal.","answer":0.5,"hint":"Use the restricted tennis group as the denominator.","solution":"Given that the person plays tennis, P(swims) = 5/10.","id":"x113-05","subject":"maths","topic":"Conditional probability","group":"Probability","tier":"Higher","calculator":false,"marks":2},{"prompt":"Set A contains 23 people including 7 in A ∩ B. How many are in A only?","answer":16,"hint":"Subtract the intersection from the total in A.","solution":"23 − 7 = 16 people.","id":"x114-05","subject":"maths","topic":"Venn diagram regions","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"n(A) = 15, n(B) = 17, and n(A ∩ B) = 8. Find n(A ∪ B).","answer":24,"hint":"Add the two set sizes and subtract the overlap once.","solution":"15 + 17 − 8 = 24.","id":"x115-05","subject":"maths","topic":"Set union","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A fair coin is tossed, then a fair 8-sided die numbered 1 to 8 is rolled. Find P(heads and a 1).","answer":0.0625,"hint":"Multiply the branch probabilities along the path.","solution":"(1/2) × (1/8) = 1/16.","id":"x116-05","subject":"maths","topic":"Tree diagrams","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Plot the listed points for y = x³ + 0. Use x = -2, -1, 0, 1, 2. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[-2,-8],[-1,-1],[0,0],[1,1],[2,8]],"curve":"quadratic","range":[-3,3,-14,14],"expression":"y = x³ + 0","hint":"Cube each x, preserving its sign, then add the constant.","solution":"The coordinates are (-2, -8), (-1, -1), (0, 0), (1, 1), (2, 8). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x117-05","subject":"maths","topic":"Cubic graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 12/x + 4 for 1 ≤ x ≤ 6. Use x = 1, 2, 3, 4, 6. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[1,16.0],[2,10.0],[3,8.0],[4,7.0],[6,6.0]],"curve":"quadratic","range":[0,7,0,23],"expression":"y = 12/x + 4 for 1 ≤ x ≤ 6","hint":"Divide 12 by x, then add the constant; x = 0 is not allowed.","solution":"The coordinates are (1, 16.0), (2, 10.0), (3, 8.0), (4, 7.0), (6, 6.0). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x118-05","subject":"maths","topic":"Reciprocal graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 2^x + 4. Use x = 0, 1, 2, 3. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[0,5],[1,6],[2,8],[3,12]],"curve":"quadratic","range":[-1,4,0,18],"expression":"y = 2^x + 4","hint":"Calculate the power of 2 first, then add the constant.","solution":"The coordinates are (0, 5), (1, 6), (2, 8), (3, 12). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x119-05","subject":"maths","topic":"Exponential graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"The graph y = x² is translated upward by 7 units. Find the new y-coordinate of its turning point.","answer":7,"hint":"An upward translation adds the same amount to every y-coordinate.","solution":"The old turning point is (0, 0); the new one is (0, 7).","id":"x120-05","subject":"maths","topic":"Translating graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A straight segment on a distance-time graph runs from (0 hours, 0 km) to (2 hours, 60 km). Find the speed in km/h.","answer":30,"hint":"Speed is the gradient: distance change divided by time change.","solution":"60 km ÷ 2 h = 30 km/h.","id":"x121-05","subject":"maths","topic":"Distance-time graphs","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A velocity-time graph rises in a straight line from 0 m/s to 25 m/s in 5 seconds. Find acceleration in m/s².","answer":5,"hint":"Acceleration is change in velocity divided by time.","solution":"(25 − 0)/5 = 5 m/s².","id":"x122-05","subject":"maths","topic":"Velocity-time gradients","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A tangent to a curve passes through (1, 5) and (3, 17). Estimate the gradient of the curve at the contact point.","answer":6,"hint":"Use the gradient of the tangent, not a chord through two curve points.","solution":"(17 − 5)/(3 − 1) = 6.","id":"x123-05","subject":"maths","topic":"Tangents and rates of change","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A velocity-time graph forms a triangle with base 6 seconds and maximum velocity 10 m/s. Find the displacement in metres.","answer":30,"hint":"Displacement is the signed area under a velocity-time graph.","solution":"Area = ½ × 6 × 10 = 30 m.","id":"x124-05","subject":"maths","topic":"Area under velocity-time graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"The lines y = x + 5 and y = 3x intersect. Find the x-coordinate of the intersection.","answer":2.5,"hint":"At the intersection, both expressions for y are equal.","solution":"x + 5 = 3x, so 2x = 5 and x = 2.5.","id":"x125-05","subject":"maths","topic":"Graphical simultaneous equations","group":"Graphs","tier":"Both","calculator":false,"marks":3},{"prompt":"Which point satisfies both x > 5 and y < 3?","kind":"choice","options":["(5, 2)","(6, 4)","(4, 0)","(6, 2)"],"correct":3,"answer":null,"hint":"Test both strict inequalities for each coordinate pair.","solution":"Only (6, 2) has x strictly greater than 5 and y strictly less than 3.","id":"x126-05","subject":"maths","topic":"Regions satisfying inequalities","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate 9 + 8 × 4.","answer":41,"hint":"Do multiplication before addition.","solution":"8 × 4 = 32; then add 9 to get 41.","id":"x001-06","subject":"maths","topic":"Order of operations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"The temperature is −8°C. It falls by 10°C. What is the new temperature in °C?","answer":-18,"hint":"A fall makes the number more negative.","solution":"−8 − 10 = −18°C.","id":"x002-06","subject":"maths","topic":"Calculating with negatives","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the value of the hundreds digit in 1706?","answer":700,"hint":"Identify the digit three places from the right.","solution":"The hundreds digit is 7, so its value is 7 × 100 = 700.","id":"x003-06","subject":"maths","topic":"Place value","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 8.376 to two decimal places.","answer":8.38,"hint":"Look at the third decimal digit.","solution":"The third digit is 6, so round the hundredths up: 8.38.","id":"x004-06","subject":"maths","topic":"Rounding decimal places","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 3136 to two significant figures.","answer":3100,"hint":"Count significant digits from the first non-zero digit.","solution":"The first two significant figures are in the thousands and hundreds columns. Rounding 3136 to the nearest 100 gives 3100.","id":"x005-06","subject":"maths","topic":"Significant figures","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Estimate 8.9 × 19.8 by rounding each number to the nearest whole number first.","answer":180,"hint":"Follow the requested rounding method for both numbers.","solution":"8.9 rounds to 9; 19.8 rounds to 20. The estimate is 180.","id":"x006-06","subject":"maths","topic":"Estimating calculations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"How many positive factors does 128 have?","answer":8,"hint":"For a power of 2, list 2⁰ up to the highest power.","solution":"128 = 2^7. Its factors are 2⁰ through 2^7, giving 8 factors.","id":"x007-06","subject":"maths","topic":"Factors","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the smallest multiple of 9 that is strictly greater than 90?","answer":99,"hint":"The number given is already the tenth multiple.","solution":"The next multiple is 11 × 9 = 99.","id":"x008-06","subject":"maths","topic":"Multiples","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Which number in this list is prime? Set 6.","kind":"choice","options":["48","72","29","36"],"correct":2,"answer":null,"hint":"A prime has exactly two positive factors: 1 and itself.","solution":"29 has no positive factors except 1 and itself. The other numbers have explicit factors 4, 6 or 9.","id":"x009-06","subject":"maths","topic":"Prime numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"In the prime factorisation of 576, what is the exponent of 2?","answer":6,"hint":"Keep dividing by 2 until the remaining number is odd.","solution":"576 = 2^6 × 3², so the exponent is 6.","id":"x010-06","subject":"maths","topic":"Prime factorisation","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the highest common factor of 72 and 108.","answer":36,"hint":"Look for the largest factor that divides both numbers.","solution":"72 = 2 × 36 and 108 = 3 × 36. Since 2 and 3 are coprime, the HCF is 36.","id":"x011-06","subject":"maths","topic":"Highest common factor","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the lowest common multiple of 24 and 36.","answer":72,"hint":"Find the HCF first, or list the multiples.","solution":"The HCF is 12. LCM = (24 × 36) ÷ 12 = 72.","id":"x012-06","subject":"maths","topic":"Lowest common multiple","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 6/12 + 1/8. Give a fraction or decimal.","answer":0.625,"hint":"Use a common denominator of 24.","solution":"6/12 = 12/24 and 1/8 = 3/24. The sum is 15/24.","id":"x013-06","subject":"maths","topic":"Adding fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 6/11 × 3/5. Give a fraction or decimal.","answer":0.3272727273,"hint":"Multiply numerators and denominators.","solution":"(6 × 3)/(11 × 5) = 18/55. Simplify if possible.","id":"x014-06","subject":"maths","topic":"Multiplying fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 6/12 ÷ 5/6. Give a fraction or decimal.","answer":0.6,"hint":"Multiply by the reciprocal of 5/6.","solution":"6/12 × 6/5 = 36/60 = 6/10.","id":"x015-06","subject":"maths","topic":"Dividing fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 6 3/4 as a decimal.","answer":6.75,"hint":"The fraction part is three quarters, or 0.75.","solution":"6 + 0.75 = 6.75.","id":"x016-06","subject":"maths","topic":"Mixed numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A club has 144 members. Three eighths cycle to the club. How many members cycle?","answer":54,"hint":"Divide by 8 to find one eighth, then multiply by 3.","solution":"144 ÷ 8 × 3 = 54.","id":"x017-06","subject":"maths","topic":"Fractions of quantities","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 0.161616… (the block 16 repeats) as a fraction or decimal.","answer":0.1616161616,"hint":"For a two-digit repeating block, compare 100x with x.","solution":"If x = 0.1616…, then 100x − x = 16; hence x = 16/99.","id":"x018-06","subject":"maths","topic":"Recurring decimals","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Simplify 3^7 × 3^9 to 3^k. Find k.","answer":16,"hint":"Add exponents when multiplying powers of the same base.","solution":"k = 7 + 9 = 16.","id":"x019-06","subject":"maths","topic":"Index laws","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Evaluate 7^−2. Give a fraction or decimal.","answer":0.0204081633,"hint":"A negative exponent gives the reciprocal of the positive power.","solution":"7^−2 = 1/(7²) = 1/49.","id":"x020-06","subject":"maths","topic":"Negative indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Evaluate 512^(2/3).","answer":64,"hint":"Take the cube root, then square the result.","solution":"The cube root of 512 is 8; its square is 64.","id":"x021-06","subject":"maths","topic":"Fractional indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write √98 in the form a√2. Find a.","answer":7,"hint":"Look for a square factor inside the root.","solution":"√(49 × 2) = 7√2, so a = 7.","id":"x022-06","subject":"maths","topic":"Simplifying surds","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write 18/√3 in the form a√3. Find a.","answer":6,"hint":"Multiply numerator and denominator by √3.","solution":"(18√3)/3 = 6√3.","id":"x023-06","subject":"maths","topic":"Rationalising denominators","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate (2 × 10^6) × (3 × 10²). Write the result as 6 × 10^k. Find k.","answer":8,"hint":"Multiply the coefficients and add powers of ten.","solution":"2 × 3 = 6 and 6 + 2 = 8, so k = 8.","id":"x024-06","subject":"maths","topic":"Calculating in standard form","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A length is 16 cm to the nearest centimetre. Give the lower bound in cm.","answer":15.5,"hint":"The rounding interval extends half a centimetre either side.","solution":"The lower bound is 16 − 0.5 = 15.5 cm; the upper bound is 16.5 cm and is excluded.","id":"x025-06","subject":"maths","topic":"Error intervals","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle has length 16 cm and width 10 cm, both to the nearest centimetre. Find the upper bound for its area in cm².","answer":173.25,"hint":"Use the upper bound for each positive length.","solution":"Upper area bound = 16.5 × 10.5 = 173.25 cm².","id":"x026-06","subject":"maths","topic":"Upper and lower bounds","group":"Number","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify 8x + 10x − 3x to ax. Find a.","answer":15,"hint":"Combine only the coefficients of x.","solution":"a = 8 + 10 − 3 = 15.","id":"x027-06","subject":"maths","topic":"Collecting like terms","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand 8(x + 7). What is the constant term?","answer":56,"hint":"Multiply both terms inside the bracket.","solution":"The expansion is 8x + 56.","id":"x028-06","subject":"maths","topic":"Expanding a single bracket","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand (x + 6)(x + 9). What is the coefficient of x?","answer":15,"hint":"Multiply every term in one bracket by every term in the other.","solution":"x² + 9x + 6x + 54 = x² + 15x + 54.","id":"x029-06","subject":"maths","topic":"Expanding double brackets","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise fully 12x + 36.","kind":"choice","options":["6(x + 3)","36(x + 2)","12(x + 3)","12(x + 6)"],"correct":2,"answer":null,"hint":"Take out the highest common factor of the two coefficients.","solution":"Both terms contain 12. Dividing gives x and 3, so the result is 12(x + 3).","id":"x030-06","subject":"maths","topic":"Factorising with a common factor","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise x² + 15x + 54.","kind":"choice","options":["(x + 7)(x + 8)","(x − 6)(x + 9)","(x + 6)(x + 9)","(x − 6)(x − 9)"],"correct":2,"answer":null,"hint":"Find two numbers whose product is the constant and whose sum is the x coefficient.","solution":"6 × 9 = 54 and 6 + 9 = 15.","id":"x031-06","subject":"maths","topic":"Factorising quadratics","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Find 2a² − b when a = 6 and b = 9.","answer":63,"hint":"Square a before multiplying by 2.","solution":"2 × 6² − 9 = 63.","id":"x032-06","subject":"maths","topic":"Substitution","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The formula is y = 8x − 6. If y = 50, find x.","answer":7,"hint":"Add the constant to y, then divide by the coefficient of x.","solution":"x = (y + 6)/8 = 56/8 = 7.","id":"x033-06","subject":"maths","topic":"Changing the subject","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the smallest integer satisfying 3x + 6 > 24.","answer":7,"hint":"Subtract the constant, divide by 3, then respect the strict inequality.","solution":"3x > 18, so x > 6. The smallest integer is 7.","id":"x034-06","subject":"maths","topic":"Linear inequalities","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Solve x + y = 19 and x − y = 7. Give x.","answer":13,"hint":"Add the two equations to eliminate y.","solution":"2x = 26, so x = 13.","id":"x035-06","subject":"maths","topic":"Simultaneous linear equations","group":"Algebra","tier":"Both","calculator":false,"marks":3},{"prompt":"The graphs y = x² and y = 36 meet. Give the positive x-coordinate.","answer":6,"hint":"Substitute to obtain x² equal to the constant.","solution":"x² = 36, so x = ±6. The positive value is 6.","id":"x036-06","subject":"maths","topic":"Simultaneous nonlinear equations","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"Write x² + 12x + 44 as (x + a)² + b. Find b.","answer":8,"hint":"Half the x coefficient gives a. Subtract a² from the constant.","solution":"a = 6. Subtract 36 from the constant 44 to get b = 8.","id":"x037-06","subject":"maths","topic":"Completing the square","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Use the quadratic formula to find the positive root of x² + x − 42 = 0.","answer":6,"hint":"Identify a, b and c. Use x = (−b ± √(b² − 4ac))/(2a).","solution":"a=1, b=1, c=−42. The discriminant is 1 + 168 = 169. The positive root is (−1 + 13)/2 = 6.","id":"x038-06","subject":"maths","topic":"Quadratic formula","group":"Algebra","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify (8x)/(16x²) for x ≠ 0, then evaluate at x = 6.","answer":0.0833333333,"hint":"Cancel the common numerical factor and one factor of x.","solution":"The expression simplifies to 1/(2x). At x = 6, it is 1/12.","id":"x039-06","subject":"maths","topic":"Algebraic fractions","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"The difference (k + 1)² − k² simplifies to 2k + 1. Use this identity to find the difference between the squares of 10 and 11.","answer":21,"hint":"Expand the square before cancelling k².","solution":"Expanding proves (k + 1)² − k² = 2k + 1. Set k = 10: the difference is 21.","id":"x040-06","subject":"maths","topic":"Algebraic proof","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x − 6. Find f(8).","answer":18,"hint":"Replace every x with the specified input.","solution":"f(8) = 3(8) − 6 = 18.","id":"x041-06","subject":"maths","topic":"Function notation","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"f(x) = 2x + 1 and g(x) = x². Find f(g(6)).","answer":73,"hint":"Apply the inside function first.","solution":"g(6) = 36; f(36) = 73.","id":"x042-06","subject":"maths","topic":"Composite functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x + 6. Find f⁻¹(24).","answer":6,"hint":"Undo the addition, then undo the multiplication.","solution":"f⁻¹(y) = (y − 6)/3. With y = 24, this gives 6.","id":"x043-06","subject":"maths","topic":"Inverse functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"x₀ = 6. Use x_(k+1) = (x_k + 4)/2 to calculate x₂.","answer":4.5,"hint":"Calculate x₁ first and substitute that new value again.","solution":"x₁ = (6 + 4)/2 = 5.0. Then x₂ = (5.0 + 4)/2 = 4.5.","id":"x044-06","subject":"maths","topic":"Iteration","group":"Algebra","tier":"Higher","calculator":true,"marks":2},{"prompt":"A geometric sequence starts at 7 and has common ratio 3. Find its fourth term.","answer":189,"hint":"Multiply by 3 three times after the first term.","solution":"The fourth term is 7 × 3³ = 189.","id":"x045-06","subject":"maths","topic":"Geometric sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The nth term is n² + 6n + 2. Find the fifth term.","answer":57,"hint":"Replace each occurrence of n (the position variable) with 5.","solution":"5² + 6 × 5 + 2 = 57.","id":"x046-06","subject":"maths","topic":"Quadratic sequences","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sequence begins 6, 7. Each new term is the sum of the preceding two. Find the fifth term.","answer":33,"hint":"Build the third and fourth terms before the fifth.","solution":"The terms are 6, 7, 13, 20, 33.","id":"x047-06","subject":"maths","topic":"Fibonacci-type sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the x-coordinate of the midpoint of (6, 2) and (20, 8).","answer":13,"hint":"Average the two x-coordinates.","solution":"(6 + 20)/2 = 13. The full midpoint is (13, 5).","id":"x048-06","subject":"maths","topic":"Midpoints","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the distance between (0, 0) and (18, 24).","answer":30,"hint":"Use the horizontal and vertical differences in Pythagoras.","solution":"√(18² + 24²) = 30 units.","id":"x049-06","subject":"maths","topic":"Distance between coordinates","group":"Coordinate geometry","tier":"Both","calculator":true,"marks":3},{"prompt":"A line is parallel to y = 7x − 4 and passes through (0, 6). Give its gradient.","answer":7,"hint":"Parallel non-vertical lines have equal gradients.","solution":"The given line has gradient 7, so the parallel line does too.","id":"x050-06","subject":"maths","topic":"Parallel lines","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the gradient of a line perpendicular to y = 7x + 2. Give a fraction or decimal.","answer":-0.1428571429,"hint":"For non-zero gradients, the perpendicular gradient is the negative reciprocal.","solution":"The negative reciprocal of 7 is −1/7.","id":"x051-06","subject":"maths","topic":"Perpendicular lines","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A line passes through (1, 13) and (3, 25). Write it as y = mx + c. Find c.","answer":7,"hint":"Find the gradient from the two points, then substitute a point.","solution":"m = (25 − 13)/2 = 6. Then c = 13 − 6 = 7.","id":"x052-06","subject":"maths","topic":"Equation of a line through points","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"A pack of 9 notebooks costs £63. Find the price per notebook in pounds.","answer":7,"hint":"Divide cost by number of items.","solution":"£63 ÷ 9 = £7 per notebook.","id":"x053-06","subject":"maths","topic":"Best buys and unit pricing","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"£1 exchanges for €1.20. How many euros are exchanged for £150?","answer":180,"hint":"Multiply the pound amount by the euros-per-pound rate.","solution":"150 × 1.20 = €180.","id":"x054-06","subject":"maths","topic":"Currency conversion","group":"Proportion and rates","tier":"Both","calculator":true,"marks":2},{"prompt":"A recipe for 4 people uses 200 g of rice. How many grams are needed for 6 people?","answer":300.0,"hint":"Scale every ingredient by 6/4.","solution":"200 × 6/4 = 300.0 g.","id":"x055-06","subject":"maths","topic":"Scaling recipes","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"A map has scale 1:50 000. Two places are 6 cm apart on the map. Find their real distance in kilometres.","answer":3.0,"hint":"Convert the scaled centimetres into kilometres using 100 000 cm = 1 km.","solution":"6 × 50 000 = 300000 cm = 3.0 km.","id":"x056-06","subject":"maths","topic":"Map scales","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is directly proportional to x. When x = 3, y = 21. Find y when x = 8.","answer":56,"hint":"Find k in y = kx.","solution":"k = 21/3 = 7; hence y = 7 × 8 = 56.","id":"x057-06","subject":"maths","topic":"Direct proportion","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is inversely proportional to x. When x = 2, y = 36. Find y when x = 3.","answer":24,"hint":"The product xy stays constant.","solution":"k = 2 × 36 = 72. Thus y = 72/3 = 24.","id":"x058-06","subject":"maths","topic":"Inverse proportion","group":"Proportion and rates","tier":"Higher","calculator":false,"marks":2},{"prompt":"£600 earns 5% compound interest each year. Find the balance after 2 years in pounds.","answer":661.5,"hint":"Multiply by 1.05 for each year.","solution":"£600 × 1.05² = £661.50.","id":"x059-06","subject":"maths","topic":"Compound interest","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A bicycle worth £1500 loses 20% of its value each year. Find its value after 2 years in pounds.","answer":960,"hint":"Retain 80% each year, using the multiplier 0.8 twice.","solution":"£1500 × 0.8² = £960.","id":"x060-06","subject":"maths","topic":"Depreciation","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A culture begins with 1200 cells and increases by 10% each hour. Find the modelled count after 2 hours.","answer":1452,"hint":"Use the growth multiplier 1.1 twice.","solution":"1200 × 1.1² = 1452 cells.","id":"x061-06","subject":"maths","topic":"Repeated percentage growth","group":"Finance","tier":"Both","calculator":true,"marks":2},{"prompt":"A block has mass 504 g and volume 72 cm³. Find its density in g/cm³.","answer":7,"hint":"Density = mass ÷ volume.","solution":"504 ÷ 72 = 7 g/cm³.","id":"x062-06","subject":"maths","topic":"Density","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A force of 720 N acts on an area of 18 m². Find pressure in N/m².","answer":40,"hint":"Pressure = force ÷ area.","solution":"720 ÷ 18 = 40 N/m².","id":"x063-06","subject":"maths","topic":"Pressure","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"Convert 7 m² into cm².","answer":70000,"hint":"Square the linear conversion: 1 m = 100 cm.","solution":"1 m² = 100² = 10 000 cm². Therefore 7 m² = 70000 cm².","id":"x064-06","subject":"maths","topic":"Metric area conversions","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A journey starts at 09:16 and ends at 11:45. Find its duration in minutes.","answer":149,"hint":"Count the full hours and the remaining minutes.","solution":"From 09:16 to 11:16 is 120 minutes, then another 29. Total = 149 minutes.","id":"x065-06","subject":"maths","topic":"Time calculations","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle is 14 cm by 10 cm. A 2 cm by 2 cm square is cut from one corner. Find the perimeter of the remaining L-shape in cm.","answer":48,"hint":"The two removed edge lengths are replaced by two equal inner edge lengths.","solution":"The perimeter stays equal to the original rectangle: 2(14 + 10) = 48 cm.","id":"x066-06","subject":"maths","topic":"Perimeter of compound shapes","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 7 cm. Express its circumference as kπ cm. Find k.","answer":14,"hint":"Circumference is 2πr.","solution":"2π × 7 = 14π cm.","id":"x067-06","subject":"maths","topic":"Circle circumference","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 8 cm. Its area is kπ cm². Find k.","answer":64,"hint":"Square the radius and multiply by π.","solution":"Area = π × 8² = 64π cm².","id":"x068-06","subject":"maths","topic":"Area of circles","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A semicircle has radius 8 cm. Its perimeter is πr + d. Find the straight-edge length d in cm.","answer":16,"hint":"The straight edge is the diameter, not the radius.","solution":"d = 2r = 2 × 8 = 16 cm. The complete perimeter is 8π + 16 cm.","id":"x069-06","subject":"maths","topic":"Semicircle perimeter","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 60° and radius 18 cm. Its arc length is kπ cm. Find k.","answer":6,"hint":"Take 60/360 of the circumference.","solution":"(60/360) × 2π × 18 = 6π cm.","id":"x070-06","subject":"maths","topic":"Arc length","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 90° and radius 12 cm. Its area is kπ cm². Find k.","answer":36,"hint":"Take one quarter of the full circle area.","solution":"(90/360) × π × 12² = 36π cm².","id":"x071-06","subject":"maths","topic":"Sector area","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A triangular prism has triangular cross-section base 8 cm, height 6 cm, and prism length 10 cm. Find its volume in cm³.","answer":240,"hint":"Find the triangle area, then multiply by the prism length.","solution":"Cross-section = ½ × 8 × 6 = 24 cm². Volume = 240 cm³.","id":"x072-06","subject":"maths","topic":"Volume of prisms","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A cylinder has radius 7 cm and height 5 cm. Its volume is kπ cm³. Find k.","answer":245,"hint":"Multiply the circular base area by the height.","solution":"πr²h = π × 7² × 5 = 245π cm³.","id":"x073-06","subject":"maths","topic":"Volume of cylinders","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A cone has radius 7 cm and perpendicular height 9 cm. Its volume is kπ cm³. Find k.","answer":147,"hint":"A cone has one third of the corresponding cylinder volume.","solution":"V = πr²h/3 = π × 7² × 9/3 = 147π cm³.","id":"x074-06","subject":"maths","topic":"Volume of cones","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sphere has radius 18 cm. Its volume is kπ cm³. Find k.","answer":7776,"hint":"Use V = 4πr³/3.","solution":"(4/3) × 18³ = 7776, so V = 7776π cm³.","id":"x075-06","subject":"maths","topic":"Volume of spheres","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A cuboid measures 7 cm by 3 cm by 4 cm. Find its total surface area in cm².","answer":122,"hint":"There are two faces of each of the three different rectangular areas.","solution":"2[3(7) + 4(7) + 3×4] = 122 cm².","id":"x076-06","subject":"maths","topic":"Surface area of cuboids","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A closed cylinder has radius 7 cm and height 4 cm. Its total surface area is kπ cm². Find k.","answer":154,"hint":"Include two circular ends and the curved surface.","solution":"2r² + 2rh = 2(7²) + 2(7)(4) = 154.","id":"x077-06","subject":"maths","topic":"Cylinder surface area","group":"Geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"Two similar shapes have length scale factor 3 from small to large. A small side is 8 cm. Find the matching large side.","answer":24,"hint":"Multiply corresponding lengths by the length scale factor.","solution":"8 × 3 = 24 cm.","id":"x078-06","subject":"maths","topic":"Similarity of lengths","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Two similar shapes have length scale factor 2. The smaller area is 9 cm². Find the larger area.","answer":36,"hint":"Square the length scale factor for areas.","solution":"Area factor = 2² = 4. Larger area = 9 × 4 = 36 cm².","id":"x079-06","subject":"maths","topic":"Similarity of areas","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"Two similar solids have length scale factor 3. The smaller volume is 7 cm³. Find the larger volume.","answer":189,"hint":"Cube the length scale factor for volumes.","solution":"Volume factor = 3³ = 27. Larger volume = 189 cm³.","id":"x080-06","subject":"maths","topic":"Similarity of volumes","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A triangle has two angles 46° and 66°. Find the third angle in degrees.","answer":68,"hint":"Interior angles in a triangle total 180°.","solution":"180 − 46 − 66 = 68°.","id":"x081-06","subject":"maths","topic":"Triangle angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A regular polygon has 10 sides. Find its exterior angle in degrees, to 3 decimal places if needed.","answer":36.0,"hint":"The exterior angles total 360°.","solution":"Each exterior angle is 360/10 = 36.000°.","id":"x082-06","subject":"maths","topic":"Exterior angles of polygons","group":"Geometry","tier":"Both","calculator":true,"marks":2},{"prompt":"A transversal crosses two parallel lines. One of a pair of co-interior angles is 78°. Find the other angle in degrees.","answer":102,"hint":"Co-interior angles on parallel lines sum to 180°.","solution":"180 − 78 = 102°.","id":"x083-06","subject":"maths","topic":"Angles in parallel lines","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the sum of the interior angles of a polygon with 9 sides.","answer":1260,"hint":"Use (number of sides − 2) × 180°.","solution":"(9 − 2) × 180 = 1260°.","id":"x084-06","subject":"maths","topic":"Polygon interior-angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"The bearing of B from A is 050°. Find the bearing of A from B as a number of degrees.","answer":230,"hint":"A reverse bearing differs by 180°.","solution":"50 + 180 = 230°.","id":"x085-06","subject":"maths","topic":"Three-figure bearings","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A right-angled triangle has hypotenuse 16 cm and an angle of 30°. Find the side opposite that angle in cm.","answer":8,"hint":"Use sin(angle) = opposite/hypotenuse.","solution":"Opposite = 16 × sin30° = 8 cm.","id":"x086-06","subject":"maths","topic":"Right-angle trigonometry","group":"Trigonometry","tier":"Both","calculator":true,"marks":3},{"prompt":"In a triangle, side a = 8 cm is opposite 30°, and side b is opposite 90°. Find b in cm.","answer":16,"hint":"Use a/sin A = b/sin B.","solution":"b = 8 × sin90°/sin30° = 16 cm.","id":"x087-06","subject":"maths","topic":"Sine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides of a triangle are 8 cm each, with included angle 60°. Find the opposite side in cm.","answer":8,"hint":"Use c² = a² + b² − 2ab cos C.","solution":"c² = 2(8²) − 2(8²)cos60° = 64, so c = 8 cm.","id":"x088-06","subject":"maths","topic":"Cosine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides are 8 cm and 8 cm, with included angle 30°. Find the triangle area in cm².","answer":16,"hint":"Use area = ½ab sin C.","solution":"½ × 8 × 8 × sin30° = 16 cm².","id":"x089-06","subject":"maths","topic":"Triangle area using sine","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"An angle at the circumference is 26°. The central angle subtended by the same arc is less than 180°. Find it.","answer":52,"hint":"The angle at the centre is twice the angle at the circumference on the same arc.","solution":"2 × 26 = 52°.","id":"x090-06","subject":"maths","topic":"Angles at the centre","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"One angle of a cyclic quadrilateral is 102°. Find its opposite angle.","answer":78,"hint":"Opposite angles in a cyclic quadrilateral total 180°.","solution":"180 − 102 = 78°.","id":"x091-06","subject":"maths","topic":"Cyclic quadrilaterals","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"A tangent and chord form an angle of 37°. Find the angle subtended by that chord in the alternate segment.","answer":37,"hint":"The tangent-chord angle equals the angle in the alternate segment.","solution":"By the alternate segment theorem, the required angle is 37°.","id":"x092-06","subject":"maths","topic":"Alternate segment theorem","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"Vectors a = (6, 3) and b = (8, −1). Find the x-component of a + b.","answer":14,"hint":"Add corresponding components.","solution":"a + b = (14, 2), so the x-component is 14.","id":"x093-06","subject":"maths","topic":"Adding vectors","group":"Vectors","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the magnitude of the vector (18, 24).","answer":30,"hint":"Use Pythagoras on the two components.","solution":"√(18² + 24²) = 30.","id":"x094-06","subject":"maths","topic":"Vector magnitude","group":"Vectors","tier":"Higher","calculator":true,"marks":2},{"prompt":"Rotate (6, 8) by 90° anticlockwise about the origin. Find the new x-coordinate.","answer":-8,"hint":"The rule for 90° anticlockwise is (x,y) → (−y,x).","solution":"The image is (−8, 6), so its x-coordinate is −8.","id":"x095-06","subject":"maths","topic":"Rotations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Enlarge (6, 2) by scale factor 3 about the origin. Find the new x-coordinate.","answer":18,"hint":"Multiply both coordinates by the scale factor.","solution":"The image is (18, 6).","id":"x096-06","subject":"maths","topic":"Enlargements","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Translate (6, 4) by the vector (−3, 2). Find the new x-coordinate.","answer":3,"hint":"Add the x-component of the vector to the x-coordinate.","solution":"The image is (3, 6).","id":"x097-06","subject":"maths","topic":"Translations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Reflect (6, 9) in the line y = x. Find the new x-coordinate.","answer":9,"hint":"Reflection in y = x swaps the coordinates.","solution":"The image is (9, 6).","id":"x098-06","subject":"maths","topic":"Reflections","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Points must be exactly 8 cm from a fixed point P. What is their locus?","kind":"choice","options":["A straight line through P","A perpendicular bisector through P","A circle centred at P with radius 8 cm","A circle centred at P with diameter 8 cm"],"correct":2,"answer":null,"hint":"A fixed distance from one point defines a circle.","solution":"All points on a circle of radius 8 cm are exactly 8 cm from its centre P.","id":"x099-06","subject":"maths","topic":"Loci and constructions","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the median of 13, 6, 9, 15, 7.","answer":9,"hint":"Order the values, then choose the middle one.","solution":"The ordered list is 6, 7, 9, 13, 15. Its middle value is 9.","id":"x100-06","subject":"maths","topic":"Finding the median","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the mode of 6, 8, 8, 10, 8, 12.","answer":8,"hint":"Look for the value occurring most frequently.","solution":"8 occurs three times; every other value occurs once.","id":"x101-06","subject":"maths","topic":"Finding the mode","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the range of −6, 2, 10, 0.","answer":16,"hint":"Subtract the minimum from the maximum.","solution":"10 − (−6) = 16.","id":"x102-06","subject":"maths","topic":"Finding the range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A data set has lower quartile 9 and upper quartile 31. Find its interquartile range.","answer":22,"hint":"IQR = upper quartile − lower quartile.","solution":"31 − 9 = 22.","id":"x103-06","subject":"maths","topic":"Interquartile range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A grouped table has 2 values in 0 ≤ x < 10 and 8 values in 10 ≤ x < 20. Estimate the mean, to 3 decimal places.","answer":13.0,"hint":"Use class midpoints 5 and 15, multiply by frequencies, then divide by total frequency.","solution":"Estimated total = 2×5 + 8×15 = 130. Divide by 10 to get 13.000.","id":"x104-06","subject":"maths","topic":"Estimated mean from grouped data","group":"Statistics","tier":"Both","calculator":true,"marks":3},{"prompt":"A histogram class has width 5 and frequency 40. Find its frequency density.","answer":8,"hint":"Frequency density = frequency ÷ class width.","solution":"40 ÷ 5 = 8.","id":"x105-06","subject":"maths","topic":"Frequency density","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"Class frequencies, in ascending order, are 6, 8, 10, 12. Find the cumulative frequency at the end of the third class.","answer":24,"hint":"Add all frequencies up to and including the third class.","solution":"6 + 8 + 10 = 24.","id":"x106-06","subject":"maths","topic":"Cumulative frequency","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A box plot has minimum 6, lower quartile 9, median 12, upper quartile 15, maximum 21. Read off its median.","answer":12,"hint":"The median is the line inside the box.","solution":"The median line is at 12. The ends of the box are the quartiles.","id":"x107-06","subject":"maths","topic":"Box plots","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A school has 600 pupils; 180 are in a chosen group. In a proportional sample of 40 pupils, how many should come from that group?","answer":12,"hint":"Multiply the sample size by the group proportion.","solution":"40 × 180/600 = 12 pupils.","id":"x108-06","subject":"maths","topic":"Stratified sampling","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"An experiment succeeds 9 times out of 20 trials. Find the relative frequency as a fraction or decimal.","answer":0.45,"hint":"Divide the number of successes by the number of trials.","solution":"Relative frequency = 9/20 = 0.45.","id":"x109-06","subject":"maths","topic":"Relative frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"An event has probability 0.3. It is tested 120 times. Find its expected frequency.","answer":36,"hint":"Multiply probability by number of trials.","solution":"0.3 × 120 = 36. This is an expectation, not a guarantee.","id":"x110-06","subject":"maths","topic":"Expected frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Two independent events have probabilities 1/2 and 6/12. Find the probability that both occur.","answer":0.25,"hint":"Multiply the probabilities of independent events.","solution":"1/2 × 6/12 = 6/24.","id":"x111-06","subject":"maths","topic":"Independent events","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A bag has 8 red counters and 3 blue counters. Two counters are drawn without replacement. Find P(both red), to 3 decimal places.","answer":0.509,"hint":"The second draw has one fewer red counter and one fewer counter altogether.","solution":"P = (8/11) × (7/10) = 0.509.","id":"x112-06","subject":"maths","topic":"Sampling without replacement","group":"Probability","tier":"Higher","calculator":true,"marks":3},{"prompt":"Of 11 club members who play tennis, 6 also swim. A member is chosen from the tennis players only. Find P(swims), as a fraction or decimal.","answer":0.5454545455,"hint":"Use the restricted tennis group as the denominator.","solution":"Given that the person plays tennis, P(swims) = 6/11.","id":"x113-06","subject":"maths","topic":"Conditional probability","group":"Probability","tier":"Higher","calculator":false,"marks":2},{"prompt":"Set A contains 26 people including 8 in A ∩ B. How many are in A only?","answer":18,"hint":"Subtract the intersection from the total in A.","solution":"26 − 8 = 18 people.","id":"x114-06","subject":"maths","topic":"Venn diagram regions","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"n(A) = 16, n(B) = 18, and n(A ∩ B) = 9. Find n(A ∪ B).","answer":25,"hint":"Add the two set sizes and subtract the overlap once.","solution":"16 + 18 − 9 = 25.","id":"x115-06","subject":"maths","topic":"Set union","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A fair coin is tossed, then a fair 9-sided die numbered 1 to 9 is rolled. Find P(heads and a 1).","answer":0.0555555556,"hint":"Multiply the branch probabilities along the path.","solution":"(1/2) × (1/9) = 1/18.","id":"x116-06","subject":"maths","topic":"Tree diagrams","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Plot the listed points for y = x³ + 1. Use x = -2, -1, 0, 1, 2. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[-2,-7],[-1,0],[0,1],[1,2],[2,9]],"curve":"quadratic","range":[-3,3,-14,14],"expression":"y = x³ + 1","hint":"Cube each x, preserving its sign, then add the constant.","solution":"The coordinates are (-2, -7), (-1, 0), (0, 1), (1, 2), (2, 9). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x117-06","subject":"maths","topic":"Cubic graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 12/x + 5 for 1 ≤ x ≤ 6. Use x = 1, 2, 3, 4, 6. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[1,17.0],[2,11.0],[3,9.0],[4,8.0],[6,7.0]],"curve":"quadratic","range":[0,7,0,23],"expression":"y = 12/x + 5 for 1 ≤ x ≤ 6","hint":"Divide 12 by x, then add the constant; x = 0 is not allowed.","solution":"The coordinates are (1, 17.0), (2, 11.0), (3, 9.0), (4, 8.0), (6, 7.0). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x118-06","subject":"maths","topic":"Reciprocal graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 2^x + 5. Use x = 0, 1, 2, 3. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[0,6],[1,7],[2,9],[3,13]],"curve":"quadratic","range":[-1,4,0,18],"expression":"y = 2^x + 5","hint":"Calculate the power of 2 first, then add the constant.","solution":"The coordinates are (0, 6), (1, 7), (2, 9), (3, 13). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x119-06","subject":"maths","topic":"Exponential graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"The graph y = x² is translated upward by 8 units. Find the new y-coordinate of its turning point.","answer":8,"hint":"An upward translation adds the same amount to every y-coordinate.","solution":"The old turning point is (0, 0); the new one is (0, 8).","id":"x120-06","subject":"maths","topic":"Translating graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A straight segment on a distance-time graph runs from (0 hours, 0 km) to (2 hours, 72 km). Find the speed in km/h.","answer":36,"hint":"Speed is the gradient: distance change divided by time change.","solution":"72 km ÷ 2 h = 36 km/h.","id":"x121-06","subject":"maths","topic":"Distance-time graphs","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A velocity-time graph rises in a straight line from 0 m/s to 30 m/s in 5 seconds. Find acceleration in m/s².","answer":6,"hint":"Acceleration is change in velocity divided by time.","solution":"(30 − 0)/5 = 6 m/s².","id":"x122-06","subject":"maths","topic":"Velocity-time gradients","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A tangent to a curve passes through (1, 6) and (3, 20). Estimate the gradient of the curve at the contact point.","answer":7,"hint":"Use the gradient of the tangent, not a chord through two curve points.","solution":"(20 − 6)/(3 − 1) = 7.","id":"x123-06","subject":"maths","topic":"Tangents and rates of change","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A velocity-time graph forms a triangle with base 6 seconds and maximum velocity 12 m/s. Find the displacement in metres.","answer":36,"hint":"Displacement is the signed area under a velocity-time graph.","solution":"Area = ½ × 6 × 12 = 36 m.","id":"x124-06","subject":"maths","topic":"Area under velocity-time graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"The lines y = x + 6 and y = 3x intersect. Find the x-coordinate of the intersection.","answer":3.0,"hint":"At the intersection, both expressions for y are equal.","solution":"x + 6 = 3x, so 2x = 6 and x = 3.0.","id":"x125-06","subject":"maths","topic":"Graphical simultaneous equations","group":"Graphs","tier":"Both","calculator":false,"marks":3},{"prompt":"Which point satisfies both x > 6 and y < 3?","kind":"choice","options":["(7, 4)","(5, 0)","(7, 2)","(6, 2)"],"correct":2,"answer":null,"hint":"Test both strict inequalities for each coordinate pair.","solution":"Only (7, 2) has x strictly greater than 6 and y strictly less than 3.","id":"x126-06","subject":"maths","topic":"Regions satisfying inequalities","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate 10 + 9 × 4.","answer":46,"hint":"Do multiplication before addition.","solution":"9 × 4 = 36; then add 10 to get 46.","id":"x001-07","subject":"maths","topic":"Order of operations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"The temperature is −9°C. It falls by 11°C. What is the new temperature in °C?","answer":-20,"hint":"A fall makes the number more negative.","solution":"−9 − 11 = −20°C.","id":"x002-07","subject":"maths","topic":"Calculating with negatives","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the value of the hundreds digit in 1807?","answer":800,"hint":"Identify the digit three places from the right.","solution":"The hundreds digit is 8, so its value is 8 × 100 = 800.","id":"x003-07","subject":"maths","topic":"Place value","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 9.376 to two decimal places.","answer":9.38,"hint":"Look at the third decimal digit.","solution":"The third digit is 6, so round the hundredths up: 9.38.","id":"x004-07","subject":"maths","topic":"Rounding decimal places","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 3453 to two significant figures.","answer":3500,"hint":"Count significant digits from the first non-zero digit.","solution":"The first two significant figures are in the thousands and hundreds columns. Rounding 3453 to the nearest 100 gives 3500.","id":"x005-07","subject":"maths","topic":"Significant figures","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Estimate 9.9 × 19.8 by rounding each number to the nearest whole number first.","answer":200,"hint":"Follow the requested rounding method for both numbers.","solution":"9.9 rounds to 10; 19.8 rounds to 20. The estimate is 200.","id":"x006-07","subject":"maths","topic":"Estimating calculations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"How many positive factors does 256 have?","answer":9,"hint":"For a power of 2, list 2⁰ up to the highest power.","solution":"256 = 2^8. Its factors are 2⁰ through 2^8, giving 9 factors.","id":"x007-07","subject":"maths","topic":"Factors","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the smallest multiple of 10 that is strictly greater than 100?","answer":110,"hint":"The number given is already the tenth multiple.","solution":"The next multiple is 11 × 10 = 110.","id":"x008-07","subject":"maths","topic":"Multiples","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Which number in this list is prime? Set 7.","kind":"choice","options":["81","31","40","54"],"correct":1,"answer":null,"hint":"A prime has exactly two positive factors: 1 and itself.","solution":"31 has no positive factors except 1 and itself. The other numbers have explicit factors 4, 6 or 9.","id":"x009-07","subject":"maths","topic":"Prime numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"In the prime factorisation of 1152, what is the exponent of 2?","answer":7,"hint":"Keep dividing by 2 until the remaining number is odd.","solution":"1152 = 2^7 × 3², so the exponent is 7.","id":"x010-07","subject":"maths","topic":"Prime factorisation","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the highest common factor of 84 and 126.","answer":42,"hint":"Look for the largest factor that divides both numbers.","solution":"84 = 2 × 42 and 126 = 3 × 42. Since 2 and 3 are coprime, the HCF is 42.","id":"x011-07","subject":"maths","topic":"Highest common factor","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the lowest common multiple of 28 and 42.","answer":84,"hint":"Find the HCF first, or list the multiples.","solution":"The HCF is 14. LCM = (28 × 42) ÷ 14 = 84.","id":"x012-07","subject":"maths","topic":"Lowest common multiple","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 7/12 + 1/8. Give a fraction or decimal.","answer":0.7083333333,"hint":"Use a common denominator of 24.","solution":"7/12 = 14/24 and 1/8 = 3/24. The sum is 17/24.","id":"x013-07","subject":"maths","topic":"Adding fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 7/11 × 3/5. Give a fraction or decimal.","answer":0.3818181818,"hint":"Multiply numerators and denominators.","solution":"(7 × 3)/(11 × 5) = 21/55. Simplify if possible.","id":"x014-07","subject":"maths","topic":"Multiplying fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 7/12 ÷ 5/6. Give a fraction or decimal.","answer":0.7,"hint":"Multiply by the reciprocal of 5/6.","solution":"7/12 × 6/5 = 42/60 = 7/10.","id":"x015-07","subject":"maths","topic":"Dividing fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 7 3/4 as a decimal.","answer":7.75,"hint":"The fraction part is three quarters, or 0.75.","solution":"7 + 0.75 = 7.75.","id":"x016-07","subject":"maths","topic":"Mixed numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A club has 168 members. Three eighths cycle to the club. How many members cycle?","answer":63,"hint":"Divide by 8 to find one eighth, then multiply by 3.","solution":"168 ÷ 8 × 3 = 63.","id":"x017-07","subject":"maths","topic":"Fractions of quantities","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 0.171717… (the block 17 repeats) as a fraction or decimal.","answer":0.1717171717,"hint":"For a two-digit repeating block, compare 100x with x.","solution":"If x = 0.1717…, then 100x − x = 17; hence x = 17/99.","id":"x018-07","subject":"maths","topic":"Recurring decimals","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Simplify 3^8 × 3^10 to 3^k. Find k.","answer":18,"hint":"Add exponents when multiplying powers of the same base.","solution":"k = 8 + 10 = 18.","id":"x019-07","subject":"maths","topic":"Index laws","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Evaluate 8^−2. Give a fraction or decimal.","answer":0.015625,"hint":"A negative exponent gives the reciprocal of the positive power.","solution":"8^−2 = 1/(8²) = 1/64.","id":"x020-07","subject":"maths","topic":"Negative indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Evaluate 729^(2/3).","answer":81,"hint":"Take the cube root, then square the result.","solution":"The cube root of 729 is 9; its square is 81.","id":"x021-07","subject":"maths","topic":"Fractional indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write √128 in the form a√2. Find a.","answer":8,"hint":"Look for a square factor inside the root.","solution":"√(64 × 2) = 8√2, so a = 8.","id":"x022-07","subject":"maths","topic":"Simplifying surds","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write 21/√3 in the form a√3. Find a.","answer":7,"hint":"Multiply numerator and denominator by √3.","solution":"(21√3)/3 = 7√3.","id":"x023-07","subject":"maths","topic":"Rationalising denominators","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate (2 × 10^7) × (3 × 10²). Write the result as 6 × 10^k. Find k.","answer":9,"hint":"Multiply the coefficients and add powers of ten.","solution":"2 × 3 = 6 and 7 + 2 = 9, so k = 9.","id":"x024-07","subject":"maths","topic":"Calculating in standard form","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A length is 17 cm to the nearest centimetre. Give the lower bound in cm.","answer":16.5,"hint":"The rounding interval extends half a centimetre either side.","solution":"The lower bound is 17 − 0.5 = 16.5 cm; the upper bound is 17.5 cm and is excluded.","id":"x025-07","subject":"maths","topic":"Error intervals","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle has length 17 cm and width 11 cm, both to the nearest centimetre. Find the upper bound for its area in cm².","answer":201.25,"hint":"Use the upper bound for each positive length.","solution":"Upper area bound = 17.5 × 11.5 = 201.25 cm².","id":"x026-07","subject":"maths","topic":"Upper and lower bounds","group":"Number","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify 9x + 11x − 3x to ax. Find a.","answer":17,"hint":"Combine only the coefficients of x.","solution":"a = 9 + 11 − 3 = 17.","id":"x027-07","subject":"maths","topic":"Collecting like terms","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand 9(x + 8). What is the constant term?","answer":72,"hint":"Multiply both terms inside the bracket.","solution":"The expansion is 9x + 72.","id":"x028-07","subject":"maths","topic":"Expanding a single bracket","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand (x + 7)(x + 10). What is the coefficient of x?","answer":17,"hint":"Multiply every term in one bracket by every term in the other.","solution":"x² + 10x + 7x + 70 = x² + 17x + 70.","id":"x029-07","subject":"maths","topic":"Expanding double brackets","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise fully 14x + 42.","kind":"choice","options":["42(x + 2)","14(x + 3)","14(x + 6)","7(x + 3)"],"correct":1,"answer":null,"hint":"Take out the highest common factor of the two coefficients.","solution":"Both terms contain 14. Dividing gives x and 3, so the result is 14(x + 3).","id":"x030-07","subject":"maths","topic":"Factorising with a common factor","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise x² + 17x + 70.","kind":"choice","options":["(x − 7)(x + 10)","(x + 7)(x + 10)","(x − 7)(x − 10)","(x + 8)(x + 9)"],"correct":1,"answer":null,"hint":"Find two numbers whose product is the constant and whose sum is the x coefficient.","solution":"7 × 10 = 70 and 7 + 10 = 17.","id":"x031-07","subject":"maths","topic":"Factorising quadratics","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Find 2a² − b when a = 7 and b = 10.","answer":88,"hint":"Square a before multiplying by 2.","solution":"2 × 7² − 10 = 88.","id":"x032-07","subject":"maths","topic":"Substitution","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The formula is y = 9x − 7. If y = 65, find x.","answer":8,"hint":"Add the constant to y, then divide by the coefficient of x.","solution":"x = (y + 7)/9 = 72/9 = 8.","id":"x033-07","subject":"maths","topic":"Changing the subject","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the smallest integer satisfying 3x + 7 > 28.","answer":8,"hint":"Subtract the constant, divide by 3, then respect the strict inequality.","solution":"3x > 21, so x > 7. The smallest integer is 8.","id":"x034-07","subject":"maths","topic":"Linear inequalities","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Solve x + y = 22 and x − y = 8. Give x.","answer":15,"hint":"Add the two equations to eliminate y.","solution":"2x = 30, so x = 15.","id":"x035-07","subject":"maths","topic":"Simultaneous linear equations","group":"Algebra","tier":"Both","calculator":false,"marks":3},{"prompt":"The graphs y = x² and y = 49 meet. Give the positive x-coordinate.","answer":7,"hint":"Substitute to obtain x² equal to the constant.","solution":"x² = 49, so x = ±7. The positive value is 7.","id":"x036-07","subject":"maths","topic":"Simultaneous nonlinear equations","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"Write x² + 14x + 58 as (x + a)² + b. Find b.","answer":9,"hint":"Half the x coefficient gives a. Subtract a² from the constant.","solution":"a = 7. Subtract 49 from the constant 58 to get b = 9.","id":"x037-07","subject":"maths","topic":"Completing the square","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Use the quadratic formula to find the positive root of x² + x − 56 = 0.","answer":7,"hint":"Identify a, b and c. Use x = (−b ± √(b² − 4ac))/(2a).","solution":"a=1, b=1, c=−56. The discriminant is 1 + 224 = 225. The positive root is (−1 + 15)/2 = 7.","id":"x038-07","subject":"maths","topic":"Quadratic formula","group":"Algebra","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify (9x)/(18x²) for x ≠ 0, then evaluate at x = 7.","answer":0.0714285714,"hint":"Cancel the common numerical factor and one factor of x.","solution":"The expression simplifies to 1/(2x). At x = 7, it is 1/14.","id":"x039-07","subject":"maths","topic":"Algebraic fractions","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"The difference (k + 1)² − k² simplifies to 2k + 1. Use this identity to find the difference between the squares of 11 and 12.","answer":23,"hint":"Expand the square before cancelling k².","solution":"Expanding proves (k + 1)² − k² = 2k + 1. Set k = 11: the difference is 23.","id":"x040-07","subject":"maths","topic":"Algebraic proof","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x − 7. Find f(9).","answer":20,"hint":"Replace every x with the specified input.","solution":"f(9) = 3(9) − 7 = 20.","id":"x041-07","subject":"maths","topic":"Function notation","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"f(x) = 2x + 1 and g(x) = x². Find f(g(7)).","answer":99,"hint":"Apply the inside function first.","solution":"g(7) = 49; f(49) = 99.","id":"x042-07","subject":"maths","topic":"Composite functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x + 7. Find f⁻¹(28).","answer":7,"hint":"Undo the addition, then undo the multiplication.","solution":"f⁻¹(y) = (y − 7)/3. With y = 28, this gives 7.","id":"x043-07","subject":"maths","topic":"Inverse functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"x₀ = 7. Use x_(k+1) = (x_k + 4)/2 to calculate x₂.","answer":4.75,"hint":"Calculate x₁ first and substitute that new value again.","solution":"x₁ = (7 + 4)/2 = 5.5. Then x₂ = (5.5 + 4)/2 = 4.75.","id":"x044-07","subject":"maths","topic":"Iteration","group":"Algebra","tier":"Higher","calculator":true,"marks":2},{"prompt":"A geometric sequence starts at 8 and has common ratio 3. Find its fourth term.","answer":216,"hint":"Multiply by 3 three times after the first term.","solution":"The fourth term is 8 × 3³ = 216.","id":"x045-07","subject":"maths","topic":"Geometric sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The nth term is n² + 7n + 2. Find the fifth term.","answer":62,"hint":"Replace each occurrence of n (the position variable) with 5.","solution":"5² + 7 × 5 + 2 = 62.","id":"x046-07","subject":"maths","topic":"Quadratic sequences","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sequence begins 7, 8. Each new term is the sum of the preceding two. Find the fifth term.","answer":38,"hint":"Build the third and fourth terms before the fifth.","solution":"The terms are 7, 8, 15, 23, 38.","id":"x047-07","subject":"maths","topic":"Fibonacci-type sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the x-coordinate of the midpoint of (7, 2) and (23, 8).","answer":15,"hint":"Average the two x-coordinates.","solution":"(7 + 23)/2 = 15. The full midpoint is (15, 5).","id":"x048-07","subject":"maths","topic":"Midpoints","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the distance between (0, 0) and (21, 28).","answer":35,"hint":"Use the horizontal and vertical differences in Pythagoras.","solution":"√(21² + 28²) = 35 units.","id":"x049-07","subject":"maths","topic":"Distance between coordinates","group":"Coordinate geometry","tier":"Both","calculator":true,"marks":3},{"prompt":"A line is parallel to y = 8x − 4 and passes through (0, 7). Give its gradient.","answer":8,"hint":"Parallel non-vertical lines have equal gradients.","solution":"The given line has gradient 8, so the parallel line does too.","id":"x050-07","subject":"maths","topic":"Parallel lines","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the gradient of a line perpendicular to y = 8x + 2. Give a fraction or decimal.","answer":-0.125,"hint":"For non-zero gradients, the perpendicular gradient is the negative reciprocal.","solution":"The negative reciprocal of 8 is −1/8.","id":"x051-07","subject":"maths","topic":"Perpendicular lines","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A line passes through (1, 15) and (3, 29). Write it as y = mx + c. Find c.","answer":8,"hint":"Find the gradient from the two points, then substitute a point.","solution":"m = (29 − 15)/2 = 7. Then c = 15 − 7 = 8.","id":"x052-07","subject":"maths","topic":"Equation of a line through points","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"A pack of 10 notebooks costs £80. Find the price per notebook in pounds.","answer":8,"hint":"Divide cost by number of items.","solution":"£80 ÷ 10 = £8 per notebook.","id":"x053-07","subject":"maths","topic":"Best buys and unit pricing","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"£1 exchanges for €1.20. How many euros are exchanged for £175?","answer":210,"hint":"Multiply the pound amount by the euros-per-pound rate.","solution":"175 × 1.20 = €210.","id":"x054-07","subject":"maths","topic":"Currency conversion","group":"Proportion and rates","tier":"Both","calculator":true,"marks":2},{"prompt":"A recipe for 4 people uses 220 g of rice. How many grams are needed for 6 people?","answer":330.0,"hint":"Scale every ingredient by 6/4.","solution":"220 × 6/4 = 330.0 g.","id":"x055-07","subject":"maths","topic":"Scaling recipes","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"A map has scale 1:50 000. Two places are 7 cm apart on the map. Find their real distance in kilometres.","answer":3.5,"hint":"Convert the scaled centimetres into kilometres using 100 000 cm = 1 km.","solution":"7 × 50 000 = 350000 cm = 3.5 km.","id":"x056-07","subject":"maths","topic":"Map scales","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is directly proportional to x. When x = 3, y = 24. Find y when x = 8.","answer":64,"hint":"Find k in y = kx.","solution":"k = 24/3 = 8; hence y = 8 × 8 = 64.","id":"x057-07","subject":"maths","topic":"Direct proportion","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is inversely proportional to x. When x = 2, y = 42. Find y when x = 3.","answer":28,"hint":"The product xy stays constant.","solution":"k = 2 × 42 = 84. Thus y = 84/3 = 28.","id":"x058-07","subject":"maths","topic":"Inverse proportion","group":"Proportion and rates","tier":"Higher","calculator":false,"marks":2},{"prompt":"£700 earns 5% compound interest each year. Find the balance after 2 years in pounds.","answer":771.75,"hint":"Multiply by 1.05 for each year.","solution":"£700 × 1.05² = £771.75.","id":"x059-07","subject":"maths","topic":"Compound interest","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A bicycle worth £1750 loses 20% of its value each year. Find its value after 2 years in pounds.","answer":1120,"hint":"Retain 80% each year, using the multiplier 0.8 twice.","solution":"£1750 × 0.8² = £1120.","id":"x060-07","subject":"maths","topic":"Depreciation","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A culture begins with 1400 cells and increases by 10% each hour. Find the modelled count after 2 hours.","answer":1694,"hint":"Use the growth multiplier 1.1 twice.","solution":"1400 × 1.1² = 1694 cells.","id":"x061-07","subject":"maths","topic":"Repeated percentage growth","group":"Finance","tier":"Both","calculator":true,"marks":2},{"prompt":"A block has mass 672 g and volume 84 cm³. Find its density in g/cm³.","answer":8,"hint":"Density = mass ÷ volume.","solution":"672 ÷ 84 = 8 g/cm³.","id":"x062-07","subject":"maths","topic":"Density","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A force of 945 N acts on an area of 21 m². Find pressure in N/m².","answer":45,"hint":"Pressure = force ÷ area.","solution":"945 ÷ 21 = 45 N/m².","id":"x063-07","subject":"maths","topic":"Pressure","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"Convert 8 m² into cm².","answer":80000,"hint":"Square the linear conversion: 1 m = 100 cm.","solution":"1 m² = 100² = 10 000 cm². Therefore 8 m² = 80000 cm².","id":"x064-07","subject":"maths","topic":"Metric area conversions","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A journey starts at 09:17 and ends at 11:45. Find its duration in minutes.","answer":148,"hint":"Count the full hours and the remaining minutes.","solution":"From 09:17 to 11:17 is 120 minutes, then another 28. Total = 148 minutes.","id":"x065-07","subject":"maths","topic":"Time calculations","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle is 15 cm by 11 cm. A 2 cm by 2 cm square is cut from one corner. Find the perimeter of the remaining L-shape in cm.","answer":52,"hint":"The two removed edge lengths are replaced by two equal inner edge lengths.","solution":"The perimeter stays equal to the original rectangle: 2(15 + 11) = 52 cm.","id":"x066-07","subject":"maths","topic":"Perimeter of compound shapes","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 8 cm. Express its circumference as kπ cm. Find k.","answer":16,"hint":"Circumference is 2πr.","solution":"2π × 8 = 16π cm.","id":"x067-07","subject":"maths","topic":"Circle circumference","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 9 cm. Its area is kπ cm². Find k.","answer":81,"hint":"Square the radius and multiply by π.","solution":"Area = π × 9² = 81π cm².","id":"x068-07","subject":"maths","topic":"Area of circles","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A semicircle has radius 9 cm. Its perimeter is πr + d. Find the straight-edge length d in cm.","answer":18,"hint":"The straight edge is the diameter, not the radius.","solution":"d = 2r = 2 × 9 = 18 cm. The complete perimeter is 9π + 18 cm.","id":"x069-07","subject":"maths","topic":"Semicircle perimeter","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 60° and radius 21 cm. Its arc length is kπ cm. Find k.","answer":7,"hint":"Take 60/360 of the circumference.","solution":"(60/360) × 2π × 21 = 7π cm.","id":"x070-07","subject":"maths","topic":"Arc length","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 90° and radius 14 cm. Its area is kπ cm². Find k.","answer":49,"hint":"Take one quarter of the full circle area.","solution":"(90/360) × π × 14² = 49π cm².","id":"x071-07","subject":"maths","topic":"Sector area","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A triangular prism has triangular cross-section base 9 cm, height 6 cm, and prism length 10 cm. Find its volume in cm³.","answer":270,"hint":"Find the triangle area, then multiply by the prism length.","solution":"Cross-section = ½ × 9 × 6 = 27 cm². Volume = 270 cm³.","id":"x072-07","subject":"maths","topic":"Volume of prisms","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A cylinder has radius 8 cm and height 5 cm. Its volume is kπ cm³. Find k.","answer":320,"hint":"Multiply the circular base area by the height.","solution":"πr²h = π × 8² × 5 = 320π cm³.","id":"x073-07","subject":"maths","topic":"Volume of cylinders","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A cone has radius 8 cm and perpendicular height 9 cm. Its volume is kπ cm³. Find k.","answer":192,"hint":"A cone has one third of the corresponding cylinder volume.","solution":"V = πr²h/3 = π × 8² × 9/3 = 192π cm³.","id":"x074-07","subject":"maths","topic":"Volume of cones","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sphere has radius 21 cm. Its volume is kπ cm³. Find k.","answer":12348,"hint":"Use V = 4πr³/3.","solution":"(4/3) × 21³ = 12348, so V = 12348π cm³.","id":"x075-07","subject":"maths","topic":"Volume of spheres","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A cuboid measures 8 cm by 3 cm by 4 cm. Find its total surface area in cm².","answer":136,"hint":"There are two faces of each of the three different rectangular areas.","solution":"2[3(8) + 4(8) + 3×4] = 136 cm².","id":"x076-07","subject":"maths","topic":"Surface area of cuboids","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A closed cylinder has radius 8 cm and height 4 cm. Its total surface area is kπ cm². Find k.","answer":192,"hint":"Include two circular ends and the curved surface.","solution":"2r² + 2rh = 2(8²) + 2(8)(4) = 192.","id":"x077-07","subject":"maths","topic":"Cylinder surface area","group":"Geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"Two similar shapes have length scale factor 3 from small to large. A small side is 9 cm. Find the matching large side.","answer":27,"hint":"Multiply corresponding lengths by the length scale factor.","solution":"9 × 3 = 27 cm.","id":"x078-07","subject":"maths","topic":"Similarity of lengths","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Two similar shapes have length scale factor 2. The smaller area is 10 cm². Find the larger area.","answer":40,"hint":"Square the length scale factor for areas.","solution":"Area factor = 2² = 4. Larger area = 10 × 4 = 40 cm².","id":"x079-07","subject":"maths","topic":"Similarity of areas","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"Two similar solids have length scale factor 3. The smaller volume is 8 cm³. Find the larger volume.","answer":216,"hint":"Cube the length scale factor for volumes.","solution":"Volume factor = 3³ = 27. Larger volume = 216 cm³.","id":"x080-07","subject":"maths","topic":"Similarity of volumes","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A triangle has two angles 47° and 67°. Find the third angle in degrees.","answer":66,"hint":"Interior angles in a triangle total 180°.","solution":"180 − 47 − 67 = 66°.","id":"x081-07","subject":"maths","topic":"Triangle angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A regular polygon has 11 sides. Find its exterior angle in degrees, to 3 decimal places if needed.","answer":32.727,"hint":"The exterior angles total 360°.","solution":"Each exterior angle is 360/11 = 32.727°.","id":"x082-07","subject":"maths","topic":"Exterior angles of polygons","group":"Geometry","tier":"Both","calculator":true,"marks":2},{"prompt":"A transversal crosses two parallel lines. One of a pair of co-interior angles is 81°. Find the other angle in degrees.","answer":99,"hint":"Co-interior angles on parallel lines sum to 180°.","solution":"180 − 81 = 99°.","id":"x083-07","subject":"maths","topic":"Angles in parallel lines","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the sum of the interior angles of a polygon with 10 sides.","answer":1440,"hint":"Use (number of sides − 2) × 180°.","solution":"(10 − 2) × 180 = 1440°.","id":"x084-07","subject":"maths","topic":"Polygon interior-angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"The bearing of B from A is 055°. Find the bearing of A from B as a number of degrees.","answer":235,"hint":"A reverse bearing differs by 180°.","solution":"55 + 180 = 235°.","id":"x085-07","subject":"maths","topic":"Three-figure bearings","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A right-angled triangle has hypotenuse 18 cm and an angle of 30°. Find the side opposite that angle in cm.","answer":9,"hint":"Use sin(angle) = opposite/hypotenuse.","solution":"Opposite = 18 × sin30° = 9 cm.","id":"x086-07","subject":"maths","topic":"Right-angle trigonometry","group":"Trigonometry","tier":"Both","calculator":true,"marks":3},{"prompt":"In a triangle, side a = 9 cm is opposite 30°, and side b is opposite 90°. Find b in cm.","answer":18,"hint":"Use a/sin A = b/sin B.","solution":"b = 9 × sin90°/sin30° = 18 cm.","id":"x087-07","subject":"maths","topic":"Sine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides of a triangle are 9 cm each, with included angle 60°. Find the opposite side in cm.","answer":9,"hint":"Use c² = a² + b² − 2ab cos C.","solution":"c² = 2(9²) − 2(9²)cos60° = 81, so c = 9 cm.","id":"x088-07","subject":"maths","topic":"Cosine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides are 9 cm and 8 cm, with included angle 30°. Find the triangle area in cm².","answer":18,"hint":"Use area = ½ab sin C.","solution":"½ × 9 × 8 × sin30° = 18 cm².","id":"x089-07","subject":"maths","topic":"Triangle area using sine","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"An angle at the circumference is 27°. The central angle subtended by the same arc is less than 180°. Find it.","answer":54,"hint":"The angle at the centre is twice the angle at the circumference on the same arc.","solution":"2 × 27 = 54°.","id":"x090-07","subject":"maths","topic":"Angles at the centre","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"One angle of a cyclic quadrilateral is 104°. Find its opposite angle.","answer":76,"hint":"Opposite angles in a cyclic quadrilateral total 180°.","solution":"180 − 104 = 76°.","id":"x091-07","subject":"maths","topic":"Cyclic quadrilaterals","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"A tangent and chord form an angle of 39°. Find the angle subtended by that chord in the alternate segment.","answer":39,"hint":"The tangent-chord angle equals the angle in the alternate segment.","solution":"By the alternate segment theorem, the required angle is 39°.","id":"x092-07","subject":"maths","topic":"Alternate segment theorem","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"Vectors a = (7, 3) and b = (9, −1). Find the x-component of a + b.","answer":16,"hint":"Add corresponding components.","solution":"a + b = (16, 2), so the x-component is 16.","id":"x093-07","subject":"maths","topic":"Adding vectors","group":"Vectors","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the magnitude of the vector (21, 28).","answer":35,"hint":"Use Pythagoras on the two components.","solution":"√(21² + 28²) = 35.","id":"x094-07","subject":"maths","topic":"Vector magnitude","group":"Vectors","tier":"Higher","calculator":true,"marks":2},{"prompt":"Rotate (7, 9) by 90° anticlockwise about the origin. Find the new x-coordinate.","answer":-9,"hint":"The rule for 90° anticlockwise is (x,y) → (−y,x).","solution":"The image is (−9, 7), so its x-coordinate is −9.","id":"x095-07","subject":"maths","topic":"Rotations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Enlarge (7, 2) by scale factor 3 about the origin. Find the new x-coordinate.","answer":21,"hint":"Multiply both coordinates by the scale factor.","solution":"The image is (21, 6).","id":"x096-07","subject":"maths","topic":"Enlargements","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Translate (7, 4) by the vector (−3, 2). Find the new x-coordinate.","answer":4,"hint":"Add the x-component of the vector to the x-coordinate.","solution":"The image is (4, 6).","id":"x097-07","subject":"maths","topic":"Translations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Reflect (7, 10) in the line y = x. Find the new x-coordinate.","answer":10,"hint":"Reflection in y = x swaps the coordinates.","solution":"The image is (10, 7).","id":"x098-07","subject":"maths","topic":"Reflections","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Points must be exactly 9 cm from a fixed point P. What is their locus?","kind":"choice","options":["A perpendicular bisector through P","A circle centred at P with radius 9 cm","A circle centred at P with diameter 9 cm","A straight line through P"],"correct":1,"answer":null,"hint":"A fixed distance from one point defines a circle.","solution":"All points on a circle of radius 9 cm are exactly 9 cm from its centre P.","id":"x099-07","subject":"maths","topic":"Loci and constructions","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the median of 14, 7, 10, 16, 8.","answer":10,"hint":"Order the values, then choose the middle one.","solution":"The ordered list is 7, 8, 10, 14, 16. Its middle value is 10.","id":"x100-07","subject":"maths","topic":"Finding the median","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the mode of 7, 9, 9, 11, 9, 13.","answer":9,"hint":"Look for the value occurring most frequently.","solution":"9 occurs three times; every other value occurs once.","id":"x101-07","subject":"maths","topic":"Finding the mode","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the range of −7, 2, 11, 0.","answer":18,"hint":"Subtract the minimum from the maximum.","solution":"11 − (−7) = 18.","id":"x102-07","subject":"maths","topic":"Finding the range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A data set has lower quartile 10 and upper quartile 35. Find its interquartile range.","answer":25,"hint":"IQR = upper quartile − lower quartile.","solution":"35 − 10 = 25.","id":"x103-07","subject":"maths","topic":"Interquartile range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A grouped table has 2 values in 0 ≤ x < 10 and 9 values in 10 ≤ x < 20. Estimate the mean, to 3 decimal places.","answer":13.182,"hint":"Use class midpoints 5 and 15, multiply by frequencies, then divide by total frequency.","solution":"Estimated total = 2×5 + 9×15 = 145. Divide by 11 to get 13.182.","id":"x104-07","subject":"maths","topic":"Estimated mean from grouped data","group":"Statistics","tier":"Both","calculator":true,"marks":3},{"prompt":"A histogram class has width 5 and frequency 45. Find its frequency density.","answer":9,"hint":"Frequency density = frequency ÷ class width.","solution":"45 ÷ 5 = 9.","id":"x105-07","subject":"maths","topic":"Frequency density","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"Class frequencies, in ascending order, are 7, 9, 11, 13. Find the cumulative frequency at the end of the third class.","answer":27,"hint":"Add all frequencies up to and including the third class.","solution":"7 + 9 + 11 = 27.","id":"x106-07","subject":"maths","topic":"Cumulative frequency","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A box plot has minimum 7, lower quartile 10, median 13, upper quartile 16, maximum 22. Read off its median.","answer":13,"hint":"The median is the line inside the box.","solution":"The median line is at 13. The ends of the box are the quartiles.","id":"x107-07","subject":"maths","topic":"Box plots","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A school has 600 pupils; 210 are in a chosen group. In a proportional sample of 40 pupils, how many should come from that group?","answer":14,"hint":"Multiply the sample size by the group proportion.","solution":"40 × 210/600 = 14 pupils.","id":"x108-07","subject":"maths","topic":"Stratified sampling","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"An experiment succeeds 10 times out of 20 trials. Find the relative frequency as a fraction or decimal.","answer":0.5,"hint":"Divide the number of successes by the number of trials.","solution":"Relative frequency = 10/20 = 0.5.","id":"x109-07","subject":"maths","topic":"Relative frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"An event has probability 0.3. It is tested 140 times. Find its expected frequency.","answer":42,"hint":"Multiply probability by number of trials.","solution":"0.3 × 140 = 42. This is an expectation, not a guarantee.","id":"x110-07","subject":"maths","topic":"Expected frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Two independent events have probabilities 1/2 and 7/12. Find the probability that both occur.","answer":0.2916666667,"hint":"Multiply the probabilities of independent events.","solution":"1/2 × 7/12 = 7/24.","id":"x111-07","subject":"maths","topic":"Independent events","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A bag has 9 red counters and 3 blue counters. Two counters are drawn without replacement. Find P(both red), to 3 decimal places.","answer":0.545,"hint":"The second draw has one fewer red counter and one fewer counter altogether.","solution":"P = (9/12) × (8/11) = 0.545.","id":"x112-07","subject":"maths","topic":"Sampling without replacement","group":"Probability","tier":"Higher","calculator":true,"marks":3},{"prompt":"Of 12 club members who play tennis, 7 also swim. A member is chosen from the tennis players only. Find P(swims), as a fraction or decimal.","answer":0.5833333333,"hint":"Use the restricted tennis group as the denominator.","solution":"Given that the person plays tennis, P(swims) = 7/12.","id":"x113-07","subject":"maths","topic":"Conditional probability","group":"Probability","tier":"Higher","calculator":false,"marks":2},{"prompt":"Set A contains 29 people including 9 in A ∩ B. How many are in A only?","answer":20,"hint":"Subtract the intersection from the total in A.","solution":"29 − 9 = 20 people.","id":"x114-07","subject":"maths","topic":"Venn diagram regions","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"n(A) = 17, n(B) = 19, and n(A ∩ B) = 10. Find n(A ∪ B).","answer":26,"hint":"Add the two set sizes and subtract the overlap once.","solution":"17 + 19 − 10 = 26.","id":"x115-07","subject":"maths","topic":"Set union","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A fair coin is tossed, then a fair 10-sided die numbered 1 to 10 is rolled. Find P(heads and a 1).","answer":0.05,"hint":"Multiply the branch probabilities along the path.","solution":"(1/2) × (1/10) = 1/20.","id":"x116-07","subject":"maths","topic":"Tree diagrams","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Plot the listed points for y = x³ + 2. Use x = -2, -1, 0, 1, 2. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[-2,-6],[-1,1],[0,2],[1,3],[2,10]],"curve":"quadratic","range":[-3,3,-14,14],"expression":"y = x³ + 2","hint":"Cube each x, preserving its sign, then add the constant.","solution":"The coordinates are (-2, -6), (-1, 1), (0, 2), (1, 3), (2, 10). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x117-07","subject":"maths","topic":"Cubic graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 12/x + 6 for 1 ≤ x ≤ 6. Use x = 1, 2, 3, 4, 6. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[1,18.0],[2,12.0],[3,10.0],[4,9.0],[6,8.0]],"curve":"quadratic","range":[0,7,0,23],"expression":"y = 12/x + 6 for 1 ≤ x ≤ 6","hint":"Divide 12 by x, then add the constant; x = 0 is not allowed.","solution":"The coordinates are (1, 18.0), (2, 12.0), (3, 10.0), (4, 9.0), (6, 8.0). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x118-07","subject":"maths","topic":"Reciprocal graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 2^x + 6. Use x = 0, 1, 2, 3. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[0,7],[1,8],[2,10],[3,14]],"curve":"quadratic","range":[-1,4,0,18],"expression":"y = 2^x + 6","hint":"Calculate the power of 2 first, then add the constant.","solution":"The coordinates are (0, 7), (1, 8), (2, 10), (3, 14). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x119-07","subject":"maths","topic":"Exponential graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"The graph y = x² is translated upward by 9 units. Find the new y-coordinate of its turning point.","answer":9,"hint":"An upward translation adds the same amount to every y-coordinate.","solution":"The old turning point is (0, 0); the new one is (0, 9).","id":"x120-07","subject":"maths","topic":"Translating graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A straight segment on a distance-time graph runs from (0 hours, 0 km) to (2 hours, 84 km). Find the speed in km/h.","answer":42,"hint":"Speed is the gradient: distance change divided by time change.","solution":"84 km ÷ 2 h = 42 km/h.","id":"x121-07","subject":"maths","topic":"Distance-time graphs","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A velocity-time graph rises in a straight line from 0 m/s to 35 m/s in 5 seconds. Find acceleration in m/s².","answer":7,"hint":"Acceleration is change in velocity divided by time.","solution":"(35 − 0)/5 = 7 m/s².","id":"x122-07","subject":"maths","topic":"Velocity-time gradients","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A tangent to a curve passes through (1, 7) and (3, 23). Estimate the gradient of the curve at the contact point.","answer":8,"hint":"Use the gradient of the tangent, not a chord through two curve points.","solution":"(23 − 7)/(3 − 1) = 8.","id":"x123-07","subject":"maths","topic":"Tangents and rates of change","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A velocity-time graph forms a triangle with base 6 seconds and maximum velocity 14 m/s. Find the displacement in metres.","answer":42,"hint":"Displacement is the signed area under a velocity-time graph.","solution":"Area = ½ × 6 × 14 = 42 m.","id":"x124-07","subject":"maths","topic":"Area under velocity-time graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"The lines y = x + 7 and y = 3x intersect. Find the x-coordinate of the intersection.","answer":3.5,"hint":"At the intersection, both expressions for y are equal.","solution":"x + 7 = 3x, so 2x = 7 and x = 3.5.","id":"x125-07","subject":"maths","topic":"Graphical simultaneous equations","group":"Graphs","tier":"Both","calculator":false,"marks":3},{"prompt":"Which point satisfies both x > 7 and y < 3?","kind":"choice","options":["(6, 0)","(8, 2)","(7, 2)","(8, 4)"],"correct":1,"answer":null,"hint":"Test both strict inequalities for each coordinate pair.","solution":"Only (8, 2) has x strictly greater than 7 and y strictly less than 3.","id":"x126-07","subject":"maths","topic":"Regions satisfying inequalities","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate 11 + 10 × 4.","answer":51,"hint":"Do multiplication before addition.","solution":"10 × 4 = 40; then add 11 to get 51.","id":"x001-08","subject":"maths","topic":"Order of operations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"The temperature is −10°C. It falls by 12°C. What is the new temperature in °C?","answer":-22,"hint":"A fall makes the number more negative.","solution":"−10 − 12 = −22°C.","id":"x002-08","subject":"maths","topic":"Calculating with negatives","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the value of the hundreds digit in 1908?","answer":900,"hint":"Identify the digit three places from the right.","solution":"The hundreds digit is 9, so its value is 9 × 100 = 900.","id":"x003-08","subject":"maths","topic":"Place value","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 10.376 to two decimal places.","answer":10.38,"hint":"Look at the third decimal digit.","solution":"The third digit is 6, so round the hundredths up: 10.38.","id":"x004-08","subject":"maths","topic":"Rounding decimal places","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 3770 to two significant figures.","answer":3800,"hint":"Count significant digits from the first non-zero digit.","solution":"The first two significant figures are in the thousands and hundreds columns. Rounding 3770 to the nearest 100 gives 3800.","id":"x005-08","subject":"maths","topic":"Significant figures","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Estimate 10.9 × 19.8 by rounding each number to the nearest whole number first.","answer":220,"hint":"Follow the requested rounding method for both numbers.","solution":"10.9 rounds to 11; 19.8 rounds to 20. The estimate is 220.","id":"x006-08","subject":"maths","topic":"Estimating calculations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"How many positive factors does 512 have?","answer":10,"hint":"For a power of 2, list 2⁰ up to the highest power.","solution":"512 = 2^9. Its factors are 2⁰ through 2^9, giving 10 factors.","id":"x007-08","subject":"maths","topic":"Factors","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the smallest multiple of 11 that is strictly greater than 110?","answer":121,"hint":"The number given is already the tenth multiple.","solution":"The next multiple is 11 × 11 = 121.","id":"x008-08","subject":"maths","topic":"Multiples","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Which number in this list is prime? Set 8.","kind":"choice","options":["37","44","60","90"],"correct":0,"answer":null,"hint":"A prime has exactly two positive factors: 1 and itself.","solution":"37 has no positive factors except 1 and itself. The other numbers have explicit factors 4, 6 or 9.","id":"x009-08","subject":"maths","topic":"Prime numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"In the prime factorisation of 2304, what is the exponent of 2?","answer":8,"hint":"Keep dividing by 2 until the remaining number is odd.","solution":"2304 = 2^8 × 3², so the exponent is 8.","id":"x010-08","subject":"maths","topic":"Prime factorisation","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the highest common factor of 96 and 144.","answer":48,"hint":"Look for the largest factor that divides both numbers.","solution":"96 = 2 × 48 and 144 = 3 × 48. Since 2 and 3 are coprime, the HCF is 48.","id":"x011-08","subject":"maths","topic":"Highest common factor","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the lowest common multiple of 32 and 48.","answer":96,"hint":"Find the HCF first, or list the multiples.","solution":"The HCF is 16. LCM = (32 × 48) ÷ 16 = 96.","id":"x012-08","subject":"maths","topic":"Lowest common multiple","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 8/12 + 1/8. Give a fraction or decimal.","answer":0.7916666667,"hint":"Use a common denominator of 24.","solution":"8/12 = 16/24 and 1/8 = 3/24. The sum is 19/24.","id":"x013-08","subject":"maths","topic":"Adding fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 8/11 × 3/5. Give a fraction or decimal.","answer":0.4363636364,"hint":"Multiply numerators and denominators.","solution":"(8 × 3)/(11 × 5) = 24/55. Simplify if possible.","id":"x014-08","subject":"maths","topic":"Multiplying fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 8/12 ÷ 5/6. Give a fraction or decimal.","answer":0.8,"hint":"Multiply by the reciprocal of 5/6.","solution":"8/12 × 6/5 = 48/60 = 8/10.","id":"x015-08","subject":"maths","topic":"Dividing fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 8 3/4 as a decimal.","answer":8.75,"hint":"The fraction part is three quarters, or 0.75.","solution":"8 + 0.75 = 8.75.","id":"x016-08","subject":"maths","topic":"Mixed numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A club has 192 members. Three eighths cycle to the club. How many members cycle?","answer":72,"hint":"Divide by 8 to find one eighth, then multiply by 3.","solution":"192 ÷ 8 × 3 = 72.","id":"x017-08","subject":"maths","topic":"Fractions of quantities","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 0.181818… (the block 18 repeats) as a fraction or decimal.","answer":0.1818181818,"hint":"For a two-digit repeating block, compare 100x with x.","solution":"If x = 0.1818…, then 100x − x = 18; hence x = 18/99.","id":"x018-08","subject":"maths","topic":"Recurring decimals","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Simplify 3^9 × 3^11 to 3^k. Find k.","answer":20,"hint":"Add exponents when multiplying powers of the same base.","solution":"k = 9 + 11 = 20.","id":"x019-08","subject":"maths","topic":"Index laws","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Evaluate 9^−2. Give a fraction or decimal.","answer":0.012345679,"hint":"A negative exponent gives the reciprocal of the positive power.","solution":"9^−2 = 1/(9²) = 1/81.","id":"x020-08","subject":"maths","topic":"Negative indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Evaluate 1000^(2/3).","answer":100,"hint":"Take the cube root, then square the result.","solution":"The cube root of 1000 is 10; its square is 100.","id":"x021-08","subject":"maths","topic":"Fractional indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write √162 in the form a√2. Find a.","answer":9,"hint":"Look for a square factor inside the root.","solution":"√(81 × 2) = 9√2, so a = 9.","id":"x022-08","subject":"maths","topic":"Simplifying surds","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write 24/√3 in the form a√3. Find a.","answer":8,"hint":"Multiply numerator and denominator by √3.","solution":"(24√3)/3 = 8√3.","id":"x023-08","subject":"maths","topic":"Rationalising denominators","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate (2 × 10^8) × (3 × 10²). Write the result as 6 × 10^k. Find k.","answer":10,"hint":"Multiply the coefficients and add powers of ten.","solution":"2 × 3 = 6 and 8 + 2 = 10, so k = 10.","id":"x024-08","subject":"maths","topic":"Calculating in standard form","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A length is 18 cm to the nearest centimetre. Give the lower bound in cm.","answer":17.5,"hint":"The rounding interval extends half a centimetre either side.","solution":"The lower bound is 18 − 0.5 = 17.5 cm; the upper bound is 18.5 cm and is excluded.","id":"x025-08","subject":"maths","topic":"Error intervals","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle has length 18 cm and width 12 cm, both to the nearest centimetre. Find the upper bound for its area in cm².","answer":231.25,"hint":"Use the upper bound for each positive length.","solution":"Upper area bound = 18.5 × 12.5 = 231.25 cm².","id":"x026-08","subject":"maths","topic":"Upper and lower bounds","group":"Number","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify 10x + 12x − 3x to ax. Find a.","answer":19,"hint":"Combine only the coefficients of x.","solution":"a = 10 + 12 − 3 = 19.","id":"x027-08","subject":"maths","topic":"Collecting like terms","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand 10(x + 9). What is the constant term?","answer":90,"hint":"Multiply both terms inside the bracket.","solution":"The expansion is 10x + 90.","id":"x028-08","subject":"maths","topic":"Expanding a single bracket","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand (x + 8)(x + 11). What is the coefficient of x?","answer":19,"hint":"Multiply every term in one bracket by every term in the other.","solution":"x² + 11x + 8x + 88 = x² + 19x + 88.","id":"x029-08","subject":"maths","topic":"Expanding double brackets","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise fully 16x + 48.","kind":"choice","options":["16(x + 3)","16(x + 6)","8(x + 3)","48(x + 2)"],"correct":0,"answer":null,"hint":"Take out the highest common factor of the two coefficients.","solution":"Both terms contain 16. Dividing gives x and 3, so the result is 16(x + 3).","id":"x030-08","subject":"maths","topic":"Factorising with a common factor","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise x² + 19x + 88.","kind":"choice","options":["(x + 8)(x + 11)","(x − 8)(x − 11)","(x + 9)(x + 10)","(x − 8)(x + 11)"],"correct":0,"answer":null,"hint":"Find two numbers whose product is the constant and whose sum is the x coefficient.","solution":"8 × 11 = 88 and 8 + 11 = 19.","id":"x031-08","subject":"maths","topic":"Factorising quadratics","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Find 2a² − b when a = 8 and b = 11.","answer":117,"hint":"Square a before multiplying by 2.","solution":"2 × 8² − 11 = 117.","id":"x032-08","subject":"maths","topic":"Substitution","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The formula is y = 10x − 8. If y = 82, find x.","answer":9,"hint":"Add the constant to y, then divide by the coefficient of x.","solution":"x = (y + 8)/10 = 90/10 = 9.","id":"x033-08","subject":"maths","topic":"Changing the subject","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the smallest integer satisfying 3x + 8 > 32.","answer":9,"hint":"Subtract the constant, divide by 3, then respect the strict inequality.","solution":"3x > 24, so x > 8. The smallest integer is 9.","id":"x034-08","subject":"maths","topic":"Linear inequalities","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Solve x + y = 25 and x − y = 9. Give x.","answer":17,"hint":"Add the two equations to eliminate y.","solution":"2x = 34, so x = 17.","id":"x035-08","subject":"maths","topic":"Simultaneous linear equations","group":"Algebra","tier":"Both","calculator":false,"marks":3},{"prompt":"The graphs y = x² and y = 64 meet. Give the positive x-coordinate.","answer":8,"hint":"Substitute to obtain x² equal to the constant.","solution":"x² = 64, so x = ±8. The positive value is 8.","id":"x036-08","subject":"maths","topic":"Simultaneous nonlinear equations","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"Write x² + 16x + 74 as (x + a)² + b. Find b.","answer":10,"hint":"Half the x coefficient gives a. Subtract a² from the constant.","solution":"a = 8. Subtract 64 from the constant 74 to get b = 10.","id":"x037-08","subject":"maths","topic":"Completing the square","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Use the quadratic formula to find the positive root of x² + x − 72 = 0.","answer":8,"hint":"Identify a, b and c. Use x = (−b ± √(b² − 4ac))/(2a).","solution":"a=1, b=1, c=−72. The discriminant is 1 + 288 = 289. The positive root is (−1 + 17)/2 = 8.","id":"x038-08","subject":"maths","topic":"Quadratic formula","group":"Algebra","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify (10x)/(20x²) for x ≠ 0, then evaluate at x = 8.","answer":0.0625,"hint":"Cancel the common numerical factor and one factor of x.","solution":"The expression simplifies to 1/(2x). At x = 8, it is 1/16.","id":"x039-08","subject":"maths","topic":"Algebraic fractions","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"The difference (k + 1)² − k² simplifies to 2k + 1. Use this identity to find the difference between the squares of 12 and 13.","answer":25,"hint":"Expand the square before cancelling k².","solution":"Expanding proves (k + 1)² − k² = 2k + 1. Set k = 12: the difference is 25.","id":"x040-08","subject":"maths","topic":"Algebraic proof","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x − 8. Find f(10).","answer":22,"hint":"Replace every x with the specified input.","solution":"f(10) = 3(10) − 8 = 22.","id":"x041-08","subject":"maths","topic":"Function notation","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"f(x) = 2x + 1 and g(x) = x². Find f(g(8)).","answer":129,"hint":"Apply the inside function first.","solution":"g(8) = 64; f(64) = 129.","id":"x042-08","subject":"maths","topic":"Composite functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x + 8. Find f⁻¹(32).","answer":8,"hint":"Undo the addition, then undo the multiplication.","solution":"f⁻¹(y) = (y − 8)/3. With y = 32, this gives 8.","id":"x043-08","subject":"maths","topic":"Inverse functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"x₀ = 8. Use x_(k+1) = (x_k + 4)/2 to calculate x₂.","answer":5.0,"hint":"Calculate x₁ first and substitute that new value again.","solution":"x₁ = (8 + 4)/2 = 6.0. Then x₂ = (6.0 + 4)/2 = 5.0.","id":"x044-08","subject":"maths","topic":"Iteration","group":"Algebra","tier":"Higher","calculator":true,"marks":2},{"prompt":"A geometric sequence starts at 9 and has common ratio 3. Find its fourth term.","answer":243,"hint":"Multiply by 3 three times after the first term.","solution":"The fourth term is 9 × 3³ = 243.","id":"x045-08","subject":"maths","topic":"Geometric sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The nth term is n² + 8n + 2. Find the fifth term.","answer":67,"hint":"Replace each occurrence of n (the position variable) with 5.","solution":"5² + 8 × 5 + 2 = 67.","id":"x046-08","subject":"maths","topic":"Quadratic sequences","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sequence begins 8, 9. Each new term is the sum of the preceding two. Find the fifth term.","answer":43,"hint":"Build the third and fourth terms before the fifth.","solution":"The terms are 8, 9, 17, 26, 43.","id":"x047-08","subject":"maths","topic":"Fibonacci-type sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the x-coordinate of the midpoint of (8, 2) and (26, 8).","answer":17,"hint":"Average the two x-coordinates.","solution":"(8 + 26)/2 = 17. The full midpoint is (17, 5).","id":"x048-08","subject":"maths","topic":"Midpoints","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the distance between (0, 0) and (24, 32).","answer":40,"hint":"Use the horizontal and vertical differences in Pythagoras.","solution":"√(24² + 32²) = 40 units.","id":"x049-08","subject":"maths","topic":"Distance between coordinates","group":"Coordinate geometry","tier":"Both","calculator":true,"marks":3},{"prompt":"A line is parallel to y = 9x − 4 and passes through (0, 8). Give its gradient.","answer":9,"hint":"Parallel non-vertical lines have equal gradients.","solution":"The given line has gradient 9, so the parallel line does too.","id":"x050-08","subject":"maths","topic":"Parallel lines","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the gradient of a line perpendicular to y = 9x + 2. Give a fraction or decimal.","answer":-0.1111111111,"hint":"For non-zero gradients, the perpendicular gradient is the negative reciprocal.","solution":"The negative reciprocal of 9 is −1/9.","id":"x051-08","subject":"maths","topic":"Perpendicular lines","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A line passes through (1, 17) and (3, 33). Write it as y = mx + c. Find c.","answer":9,"hint":"Find the gradient from the two points, then substitute a point.","solution":"m = (33 − 17)/2 = 8. Then c = 17 − 8 = 9.","id":"x052-08","subject":"maths","topic":"Equation of a line through points","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"A pack of 11 notebooks costs £99. Find the price per notebook in pounds.","answer":9,"hint":"Divide cost by number of items.","solution":"£99 ÷ 11 = £9 per notebook.","id":"x053-08","subject":"maths","topic":"Best buys and unit pricing","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"£1 exchanges for €1.20. How many euros are exchanged for £200?","answer":240,"hint":"Multiply the pound amount by the euros-per-pound rate.","solution":"200 × 1.20 = €240.","id":"x054-08","subject":"maths","topic":"Currency conversion","group":"Proportion and rates","tier":"Both","calculator":true,"marks":2},{"prompt":"A recipe for 4 people uses 240 g of rice. How many grams are needed for 6 people?","answer":360.0,"hint":"Scale every ingredient by 6/4.","solution":"240 × 6/4 = 360.0 g.","id":"x055-08","subject":"maths","topic":"Scaling recipes","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"A map has scale 1:50 000. Two places are 8 cm apart on the map. Find their real distance in kilometres.","answer":4.0,"hint":"Convert the scaled centimetres into kilometres using 100 000 cm = 1 km.","solution":"8 × 50 000 = 400000 cm = 4.0 km.","id":"x056-08","subject":"maths","topic":"Map scales","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is directly proportional to x. When x = 3, y = 27. Find y when x = 8.","answer":72,"hint":"Find k in y = kx.","solution":"k = 27/3 = 9; hence y = 9 × 8 = 72.","id":"x057-08","subject":"maths","topic":"Direct proportion","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is inversely proportional to x. When x = 2, y = 48. Find y when x = 3.","answer":32,"hint":"The product xy stays constant.","solution":"k = 2 × 48 = 96. Thus y = 96/3 = 32.","id":"x058-08","subject":"maths","topic":"Inverse proportion","group":"Proportion and rates","tier":"Higher","calculator":false,"marks":2},{"prompt":"£800 earns 5% compound interest each year. Find the balance after 2 years in pounds.","answer":882.0,"hint":"Multiply by 1.05 for each year.","solution":"£800 × 1.05² = £882.00.","id":"x059-08","subject":"maths","topic":"Compound interest","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A bicycle worth £2000 loses 20% of its value each year. Find its value after 2 years in pounds.","answer":1280,"hint":"Retain 80% each year, using the multiplier 0.8 twice.","solution":"£2000 × 0.8² = £1280.","id":"x060-08","subject":"maths","topic":"Depreciation","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A culture begins with 1600 cells and increases by 10% each hour. Find the modelled count after 2 hours.","answer":1936,"hint":"Use the growth multiplier 1.1 twice.","solution":"1600 × 1.1² = 1936 cells.","id":"x061-08","subject":"maths","topic":"Repeated percentage growth","group":"Finance","tier":"Both","calculator":true,"marks":2},{"prompt":"A block has mass 864 g and volume 96 cm³. Find its density in g/cm³.","answer":9,"hint":"Density = mass ÷ volume.","solution":"864 ÷ 96 = 9 g/cm³.","id":"x062-08","subject":"maths","topic":"Density","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A force of 1200 N acts on an area of 24 m². Find pressure in N/m².","answer":50,"hint":"Pressure = force ÷ area.","solution":"1200 ÷ 24 = 50 N/m².","id":"x063-08","subject":"maths","topic":"Pressure","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"Convert 9 m² into cm².","answer":90000,"hint":"Square the linear conversion: 1 m = 100 cm.","solution":"1 m² = 100² = 10 000 cm². Therefore 9 m² = 90000 cm².","id":"x064-08","subject":"maths","topic":"Metric area conversions","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A journey starts at 09:18 and ends at 11:45. Find its duration in minutes.","answer":147,"hint":"Count the full hours and the remaining minutes.","solution":"From 09:18 to 11:18 is 120 minutes, then another 27. Total = 147 minutes.","id":"x065-08","subject":"maths","topic":"Time calculations","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle is 16 cm by 12 cm. A 2 cm by 2 cm square is cut from one corner. Find the perimeter of the remaining L-shape in cm.","answer":56,"hint":"The two removed edge lengths are replaced by two equal inner edge lengths.","solution":"The perimeter stays equal to the original rectangle: 2(16 + 12) = 56 cm.","id":"x066-08","subject":"maths","topic":"Perimeter of compound shapes","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 9 cm. Express its circumference as kπ cm. Find k.","answer":18,"hint":"Circumference is 2πr.","solution":"2π × 9 = 18π cm.","id":"x067-08","subject":"maths","topic":"Circle circumference","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 10 cm. Its area is kπ cm². Find k.","answer":100,"hint":"Square the radius and multiply by π.","solution":"Area = π × 10² = 100π cm².","id":"x068-08","subject":"maths","topic":"Area of circles","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A semicircle has radius 10 cm. Its perimeter is πr + d. Find the straight-edge length d in cm.","answer":20,"hint":"The straight edge is the diameter, not the radius.","solution":"d = 2r = 2 × 10 = 20 cm. The complete perimeter is 10π + 20 cm.","id":"x069-08","subject":"maths","topic":"Semicircle perimeter","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 60° and radius 24 cm. Its arc length is kπ cm. Find k.","answer":8,"hint":"Take 60/360 of the circumference.","solution":"(60/360) × 2π × 24 = 8π cm.","id":"x070-08","subject":"maths","topic":"Arc length","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 90° and radius 16 cm. Its area is kπ cm². Find k.","answer":64,"hint":"Take one quarter of the full circle area.","solution":"(90/360) × π × 16² = 64π cm².","id":"x071-08","subject":"maths","topic":"Sector area","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A triangular prism has triangular cross-section base 10 cm, height 6 cm, and prism length 10 cm. Find its volume in cm³.","answer":300,"hint":"Find the triangle area, then multiply by the prism length.","solution":"Cross-section = ½ × 10 × 6 = 30 cm². Volume = 300 cm³.","id":"x072-08","subject":"maths","topic":"Volume of prisms","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A cylinder has radius 9 cm and height 5 cm. Its volume is kπ cm³. Find k.","answer":405,"hint":"Multiply the circular base area by the height.","solution":"πr²h = π × 9² × 5 = 405π cm³.","id":"x073-08","subject":"maths","topic":"Volume of cylinders","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A cone has radius 9 cm and perpendicular height 9 cm. Its volume is kπ cm³. Find k.","answer":243,"hint":"A cone has one third of the corresponding cylinder volume.","solution":"V = πr²h/3 = π × 9² × 9/3 = 243π cm³.","id":"x074-08","subject":"maths","topic":"Volume of cones","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sphere has radius 24 cm. Its volume is kπ cm³. Find k.","answer":18432,"hint":"Use V = 4πr³/3.","solution":"(4/3) × 24³ = 18432, so V = 18432π cm³.","id":"x075-08","subject":"maths","topic":"Volume of spheres","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A cuboid measures 9 cm by 3 cm by 4 cm. Find its total surface area in cm².","answer":150,"hint":"There are two faces of each of the three different rectangular areas.","solution":"2[3(9) + 4(9) + 3×4] = 150 cm².","id":"x076-08","subject":"maths","topic":"Surface area of cuboids","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A closed cylinder has radius 9 cm and height 4 cm. Its total surface area is kπ cm². Find k.","answer":234,"hint":"Include two circular ends and the curved surface.","solution":"2r² + 2rh = 2(9²) + 2(9)(4) = 234.","id":"x077-08","subject":"maths","topic":"Cylinder surface area","group":"Geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"Two similar shapes have length scale factor 3 from small to large. A small side is 10 cm. Find the matching large side.","answer":30,"hint":"Multiply corresponding lengths by the length scale factor.","solution":"10 × 3 = 30 cm.","id":"x078-08","subject":"maths","topic":"Similarity of lengths","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Two similar shapes have length scale factor 2. The smaller area is 11 cm². Find the larger area.","answer":44,"hint":"Square the length scale factor for areas.","solution":"Area factor = 2² = 4. Larger area = 11 × 4 = 44 cm².","id":"x079-08","subject":"maths","topic":"Similarity of areas","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"Two similar solids have length scale factor 3. The smaller volume is 9 cm³. Find the larger volume.","answer":243,"hint":"Cube the length scale factor for volumes.","solution":"Volume factor = 3³ = 27. Larger volume = 243 cm³.","id":"x080-08","subject":"maths","topic":"Similarity of volumes","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A triangle has two angles 48° and 68°. Find the third angle in degrees.","answer":64,"hint":"Interior angles in a triangle total 180°.","solution":"180 − 48 − 68 = 64°.","id":"x081-08","subject":"maths","topic":"Triangle angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A regular polygon has 12 sides. Find its exterior angle in degrees, to 3 decimal places if needed.","answer":30.0,"hint":"The exterior angles total 360°.","solution":"Each exterior angle is 360/12 = 30.000°.","id":"x082-08","subject":"maths","topic":"Exterior angles of polygons","group":"Geometry","tier":"Both","calculator":true,"marks":2},{"prompt":"A transversal crosses two parallel lines. One of a pair of co-interior angles is 84°. Find the other angle in degrees.","answer":96,"hint":"Co-interior angles on parallel lines sum to 180°.","solution":"180 − 84 = 96°.","id":"x083-08","subject":"maths","topic":"Angles in parallel lines","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the sum of the interior angles of a polygon with 11 sides.","answer":1620,"hint":"Use (number of sides − 2) × 180°.","solution":"(11 − 2) × 180 = 1620°.","id":"x084-08","subject":"maths","topic":"Polygon interior-angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"The bearing of B from A is 060°. Find the bearing of A from B as a number of degrees.","answer":240,"hint":"A reverse bearing differs by 180°.","solution":"60 + 180 = 240°.","id":"x085-08","subject":"maths","topic":"Three-figure bearings","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A right-angled triangle has hypotenuse 20 cm and an angle of 30°. Find the side opposite that angle in cm.","answer":10,"hint":"Use sin(angle) = opposite/hypotenuse.","solution":"Opposite = 20 × sin30° = 10 cm.","id":"x086-08","subject":"maths","topic":"Right-angle trigonometry","group":"Trigonometry","tier":"Both","calculator":true,"marks":3},{"prompt":"In a triangle, side a = 10 cm is opposite 30°, and side b is opposite 90°. Find b in cm.","answer":20,"hint":"Use a/sin A = b/sin B.","solution":"b = 10 × sin90°/sin30° = 20 cm.","id":"x087-08","subject":"maths","topic":"Sine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides of a triangle are 10 cm each, with included angle 60°. Find the opposite side in cm.","answer":10,"hint":"Use c² = a² + b² − 2ab cos C.","solution":"c² = 2(10²) − 2(10²)cos60° = 100, so c = 10 cm.","id":"x088-08","subject":"maths","topic":"Cosine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides are 10 cm and 8 cm, with included angle 30°. Find the triangle area in cm².","answer":20,"hint":"Use area = ½ab sin C.","solution":"½ × 10 × 8 × sin30° = 20 cm².","id":"x089-08","subject":"maths","topic":"Triangle area using sine","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"An angle at the circumference is 28°. The central angle subtended by the same arc is less than 180°. Find it.","answer":56,"hint":"The angle at the centre is twice the angle at the circumference on the same arc.","solution":"2 × 28 = 56°.","id":"x090-08","subject":"maths","topic":"Angles at the centre","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"One angle of a cyclic quadrilateral is 106°. Find its opposite angle.","answer":74,"hint":"Opposite angles in a cyclic quadrilateral total 180°.","solution":"180 − 106 = 74°.","id":"x091-08","subject":"maths","topic":"Cyclic quadrilaterals","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"A tangent and chord form an angle of 41°. Find the angle subtended by that chord in the alternate segment.","answer":41,"hint":"The tangent-chord angle equals the angle in the alternate segment.","solution":"By the alternate segment theorem, the required angle is 41°.","id":"x092-08","subject":"maths","topic":"Alternate segment theorem","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"Vectors a = (8, 3) and b = (10, −1). Find the x-component of a + b.","answer":18,"hint":"Add corresponding components.","solution":"a + b = (18, 2), so the x-component is 18.","id":"x093-08","subject":"maths","topic":"Adding vectors","group":"Vectors","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the magnitude of the vector (24, 32).","answer":40,"hint":"Use Pythagoras on the two components.","solution":"√(24² + 32²) = 40.","id":"x094-08","subject":"maths","topic":"Vector magnitude","group":"Vectors","tier":"Higher","calculator":true,"marks":2},{"prompt":"Rotate (8, 10) by 90° anticlockwise about the origin. Find the new x-coordinate.","answer":-10,"hint":"The rule for 90° anticlockwise is (x,y) → (−y,x).","solution":"The image is (−10, 8), so its x-coordinate is −10.","id":"x095-08","subject":"maths","topic":"Rotations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Enlarge (8, 2) by scale factor 3 about the origin. Find the new x-coordinate.","answer":24,"hint":"Multiply both coordinates by the scale factor.","solution":"The image is (24, 6).","id":"x096-08","subject":"maths","topic":"Enlargements","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Translate (8, 4) by the vector (−3, 2). Find the new x-coordinate.","answer":5,"hint":"Add the x-component of the vector to the x-coordinate.","solution":"The image is (5, 6).","id":"x097-08","subject":"maths","topic":"Translations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Reflect (8, 11) in the line y = x. Find the new x-coordinate.","answer":11,"hint":"Reflection in y = x swaps the coordinates.","solution":"The image is (11, 8).","id":"x098-08","subject":"maths","topic":"Reflections","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Points must be exactly 10 cm from a fixed point P. What is their locus?","kind":"choice","options":["A circle centred at P with radius 10 cm","A circle centred at P with diameter 10 cm","A straight line through P","A perpendicular bisector through P"],"correct":0,"answer":null,"hint":"A fixed distance from one point defines a circle.","solution":"All points on a circle of radius 10 cm are exactly 10 cm from its centre P.","id":"x099-08","subject":"maths","topic":"Loci and constructions","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the median of 15, 8, 11, 17, 9.","answer":11,"hint":"Order the values, then choose the middle one.","solution":"The ordered list is 8, 9, 11, 15, 17. Its middle value is 11.","id":"x100-08","subject":"maths","topic":"Finding the median","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the mode of 8, 10, 10, 12, 10, 14.","answer":10,"hint":"Look for the value occurring most frequently.","solution":"10 occurs three times; every other value occurs once.","id":"x101-08","subject":"maths","topic":"Finding the mode","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the range of −8, 2, 12, 0.","answer":20,"hint":"Subtract the minimum from the maximum.","solution":"12 − (−8) = 20.","id":"x102-08","subject":"maths","topic":"Finding the range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A data set has lower quartile 11 and upper quartile 39. Find its interquartile range.","answer":28,"hint":"IQR = upper quartile − lower quartile.","solution":"39 − 11 = 28.","id":"x103-08","subject":"maths","topic":"Interquartile range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A grouped table has 2 values in 0 ≤ x < 10 and 10 values in 10 ≤ x < 20. Estimate the mean, to 3 decimal places.","answer":13.333,"hint":"Use class midpoints 5 and 15, multiply by frequencies, then divide by total frequency.","solution":"Estimated total = 2×5 + 10×15 = 160. Divide by 12 to get 13.333.","id":"x104-08","subject":"maths","topic":"Estimated mean from grouped data","group":"Statistics","tier":"Both","calculator":true,"marks":3},{"prompt":"A histogram class has width 5 and frequency 50. Find its frequency density.","answer":10,"hint":"Frequency density = frequency ÷ class width.","solution":"50 ÷ 5 = 10.","id":"x105-08","subject":"maths","topic":"Frequency density","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"Class frequencies, in ascending order, are 8, 10, 12, 14. Find the cumulative frequency at the end of the third class.","answer":30,"hint":"Add all frequencies up to and including the third class.","solution":"8 + 10 + 12 = 30.","id":"x106-08","subject":"maths","topic":"Cumulative frequency","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A box plot has minimum 8, lower quartile 11, median 14, upper quartile 17, maximum 23. Read off its median.","answer":14,"hint":"The median is the line inside the box.","solution":"The median line is at 14. The ends of the box are the quartiles.","id":"x107-08","subject":"maths","topic":"Box plots","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A school has 600 pupils; 240 are in a chosen group. In a proportional sample of 40 pupils, how many should come from that group?","answer":16,"hint":"Multiply the sample size by the group proportion.","solution":"40 × 240/600 = 16 pupils.","id":"x108-08","subject":"maths","topic":"Stratified sampling","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"An experiment succeeds 11 times out of 20 trials. Find the relative frequency as a fraction or decimal.","answer":0.55,"hint":"Divide the number of successes by the number of trials.","solution":"Relative frequency = 11/20 = 0.55.","id":"x109-08","subject":"maths","topic":"Relative frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"An event has probability 0.3. It is tested 160 times. Find its expected frequency.","answer":48,"hint":"Multiply probability by number of trials.","solution":"0.3 × 160 = 48. This is an expectation, not a guarantee.","id":"x110-08","subject":"maths","topic":"Expected frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Two independent events have probabilities 1/2 and 8/12. Find the probability that both occur.","answer":0.3333333333,"hint":"Multiply the probabilities of independent events.","solution":"1/2 × 8/12 = 8/24.","id":"x111-08","subject":"maths","topic":"Independent events","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A bag has 10 red counters and 3 blue counters. Two counters are drawn without replacement. Find P(both red), to 3 decimal places.","answer":0.577,"hint":"The second draw has one fewer red counter and one fewer counter altogether.","solution":"P = (10/13) × (9/12) = 0.577.","id":"x112-08","subject":"maths","topic":"Sampling without replacement","group":"Probability","tier":"Higher","calculator":true,"marks":3},{"prompt":"Of 13 club members who play tennis, 8 also swim. A member is chosen from the tennis players only. Find P(swims), as a fraction or decimal.","answer":0.6153846154,"hint":"Use the restricted tennis group as the denominator.","solution":"Given that the person plays tennis, P(swims) = 8/13.","id":"x113-08","subject":"maths","topic":"Conditional probability","group":"Probability","tier":"Higher","calculator":false,"marks":2},{"prompt":"Set A contains 32 people including 10 in A ∩ B. How many are in A only?","answer":22,"hint":"Subtract the intersection from the total in A.","solution":"32 − 10 = 22 people.","id":"x114-08","subject":"maths","topic":"Venn diagram regions","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"n(A) = 18, n(B) = 20, and n(A ∩ B) = 11. Find n(A ∪ B).","answer":27,"hint":"Add the two set sizes and subtract the overlap once.","solution":"18 + 20 − 11 = 27.","id":"x115-08","subject":"maths","topic":"Set union","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A fair coin is tossed, then a fair 11-sided die numbered 1 to 11 is rolled. Find P(heads and a 1).","answer":0.0454545455,"hint":"Multiply the branch probabilities along the path.","solution":"(1/2) × (1/11) = 1/22.","id":"x116-08","subject":"maths","topic":"Tree diagrams","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Plot the listed points for y = x³ + 3. Use x = -2, -1, 0, 1, 2. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[-2,-5],[-1,2],[0,3],[1,4],[2,11]],"curve":"quadratic","range":[-3,3,-14,14],"expression":"y = x³ + 3","hint":"Cube each x, preserving its sign, then add the constant.","solution":"The coordinates are (-2, -5), (-1, 2), (0, 3), (1, 4), (2, 11). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x117-08","subject":"maths","topic":"Cubic graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 12/x + 7 for 1 ≤ x ≤ 6. Use x = 1, 2, 3, 4, 6. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[1,19.0],[2,13.0],[3,11.0],[4,10.0],[6,9.0]],"curve":"quadratic","range":[0,7,0,23],"expression":"y = 12/x + 7 for 1 ≤ x ≤ 6","hint":"Divide 12 by x, then add the constant; x = 0 is not allowed.","solution":"The coordinates are (1, 19.0), (2, 13.0), (3, 11.0), (4, 10.0), (6, 9.0). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x118-08","subject":"maths","topic":"Reciprocal graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 2^x + 7. Use x = 0, 1, 2, 3. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[0,8],[1,9],[2,11],[3,15]],"curve":"quadratic","range":[-1,4,0,18],"expression":"y = 2^x + 7","hint":"Calculate the power of 2 first, then add the constant.","solution":"The coordinates are (0, 8), (1, 9), (2, 11), (3, 15). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x119-08","subject":"maths","topic":"Exponential graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"The graph y = x² is translated upward by 10 units. Find the new y-coordinate of its turning point.","answer":10,"hint":"An upward translation adds the same amount to every y-coordinate.","solution":"The old turning point is (0, 0); the new one is (0, 10).","id":"x120-08","subject":"maths","topic":"Translating graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A straight segment on a distance-time graph runs from (0 hours, 0 km) to (2 hours, 96 km). Find the speed in km/h.","answer":48,"hint":"Speed is the gradient: distance change divided by time change.","solution":"96 km ÷ 2 h = 48 km/h.","id":"x121-08","subject":"maths","topic":"Distance-time graphs","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A velocity-time graph rises in a straight line from 0 m/s to 40 m/s in 5 seconds. Find acceleration in m/s².","answer":8,"hint":"Acceleration is change in velocity divided by time.","solution":"(40 − 0)/5 = 8 m/s².","id":"x122-08","subject":"maths","topic":"Velocity-time gradients","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A tangent to a curve passes through (1, 8) and (3, 26). Estimate the gradient of the curve at the contact point.","answer":9,"hint":"Use the gradient of the tangent, not a chord through two curve points.","solution":"(26 − 8)/(3 − 1) = 9.","id":"x123-08","subject":"maths","topic":"Tangents and rates of change","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A velocity-time graph forms a triangle with base 6 seconds and maximum velocity 16 m/s. Find the displacement in metres.","answer":48,"hint":"Displacement is the signed area under a velocity-time graph.","solution":"Area = ½ × 6 × 16 = 48 m.","id":"x124-08","subject":"maths","topic":"Area under velocity-time graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"The lines y = x + 8 and y = 3x intersect. Find the x-coordinate of the intersection.","answer":4.0,"hint":"At the intersection, both expressions for y are equal.","solution":"x + 8 = 3x, so 2x = 8 and x = 4.0.","id":"x125-08","subject":"maths","topic":"Graphical simultaneous equations","group":"Graphs","tier":"Both","calculator":false,"marks":3},{"prompt":"Which point satisfies both x > 8 and y < 3?","kind":"choice","options":["(9, 2)","(8, 2)","(9, 4)","(7, 0)"],"correct":0,"answer":null,"hint":"Test both strict inequalities for each coordinate pair.","solution":"Only (9, 2) has x strictly greater than 8 and y strictly less than 3.","id":"x126-08","subject":"maths","topic":"Regions satisfying inequalities","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate 12 + 11 × 4.","answer":56,"hint":"Do multiplication before addition.","solution":"11 × 4 = 44; then add 12 to get 56.","id":"x001-09","subject":"maths","topic":"Order of operations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"The temperature is −11°C. It falls by 13°C. What is the new temperature in °C?","answer":-24,"hint":"A fall makes the number more negative.","solution":"−11 − 13 = −24°C.","id":"x002-09","subject":"maths","topic":"Calculating with negatives","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the value of the hundreds digit in 1109?","answer":100,"hint":"Identify the digit three places from the right.","solution":"The hundreds digit is 1, so its value is 1 × 100 = 100.","id":"x003-09","subject":"maths","topic":"Place value","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 11.376 to two decimal places.","answer":11.38,"hint":"Look at the third decimal digit.","solution":"The third digit is 6, so round the hundredths up: 11.38.","id":"x004-09","subject":"maths","topic":"Rounding decimal places","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 4087 to two significant figures.","answer":4100,"hint":"Count significant digits from the first non-zero digit.","solution":"The first two significant figures are in the thousands and hundreds columns. Rounding 4087 to the nearest 100 gives 4100.","id":"x005-09","subject":"maths","topic":"Significant figures","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Estimate 11.9 × 19.8 by rounding each number to the nearest whole number first.","answer":240,"hint":"Follow the requested rounding method for both numbers.","solution":"11.9 rounds to 12; 19.8 rounds to 20. The estimate is 240.","id":"x006-09","subject":"maths","topic":"Estimating calculations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"How many positive factors does 1024 have?","answer":11,"hint":"For a power of 2, list 2⁰ up to the highest power.","solution":"1024 = 2^10. Its factors are 2⁰ through 2^10, giving 11 factors.","id":"x007-09","subject":"maths","topic":"Factors","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the smallest multiple of 12 that is strictly greater than 120?","answer":132,"hint":"The number given is already the tenth multiple.","solution":"The next multiple is 11 × 12 = 132.","id":"x008-09","subject":"maths","topic":"Multiples","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Which number in this list is prime? Set 9.","kind":"choice","options":["48","66","99","41"],"correct":3,"answer":null,"hint":"A prime has exactly two positive factors: 1 and itself.","solution":"41 has no positive factors except 1 and itself. The other numbers have explicit factors 4, 6 or 9.","id":"x009-09","subject":"maths","topic":"Prime numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"In the prime factorisation of 4608, what is the exponent of 2?","answer":9,"hint":"Keep dividing by 2 until the remaining number is odd.","solution":"4608 = 2^9 × 3², so the exponent is 9.","id":"x010-09","subject":"maths","topic":"Prime factorisation","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the highest common factor of 108 and 162.","answer":54,"hint":"Look for the largest factor that divides both numbers.","solution":"108 = 2 × 54 and 162 = 3 × 54. Since 2 and 3 are coprime, the HCF is 54.","id":"x011-09","subject":"maths","topic":"Highest common factor","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the lowest common multiple of 36 and 54.","answer":108,"hint":"Find the HCF first, or list the multiples.","solution":"The HCF is 18. LCM = (36 × 54) ÷ 18 = 108.","id":"x012-09","subject":"maths","topic":"Lowest common multiple","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 9/12 + 1/8. Give a fraction or decimal.","answer":0.875,"hint":"Use a common denominator of 24.","solution":"9/12 = 18/24 and 1/8 = 3/24. The sum is 21/24.","id":"x013-09","subject":"maths","topic":"Adding fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 9/11 × 3/5. Give a fraction or decimal.","answer":0.4909090909,"hint":"Multiply numerators and denominators.","solution":"(9 × 3)/(11 × 5) = 27/55. Simplify if possible.","id":"x014-09","subject":"maths","topic":"Multiplying fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 9/12 ÷ 5/6. Give a fraction or decimal.","answer":0.9,"hint":"Multiply by the reciprocal of 5/6.","solution":"9/12 × 6/5 = 54/60 = 9/10.","id":"x015-09","subject":"maths","topic":"Dividing fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 9 3/4 as a decimal.","answer":9.75,"hint":"The fraction part is three quarters, or 0.75.","solution":"9 + 0.75 = 9.75.","id":"x016-09","subject":"maths","topic":"Mixed numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A club has 216 members. Three eighths cycle to the club. How many members cycle?","answer":81,"hint":"Divide by 8 to find one eighth, then multiply by 3.","solution":"216 ÷ 8 × 3 = 81.","id":"x017-09","subject":"maths","topic":"Fractions of quantities","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 0.191919… (the block 19 repeats) as a fraction or decimal.","answer":0.1919191919,"hint":"For a two-digit repeating block, compare 100x with x.","solution":"If x = 0.1919…, then 100x − x = 19; hence x = 19/99.","id":"x018-09","subject":"maths","topic":"Recurring decimals","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Simplify 3^10 × 3^12 to 3^k. Find k.","answer":22,"hint":"Add exponents when multiplying powers of the same base.","solution":"k = 10 + 12 = 22.","id":"x019-09","subject":"maths","topic":"Index laws","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Evaluate 10^−2. Give a fraction or decimal.","answer":0.01,"hint":"A negative exponent gives the reciprocal of the positive power.","solution":"10^−2 = 1/(10²) = 1/100.","id":"x020-09","subject":"maths","topic":"Negative indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Evaluate 1331^(2/3).","answer":121,"hint":"Take the cube root, then square the result.","solution":"The cube root of 1331 is 11; its square is 121.","id":"x021-09","subject":"maths","topic":"Fractional indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write √200 in the form a√2. Find a.","answer":10,"hint":"Look for a square factor inside the root.","solution":"√(100 × 2) = 10√2, so a = 10.","id":"x022-09","subject":"maths","topic":"Simplifying surds","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write 27/√3 in the form a√3. Find a.","answer":9,"hint":"Multiply numerator and denominator by √3.","solution":"(27√3)/3 = 9√3.","id":"x023-09","subject":"maths","topic":"Rationalising denominators","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate (2 × 10^9) × (3 × 10²). Write the result as 6 × 10^k. Find k.","answer":11,"hint":"Multiply the coefficients and add powers of ten.","solution":"2 × 3 = 6 and 9 + 2 = 11, so k = 11.","id":"x024-09","subject":"maths","topic":"Calculating in standard form","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A length is 19 cm to the nearest centimetre. Give the lower bound in cm.","answer":18.5,"hint":"The rounding interval extends half a centimetre either side.","solution":"The lower bound is 19 − 0.5 = 18.5 cm; the upper bound is 19.5 cm and is excluded.","id":"x025-09","subject":"maths","topic":"Error intervals","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle has length 19 cm and width 13 cm, both to the nearest centimetre. Find the upper bound for its area in cm².","answer":263.25,"hint":"Use the upper bound for each positive length.","solution":"Upper area bound = 19.5 × 13.5 = 263.25 cm².","id":"x026-09","subject":"maths","topic":"Upper and lower bounds","group":"Number","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify 11x + 13x − 3x to ax. Find a.","answer":21,"hint":"Combine only the coefficients of x.","solution":"a = 11 + 13 − 3 = 21.","id":"x027-09","subject":"maths","topic":"Collecting like terms","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand 11(x + 10). What is the constant term?","answer":110,"hint":"Multiply both terms inside the bracket.","solution":"The expansion is 11x + 110.","id":"x028-09","subject":"maths","topic":"Expanding a single bracket","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand (x + 9)(x + 12). What is the coefficient of x?","answer":21,"hint":"Multiply every term in one bracket by every term in the other.","solution":"x² + 12x + 9x + 108 = x² + 21x + 108.","id":"x029-09","subject":"maths","topic":"Expanding double brackets","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise fully 18x + 54.","kind":"choice","options":["18(x + 6)","9(x + 3)","54(x + 2)","18(x + 3)"],"correct":3,"answer":null,"hint":"Take out the highest common factor of the two coefficients.","solution":"Both terms contain 18. Dividing gives x and 3, so the result is 18(x + 3).","id":"x030-09","subject":"maths","topic":"Factorising with a common factor","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise x² + 21x + 108.","kind":"choice","options":["(x − 9)(x − 12)","(x + 10)(x + 11)","(x − 9)(x + 12)","(x + 9)(x + 12)"],"correct":3,"answer":null,"hint":"Find two numbers whose product is the constant and whose sum is the x coefficient.","solution":"9 × 12 = 108 and 9 + 12 = 21.","id":"x031-09","subject":"maths","topic":"Factorising quadratics","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Find 2a² − b when a = 9 and b = 12.","answer":150,"hint":"Square a before multiplying by 2.","solution":"2 × 9² − 12 = 150.","id":"x032-09","subject":"maths","topic":"Substitution","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The formula is y = 11x − 9. If y = 101, find x.","answer":10,"hint":"Add the constant to y, then divide by the coefficient of x.","solution":"x = (y + 9)/11 = 110/11 = 10.","id":"x033-09","subject":"maths","topic":"Changing the subject","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the smallest integer satisfying 3x + 9 > 36.","answer":10,"hint":"Subtract the constant, divide by 3, then respect the strict inequality.","solution":"3x > 27, so x > 9. The smallest integer is 10.","id":"x034-09","subject":"maths","topic":"Linear inequalities","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Solve x + y = 28 and x − y = 10. Give x.","answer":19,"hint":"Add the two equations to eliminate y.","solution":"2x = 38, so x = 19.","id":"x035-09","subject":"maths","topic":"Simultaneous linear equations","group":"Algebra","tier":"Both","calculator":false,"marks":3},{"prompt":"The graphs y = x² and y = 81 meet. Give the positive x-coordinate.","answer":9,"hint":"Substitute to obtain x² equal to the constant.","solution":"x² = 81, so x = ±9. The positive value is 9.","id":"x036-09","subject":"maths","topic":"Simultaneous nonlinear equations","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"Write x² + 18x + 92 as (x + a)² + b. Find b.","answer":11,"hint":"Half the x coefficient gives a. Subtract a² from the constant.","solution":"a = 9. Subtract 81 from the constant 92 to get b = 11.","id":"x037-09","subject":"maths","topic":"Completing the square","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Use the quadratic formula to find the positive root of x² + x − 90 = 0.","answer":9,"hint":"Identify a, b and c. Use x = (−b ± √(b² − 4ac))/(2a).","solution":"a=1, b=1, c=−90. The discriminant is 1 + 360 = 361. The positive root is (−1 + 19)/2 = 9.","id":"x038-09","subject":"maths","topic":"Quadratic formula","group":"Algebra","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify (11x)/(22x²) for x ≠ 0, then evaluate at x = 9.","answer":0.0555555556,"hint":"Cancel the common numerical factor and one factor of x.","solution":"The expression simplifies to 1/(2x). At x = 9, it is 1/18.","id":"x039-09","subject":"maths","topic":"Algebraic fractions","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"The difference (k + 1)² − k² simplifies to 2k + 1. Use this identity to find the difference between the squares of 13 and 14.","answer":27,"hint":"Expand the square before cancelling k².","solution":"Expanding proves (k + 1)² − k² = 2k + 1. Set k = 13: the difference is 27.","id":"x040-09","subject":"maths","topic":"Algebraic proof","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x − 9. Find f(11).","answer":24,"hint":"Replace every x with the specified input.","solution":"f(11) = 3(11) − 9 = 24.","id":"x041-09","subject":"maths","topic":"Function notation","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"f(x) = 2x + 1 and g(x) = x². Find f(g(9)).","answer":163,"hint":"Apply the inside function first.","solution":"g(9) = 81; f(81) = 163.","id":"x042-09","subject":"maths","topic":"Composite functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x + 9. Find f⁻¹(36).","answer":9,"hint":"Undo the addition, then undo the multiplication.","solution":"f⁻¹(y) = (y − 9)/3. With y = 36, this gives 9.","id":"x043-09","subject":"maths","topic":"Inverse functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"x₀ = 9. Use x_(k+1) = (x_k + 4)/2 to calculate x₂.","answer":5.25,"hint":"Calculate x₁ first and substitute that new value again.","solution":"x₁ = (9 + 4)/2 = 6.5. Then x₂ = (6.5 + 4)/2 = 5.25.","id":"x044-09","subject":"maths","topic":"Iteration","group":"Algebra","tier":"Higher","calculator":true,"marks":2},{"prompt":"A geometric sequence starts at 10 and has common ratio 3. Find its fourth term.","answer":270,"hint":"Multiply by 3 three times after the first term.","solution":"The fourth term is 10 × 3³ = 270.","id":"x045-09","subject":"maths","topic":"Geometric sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The nth term is n² + 9n + 2. Find the fifth term.","answer":72,"hint":"Replace each occurrence of n (the position variable) with 5.","solution":"5² + 9 × 5 + 2 = 72.","id":"x046-09","subject":"maths","topic":"Quadratic sequences","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sequence begins 9, 10. Each new term is the sum of the preceding two. Find the fifth term.","answer":48,"hint":"Build the third and fourth terms before the fifth.","solution":"The terms are 9, 10, 19, 29, 48.","id":"x047-09","subject":"maths","topic":"Fibonacci-type sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the x-coordinate of the midpoint of (9, 2) and (29, 8).","answer":19,"hint":"Average the two x-coordinates.","solution":"(9 + 29)/2 = 19. The full midpoint is (19, 5).","id":"x048-09","subject":"maths","topic":"Midpoints","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the distance between (0, 0) and (27, 36).","answer":45,"hint":"Use the horizontal and vertical differences in Pythagoras.","solution":"√(27² + 36²) = 45 units.","id":"x049-09","subject":"maths","topic":"Distance between coordinates","group":"Coordinate geometry","tier":"Both","calculator":true,"marks":3},{"prompt":"A line is parallel to y = 10x − 4 and passes through (0, 9). Give its gradient.","answer":10,"hint":"Parallel non-vertical lines have equal gradients.","solution":"The given line has gradient 10, so the parallel line does too.","id":"x050-09","subject":"maths","topic":"Parallel lines","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the gradient of a line perpendicular to y = 10x + 2. Give a fraction or decimal.","answer":-0.1,"hint":"For non-zero gradients, the perpendicular gradient is the negative reciprocal.","solution":"The negative reciprocal of 10 is −1/10.","id":"x051-09","subject":"maths","topic":"Perpendicular lines","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A line passes through (1, 19) and (3, 37). Write it as y = mx + c. Find c.","answer":10,"hint":"Find the gradient from the two points, then substitute a point.","solution":"m = (37 − 19)/2 = 9. Then c = 19 − 9 = 10.","id":"x052-09","subject":"maths","topic":"Equation of a line through points","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"A pack of 12 notebooks costs £120. Find the price per notebook in pounds.","answer":10,"hint":"Divide cost by number of items.","solution":"£120 ÷ 12 = £10 per notebook.","id":"x053-09","subject":"maths","topic":"Best buys and unit pricing","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"£1 exchanges for €1.20. How many euros are exchanged for £225?","answer":270,"hint":"Multiply the pound amount by the euros-per-pound rate.","solution":"225 × 1.20 = €270.","id":"x054-09","subject":"maths","topic":"Currency conversion","group":"Proportion and rates","tier":"Both","calculator":true,"marks":2},{"prompt":"A recipe for 4 people uses 260 g of rice. How many grams are needed for 6 people?","answer":390.0,"hint":"Scale every ingredient by 6/4.","solution":"260 × 6/4 = 390.0 g.","id":"x055-09","subject":"maths","topic":"Scaling recipes","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"A map has scale 1:50 000. Two places are 9 cm apart on the map. Find their real distance in kilometres.","answer":4.5,"hint":"Convert the scaled centimetres into kilometres using 100 000 cm = 1 km.","solution":"9 × 50 000 = 450000 cm = 4.5 km.","id":"x056-09","subject":"maths","topic":"Map scales","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is directly proportional to x. When x = 3, y = 30. Find y when x = 8.","answer":80,"hint":"Find k in y = kx.","solution":"k = 30/3 = 10; hence y = 10 × 8 = 80.","id":"x057-09","subject":"maths","topic":"Direct proportion","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is inversely proportional to x. When x = 2, y = 54. Find y when x = 3.","answer":36,"hint":"The product xy stays constant.","solution":"k = 2 × 54 = 108. Thus y = 108/3 = 36.","id":"x058-09","subject":"maths","topic":"Inverse proportion","group":"Proportion and rates","tier":"Higher","calculator":false,"marks":2},{"prompt":"£900 earns 5% compound interest each year. Find the balance after 2 years in pounds.","answer":992.25,"hint":"Multiply by 1.05 for each year.","solution":"£900 × 1.05² = £992.25.","id":"x059-09","subject":"maths","topic":"Compound interest","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A bicycle worth £2250 loses 20% of its value each year. Find its value after 2 years in pounds.","answer":1440,"hint":"Retain 80% each year, using the multiplier 0.8 twice.","solution":"£2250 × 0.8² = £1440.","id":"x060-09","subject":"maths","topic":"Depreciation","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A culture begins with 1800 cells and increases by 10% each hour. Find the modelled count after 2 hours.","answer":2178,"hint":"Use the growth multiplier 1.1 twice.","solution":"1800 × 1.1² = 2178 cells.","id":"x061-09","subject":"maths","topic":"Repeated percentage growth","group":"Finance","tier":"Both","calculator":true,"marks":2},{"prompt":"A block has mass 1080 g and volume 108 cm³. Find its density in g/cm³.","answer":10,"hint":"Density = mass ÷ volume.","solution":"1080 ÷ 108 = 10 g/cm³.","id":"x062-09","subject":"maths","topic":"Density","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A force of 1485 N acts on an area of 27 m². Find pressure in N/m².","answer":55,"hint":"Pressure = force ÷ area.","solution":"1485 ÷ 27 = 55 N/m².","id":"x063-09","subject":"maths","topic":"Pressure","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"Convert 10 m² into cm².","answer":100000,"hint":"Square the linear conversion: 1 m = 100 cm.","solution":"1 m² = 100² = 10 000 cm². Therefore 10 m² = 100000 cm².","id":"x064-09","subject":"maths","topic":"Metric area conversions","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A journey starts at 09:19 and ends at 11:45. Find its duration in minutes.","answer":146,"hint":"Count the full hours and the remaining minutes.","solution":"From 09:19 to 11:19 is 120 minutes, then another 26. Total = 146 minutes.","id":"x065-09","subject":"maths","topic":"Time calculations","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle is 17 cm by 13 cm. A 2 cm by 2 cm square is cut from one corner. Find the perimeter of the remaining L-shape in cm.","answer":60,"hint":"The two removed edge lengths are replaced by two equal inner edge lengths.","solution":"The perimeter stays equal to the original rectangle: 2(17 + 13) = 60 cm.","id":"x066-09","subject":"maths","topic":"Perimeter of compound shapes","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 10 cm. Express its circumference as kπ cm. Find k.","answer":20,"hint":"Circumference is 2πr.","solution":"2π × 10 = 20π cm.","id":"x067-09","subject":"maths","topic":"Circle circumference","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 11 cm. Its area is kπ cm². Find k.","answer":121,"hint":"Square the radius and multiply by π.","solution":"Area = π × 11² = 121π cm².","id":"x068-09","subject":"maths","topic":"Area of circles","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A semicircle has radius 11 cm. Its perimeter is πr + d. Find the straight-edge length d in cm.","answer":22,"hint":"The straight edge is the diameter, not the radius.","solution":"d = 2r = 2 × 11 = 22 cm. The complete perimeter is 11π + 22 cm.","id":"x069-09","subject":"maths","topic":"Semicircle perimeter","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 60° and radius 27 cm. Its arc length is kπ cm. Find k.","answer":9,"hint":"Take 60/360 of the circumference.","solution":"(60/360) × 2π × 27 = 9π cm.","id":"x070-09","subject":"maths","topic":"Arc length","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 90° and radius 18 cm. Its area is kπ cm². Find k.","answer":81,"hint":"Take one quarter of the full circle area.","solution":"(90/360) × π × 18² = 81π cm².","id":"x071-09","subject":"maths","topic":"Sector area","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A triangular prism has triangular cross-section base 11 cm, height 6 cm, and prism length 10 cm. Find its volume in cm³.","answer":330,"hint":"Find the triangle area, then multiply by the prism length.","solution":"Cross-section = ½ × 11 × 6 = 33 cm². Volume = 330 cm³.","id":"x072-09","subject":"maths","topic":"Volume of prisms","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A cylinder has radius 10 cm and height 5 cm. Its volume is kπ cm³. Find k.","answer":500,"hint":"Multiply the circular base area by the height.","solution":"πr²h = π × 10² × 5 = 500π cm³.","id":"x073-09","subject":"maths","topic":"Volume of cylinders","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A cone has radius 10 cm and perpendicular height 9 cm. Its volume is kπ cm³. Find k.","answer":300,"hint":"A cone has one third of the corresponding cylinder volume.","solution":"V = πr²h/3 = π × 10² × 9/3 = 300π cm³.","id":"x074-09","subject":"maths","topic":"Volume of cones","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sphere has radius 27 cm. Its volume is kπ cm³. Find k.","answer":26244,"hint":"Use V = 4πr³/3.","solution":"(4/3) × 27³ = 26244, so V = 26244π cm³.","id":"x075-09","subject":"maths","topic":"Volume of spheres","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A cuboid measures 10 cm by 3 cm by 4 cm. Find its total surface area in cm².","answer":164,"hint":"There are two faces of each of the three different rectangular areas.","solution":"2[3(10) + 4(10) + 3×4] = 164 cm².","id":"x076-09","subject":"maths","topic":"Surface area of cuboids","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A closed cylinder has radius 10 cm and height 4 cm. Its total surface area is kπ cm². Find k.","answer":280,"hint":"Include two circular ends and the curved surface.","solution":"2r² + 2rh = 2(10²) + 2(10)(4) = 280.","id":"x077-09","subject":"maths","topic":"Cylinder surface area","group":"Geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"Two similar shapes have length scale factor 3 from small to large. A small side is 11 cm. Find the matching large side.","answer":33,"hint":"Multiply corresponding lengths by the length scale factor.","solution":"11 × 3 = 33 cm.","id":"x078-09","subject":"maths","topic":"Similarity of lengths","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Two similar shapes have length scale factor 2. The smaller area is 12 cm². Find the larger area.","answer":48,"hint":"Square the length scale factor for areas.","solution":"Area factor = 2² = 4. Larger area = 12 × 4 = 48 cm².","id":"x079-09","subject":"maths","topic":"Similarity of areas","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"Two similar solids have length scale factor 3. The smaller volume is 10 cm³. Find the larger volume.","answer":270,"hint":"Cube the length scale factor for volumes.","solution":"Volume factor = 3³ = 27. Larger volume = 270 cm³.","id":"x080-09","subject":"maths","topic":"Similarity of volumes","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A triangle has two angles 49° and 69°. Find the third angle in degrees.","answer":62,"hint":"Interior angles in a triangle total 180°.","solution":"180 − 49 − 69 = 62°.","id":"x081-09","subject":"maths","topic":"Triangle angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A regular polygon has 13 sides. Find its exterior angle in degrees, to 3 decimal places if needed.","answer":27.692,"hint":"The exterior angles total 360°.","solution":"Each exterior angle is 360/13 = 27.692°.","id":"x082-09","subject":"maths","topic":"Exterior angles of polygons","group":"Geometry","tier":"Both","calculator":true,"marks":2},{"prompt":"A transversal crosses two parallel lines. One of a pair of co-interior angles is 87°. Find the other angle in degrees.","answer":93,"hint":"Co-interior angles on parallel lines sum to 180°.","solution":"180 − 87 = 93°.","id":"x083-09","subject":"maths","topic":"Angles in parallel lines","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the sum of the interior angles of a polygon with 12 sides.","answer":1800,"hint":"Use (number of sides − 2) × 180°.","solution":"(12 − 2) × 180 = 1800°.","id":"x084-09","subject":"maths","topic":"Polygon interior-angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"The bearing of B from A is 065°. Find the bearing of A from B as a number of degrees.","answer":245,"hint":"A reverse bearing differs by 180°.","solution":"65 + 180 = 245°.","id":"x085-09","subject":"maths","topic":"Three-figure bearings","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A right-angled triangle has hypotenuse 22 cm and an angle of 30°. Find the side opposite that angle in cm.","answer":11,"hint":"Use sin(angle) = opposite/hypotenuse.","solution":"Opposite = 22 × sin30° = 11 cm.","id":"x086-09","subject":"maths","topic":"Right-angle trigonometry","group":"Trigonometry","tier":"Both","calculator":true,"marks":3},{"prompt":"In a triangle, side a = 11 cm is opposite 30°, and side b is opposite 90°. Find b in cm.","answer":22,"hint":"Use a/sin A = b/sin B.","solution":"b = 11 × sin90°/sin30° = 22 cm.","id":"x087-09","subject":"maths","topic":"Sine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides of a triangle are 11 cm each, with included angle 60°. Find the opposite side in cm.","answer":11,"hint":"Use c² = a² + b² − 2ab cos C.","solution":"c² = 2(11²) − 2(11²)cos60° = 121, so c = 11 cm.","id":"x088-09","subject":"maths","topic":"Cosine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides are 11 cm and 8 cm, with included angle 30°. Find the triangle area in cm².","answer":22,"hint":"Use area = ½ab sin C.","solution":"½ × 11 × 8 × sin30° = 22 cm².","id":"x089-09","subject":"maths","topic":"Triangle area using sine","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"An angle at the circumference is 29°. The central angle subtended by the same arc is less than 180°. Find it.","answer":58,"hint":"The angle at the centre is twice the angle at the circumference on the same arc.","solution":"2 × 29 = 58°.","id":"x090-09","subject":"maths","topic":"Angles at the centre","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"One angle of a cyclic quadrilateral is 108°. Find its opposite angle.","answer":72,"hint":"Opposite angles in a cyclic quadrilateral total 180°.","solution":"180 − 108 = 72°.","id":"x091-09","subject":"maths","topic":"Cyclic quadrilaterals","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"A tangent and chord form an angle of 43°. Find the angle subtended by that chord in the alternate segment.","answer":43,"hint":"The tangent-chord angle equals the angle in the alternate segment.","solution":"By the alternate segment theorem, the required angle is 43°.","id":"x092-09","subject":"maths","topic":"Alternate segment theorem","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"Vectors a = (9, 3) and b = (11, −1). Find the x-component of a + b.","answer":20,"hint":"Add corresponding components.","solution":"a + b = (20, 2), so the x-component is 20.","id":"x093-09","subject":"maths","topic":"Adding vectors","group":"Vectors","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the magnitude of the vector (27, 36).","answer":45,"hint":"Use Pythagoras on the two components.","solution":"√(27² + 36²) = 45.","id":"x094-09","subject":"maths","topic":"Vector magnitude","group":"Vectors","tier":"Higher","calculator":true,"marks":2},{"prompt":"Rotate (9, 11) by 90° anticlockwise about the origin. Find the new x-coordinate.","answer":-11,"hint":"The rule for 90° anticlockwise is (x,y) → (−y,x).","solution":"The image is (−11, 9), so its x-coordinate is −11.","id":"x095-09","subject":"maths","topic":"Rotations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Enlarge (9, 2) by scale factor 3 about the origin. Find the new x-coordinate.","answer":27,"hint":"Multiply both coordinates by the scale factor.","solution":"The image is (27, 6).","id":"x096-09","subject":"maths","topic":"Enlargements","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Translate (9, 4) by the vector (−3, 2). Find the new x-coordinate.","answer":6,"hint":"Add the x-component of the vector to the x-coordinate.","solution":"The image is (6, 6).","id":"x097-09","subject":"maths","topic":"Translations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Reflect (9, 12) in the line y = x. Find the new x-coordinate.","answer":12,"hint":"Reflection in y = x swaps the coordinates.","solution":"The image is (12, 9).","id":"x098-09","subject":"maths","topic":"Reflections","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Points must be exactly 11 cm from a fixed point P. What is their locus?","kind":"choice","options":["A circle centred at P with diameter 11 cm","A straight line through P","A perpendicular bisector through P","A circle centred at P with radius 11 cm"],"correct":3,"answer":null,"hint":"A fixed distance from one point defines a circle.","solution":"All points on a circle of radius 11 cm are exactly 11 cm from its centre P.","id":"x099-09","subject":"maths","topic":"Loci and constructions","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the median of 16, 9, 12, 18, 10.","answer":12,"hint":"Order the values, then choose the middle one.","solution":"The ordered list is 9, 10, 12, 16, 18. Its middle value is 12.","id":"x100-09","subject":"maths","topic":"Finding the median","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the mode of 9, 11, 11, 13, 11, 15.","answer":11,"hint":"Look for the value occurring most frequently.","solution":"11 occurs three times; every other value occurs once.","id":"x101-09","subject":"maths","topic":"Finding the mode","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the range of −9, 2, 13, 0.","answer":22,"hint":"Subtract the minimum from the maximum.","solution":"13 − (−9) = 22.","id":"x102-09","subject":"maths","topic":"Finding the range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A data set has lower quartile 12 and upper quartile 43. Find its interquartile range.","answer":31,"hint":"IQR = upper quartile − lower quartile.","solution":"43 − 12 = 31.","id":"x103-09","subject":"maths","topic":"Interquartile range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A grouped table has 2 values in 0 ≤ x < 10 and 11 values in 10 ≤ x < 20. Estimate the mean, to 3 decimal places.","answer":13.462,"hint":"Use class midpoints 5 and 15, multiply by frequencies, then divide by total frequency.","solution":"Estimated total = 2×5 + 11×15 = 175. Divide by 13 to get 13.462.","id":"x104-09","subject":"maths","topic":"Estimated mean from grouped data","group":"Statistics","tier":"Both","calculator":true,"marks":3},{"prompt":"A histogram class has width 5 and frequency 55. Find its frequency density.","answer":11,"hint":"Frequency density = frequency ÷ class width.","solution":"55 ÷ 5 = 11.","id":"x105-09","subject":"maths","topic":"Frequency density","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"Class frequencies, in ascending order, are 9, 11, 13, 15. Find the cumulative frequency at the end of the third class.","answer":33,"hint":"Add all frequencies up to and including the third class.","solution":"9 + 11 + 13 = 33.","id":"x106-09","subject":"maths","topic":"Cumulative frequency","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A box plot has minimum 9, lower quartile 12, median 15, upper quartile 18, maximum 24. Read off its median.","answer":15,"hint":"The median is the line inside the box.","solution":"The median line is at 15. The ends of the box are the quartiles.","id":"x107-09","subject":"maths","topic":"Box plots","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A school has 600 pupils; 270 are in a chosen group. In a proportional sample of 40 pupils, how many should come from that group?","answer":18,"hint":"Multiply the sample size by the group proportion.","solution":"40 × 270/600 = 18 pupils.","id":"x108-09","subject":"maths","topic":"Stratified sampling","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"An experiment succeeds 12 times out of 20 trials. Find the relative frequency as a fraction or decimal.","answer":0.6,"hint":"Divide the number of successes by the number of trials.","solution":"Relative frequency = 12/20 = 0.6.","id":"x109-09","subject":"maths","topic":"Relative frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"An event has probability 0.3. It is tested 180 times. Find its expected frequency.","answer":54,"hint":"Multiply probability by number of trials.","solution":"0.3 × 180 = 54. This is an expectation, not a guarantee.","id":"x110-09","subject":"maths","topic":"Expected frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Two independent events have probabilities 1/2 and 9/12. Find the probability that both occur.","answer":0.375,"hint":"Multiply the probabilities of independent events.","solution":"1/2 × 9/12 = 9/24.","id":"x111-09","subject":"maths","topic":"Independent events","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A bag has 11 red counters and 3 blue counters. Two counters are drawn without replacement. Find P(both red), to 3 decimal places.","answer":0.604,"hint":"The second draw has one fewer red counter and one fewer counter altogether.","solution":"P = (11/14) × (10/13) = 0.604.","id":"x112-09","subject":"maths","topic":"Sampling without replacement","group":"Probability","tier":"Higher","calculator":true,"marks":3},{"prompt":"Of 14 club members who play tennis, 9 also swim. A member is chosen from the tennis players only. Find P(swims), as a fraction or decimal.","answer":0.6428571429,"hint":"Use the restricted tennis group as the denominator.","solution":"Given that the person plays tennis, P(swims) = 9/14.","id":"x113-09","subject":"maths","topic":"Conditional probability","group":"Probability","tier":"Higher","calculator":false,"marks":2},{"prompt":"Set A contains 35 people including 11 in A ∩ B. How many are in A only?","answer":24,"hint":"Subtract the intersection from the total in A.","solution":"35 − 11 = 24 people.","id":"x114-09","subject":"maths","topic":"Venn diagram regions","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"n(A) = 19, n(B) = 21, and n(A ∩ B) = 12. Find n(A ∪ B).","answer":28,"hint":"Add the two set sizes and subtract the overlap once.","solution":"19 + 21 − 12 = 28.","id":"x115-09","subject":"maths","topic":"Set union","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A fair coin is tossed, then a fair 12-sided die numbered 1 to 12 is rolled. Find P(heads and a 1).","answer":0.0416666667,"hint":"Multiply the branch probabilities along the path.","solution":"(1/2) × (1/12) = 1/24.","id":"x116-09","subject":"maths","topic":"Tree diagrams","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Plot the listed points for y = x³ + 4. Use x = -2, -1, 0, 1, 2. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[-2,-4],[-1,3],[0,4],[1,5],[2,12]],"curve":"quadratic","range":[-3,3,-14,14],"expression":"y = x³ + 4","hint":"Cube each x, preserving its sign, then add the constant.","solution":"The coordinates are (-2, -4), (-1, 3), (0, 4), (1, 5), (2, 12). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x117-09","subject":"maths","topic":"Cubic graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 12/x + 8 for 1 ≤ x ≤ 6. Use x = 1, 2, 3, 4, 6. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[1,20.0],[2,14.0],[3,12.0],[4,11.0],[6,10.0]],"curve":"quadratic","range":[0,7,0,23],"expression":"y = 12/x + 8 for 1 ≤ x ≤ 6","hint":"Divide 12 by x, then add the constant; x = 0 is not allowed.","solution":"The coordinates are (1, 20.0), (2, 14.0), (3, 12.0), (4, 11.0), (6, 10.0). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x118-09","subject":"maths","topic":"Reciprocal graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 2^x + 8. Use x = 0, 1, 2, 3. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[0,9],[1,10],[2,12],[3,16]],"curve":"quadratic","range":[-1,4,0,18],"expression":"y = 2^x + 8","hint":"Calculate the power of 2 first, then add the constant.","solution":"The coordinates are (0, 9), (1, 10), (2, 12), (3, 16). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x119-09","subject":"maths","topic":"Exponential graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"The graph y = x² is translated upward by 11 units. Find the new y-coordinate of its turning point.","answer":11,"hint":"An upward translation adds the same amount to every y-coordinate.","solution":"The old turning point is (0, 0); the new one is (0, 11).","id":"x120-09","subject":"maths","topic":"Translating graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A straight segment on a distance-time graph runs from (0 hours, 0 km) to (2 hours, 108 km). Find the speed in km/h.","answer":54,"hint":"Speed is the gradient: distance change divided by time change.","solution":"108 km ÷ 2 h = 54 km/h.","id":"x121-09","subject":"maths","topic":"Distance-time graphs","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A velocity-time graph rises in a straight line from 0 m/s to 45 m/s in 5 seconds. Find acceleration in m/s².","answer":9,"hint":"Acceleration is change in velocity divided by time.","solution":"(45 − 0)/5 = 9 m/s².","id":"x122-09","subject":"maths","topic":"Velocity-time gradients","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A tangent to a curve passes through (1, 9) and (3, 29). Estimate the gradient of the curve at the contact point.","answer":10,"hint":"Use the gradient of the tangent, not a chord through two curve points.","solution":"(29 − 9)/(3 − 1) = 10.","id":"x123-09","subject":"maths","topic":"Tangents and rates of change","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A velocity-time graph forms a triangle with base 6 seconds and maximum velocity 18 m/s. Find the displacement in metres.","answer":54,"hint":"Displacement is the signed area under a velocity-time graph.","solution":"Area = ½ × 6 × 18 = 54 m.","id":"x124-09","subject":"maths","topic":"Area under velocity-time graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"The lines y = x + 9 and y = 3x intersect. Find the x-coordinate of the intersection.","answer":4.5,"hint":"At the intersection, both expressions for y are equal.","solution":"x + 9 = 3x, so 2x = 9 and x = 4.5.","id":"x125-09","subject":"maths","topic":"Graphical simultaneous equations","group":"Graphs","tier":"Both","calculator":false,"marks":3},{"prompt":"Which point satisfies both x > 9 and y < 3?","kind":"choice","options":["(9, 2)","(10, 4)","(8, 0)","(10, 2)"],"correct":3,"answer":null,"hint":"Test both strict inequalities for each coordinate pair.","solution":"Only (10, 2) has x strictly greater than 9 and y strictly less than 3.","id":"x126-09","subject":"maths","topic":"Regions satisfying inequalities","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate 13 + 12 × 4.","answer":61,"hint":"Do multiplication before addition.","solution":"12 × 4 = 48; then add 13 to get 61.","id":"x001-10","subject":"maths","topic":"Order of operations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"The temperature is −12°C. It falls by 14°C. What is the new temperature in °C?","answer":-26,"hint":"A fall makes the number more negative.","solution":"−12 − 14 = −26°C.","id":"x002-10","subject":"maths","topic":"Calculating with negatives","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the value of the hundreds digit in 1210?","answer":200,"hint":"Identify the digit three places from the right.","solution":"The hundreds digit is 2, so its value is 2 × 100 = 200.","id":"x003-10","subject":"maths","topic":"Place value","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 12.376 to two decimal places.","answer":12.38,"hint":"Look at the third decimal digit.","solution":"The third digit is 6, so round the hundredths up: 12.38.","id":"x004-10","subject":"maths","topic":"Rounding decimal places","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Round 4404 to two significant figures.","answer":4400,"hint":"Count significant digits from the first non-zero digit.","solution":"The first two significant figures are in the thousands and hundreds columns. Rounding 4404 to the nearest 100 gives 4400.","id":"x005-10","subject":"maths","topic":"Significant figures","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Estimate 12.9 × 19.8 by rounding each number to the nearest whole number first.","answer":260,"hint":"Follow the requested rounding method for both numbers.","solution":"12.9 rounds to 13; 19.8 rounds to 20. The estimate is 260.","id":"x006-10","subject":"maths","topic":"Estimating calculations","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"How many positive factors does 2048 have?","answer":12,"hint":"For a power of 2, list 2⁰ up to the highest power.","solution":"2048 = 2^11. Its factors are 2⁰ through 2^11, giving 12 factors.","id":"x007-10","subject":"maths","topic":"Factors","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"What is the smallest multiple of 13 that is strictly greater than 130?","answer":143,"hint":"The number given is already the tenth multiple.","solution":"The next multiple is 11 × 13 = 143.","id":"x008-10","subject":"maths","topic":"Multiples","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Which number in this list is prime? Set 10.","kind":"choice","options":["72","108","43","52"],"correct":2,"answer":null,"hint":"A prime has exactly two positive factors: 1 and itself.","solution":"43 has no positive factors except 1 and itself. The other numbers have explicit factors 4, 6 or 9.","id":"x009-10","subject":"maths","topic":"Prime numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"In the prime factorisation of 9216, what is the exponent of 2?","answer":10,"hint":"Keep dividing by 2 until the remaining number is odd.","solution":"9216 = 2^10 × 3², so the exponent is 10.","id":"x010-10","subject":"maths","topic":"Prime factorisation","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the highest common factor of 120 and 180.","answer":60,"hint":"Look for the largest factor that divides both numbers.","solution":"120 = 2 × 60 and 180 = 3 × 60. Since 2 and 3 are coprime, the HCF is 60.","id":"x011-10","subject":"maths","topic":"Highest common factor","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the lowest common multiple of 40 and 60.","answer":120,"hint":"Find the HCF first, or list the multiples.","solution":"The HCF is 20. LCM = (40 × 60) ÷ 20 = 120.","id":"x012-10","subject":"maths","topic":"Lowest common multiple","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 10/12 + 1/8. Give a fraction or decimal.","answer":0.9583333333,"hint":"Use a common denominator of 24.","solution":"10/12 = 20/24 and 1/8 = 3/24. The sum is 23/24.","id":"x013-10","subject":"maths","topic":"Adding fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 10/11 × 3/5. Give a fraction or decimal.","answer":0.5454545455,"hint":"Multiply numerators and denominators.","solution":"(10 × 3)/(11 × 5) = 30/55. Simplify if possible.","id":"x014-10","subject":"maths","topic":"Multiplying fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Calculate 10/12 ÷ 5/6. Give a fraction or decimal.","answer":1.0,"hint":"Multiply by the reciprocal of 5/6.","solution":"10/12 × 6/5 = 60/60 = 10/10.","id":"x015-10","subject":"maths","topic":"Dividing fractions","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 10 3/4 as a decimal.","answer":10.75,"hint":"The fraction part is three quarters, or 0.75.","solution":"10 + 0.75 = 10.75.","id":"x016-10","subject":"maths","topic":"Mixed numbers","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A club has 240 members. Three eighths cycle to the club. How many members cycle?","answer":90,"hint":"Divide by 8 to find one eighth, then multiply by 3.","solution":"240 ÷ 8 × 3 = 90.","id":"x017-10","subject":"maths","topic":"Fractions of quantities","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Write 0.202020… (the block 20 repeats) as a fraction or decimal.","answer":0.202020202,"hint":"For a two-digit repeating block, compare 100x with x.","solution":"If x = 0.2020…, then 100x − x = 20; hence x = 20/99.","id":"x018-10","subject":"maths","topic":"Recurring decimals","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Simplify 3^11 × 3^13 to 3^k. Find k.","answer":24,"hint":"Add exponents when multiplying powers of the same base.","solution":"k = 11 + 13 = 24.","id":"x019-10","subject":"maths","topic":"Index laws","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"Evaluate 11^−2. Give a fraction or decimal.","answer":0.0082644628,"hint":"A negative exponent gives the reciprocal of the positive power.","solution":"11^−2 = 1/(11²) = 1/121.","id":"x020-10","subject":"maths","topic":"Negative indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Evaluate 1728^(2/3).","answer":144,"hint":"Take the cube root, then square the result.","solution":"The cube root of 1728 is 12; its square is 144.","id":"x021-10","subject":"maths","topic":"Fractional indices","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write √242 in the form a√2. Find a.","answer":11,"hint":"Look for a square factor inside the root.","solution":"√(121 × 2) = 11√2, so a = 11.","id":"x022-10","subject":"maths","topic":"Simplifying surds","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Write 30/√3 in the form a√3. Find a.","answer":10,"hint":"Multiply numerator and denominator by √3.","solution":"(30√3)/3 = 10√3.","id":"x023-10","subject":"maths","topic":"Rationalising denominators","group":"Number","tier":"Higher","calculator":false,"marks":2},{"prompt":"Calculate (2 × 10^10) × (3 × 10²). Write the result as 6 × 10^k. Find k.","answer":12,"hint":"Multiply the coefficients and add powers of ten.","solution":"2 × 3 = 6 and 10 + 2 = 12, so k = 12.","id":"x024-10","subject":"maths","topic":"Calculating in standard form","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A length is 20 cm to the nearest centimetre. Give the lower bound in cm.","answer":19.5,"hint":"The rounding interval extends half a centimetre either side.","solution":"The lower bound is 20 − 0.5 = 19.5 cm; the upper bound is 20.5 cm and is excluded.","id":"x025-10","subject":"maths","topic":"Error intervals","group":"Number","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle has length 20 cm and width 14 cm, both to the nearest centimetre. Find the upper bound for its area in cm².","answer":297.25,"hint":"Use the upper bound for each positive length.","solution":"Upper area bound = 20.5 × 14.5 = 297.25 cm².","id":"x026-10","subject":"maths","topic":"Upper and lower bounds","group":"Number","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify 12x + 14x − 3x to ax. Find a.","answer":23,"hint":"Combine only the coefficients of x.","solution":"a = 12 + 14 − 3 = 23.","id":"x027-10","subject":"maths","topic":"Collecting like terms","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand 12(x + 11). What is the constant term?","answer":132,"hint":"Multiply both terms inside the bracket.","solution":"The expansion is 12x + 132.","id":"x028-10","subject":"maths","topic":"Expanding a single bracket","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Expand (x + 10)(x + 13). What is the coefficient of x?","answer":23,"hint":"Multiply every term in one bracket by every term in the other.","solution":"x² + 13x + 10x + 130 = x² + 23x + 130.","id":"x029-10","subject":"maths","topic":"Expanding double brackets","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise fully 20x + 60.","kind":"choice","options":["10(x + 3)","60(x + 2)","20(x + 3)","20(x + 6)"],"correct":2,"answer":null,"hint":"Take out the highest common factor of the two coefficients.","solution":"Both terms contain 20. Dividing gives x and 3, so the result is 20(x + 3).","id":"x030-10","subject":"maths","topic":"Factorising with a common factor","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Factorise x² + 23x + 130.","kind":"choice","options":["(x + 11)(x + 12)","(x − 10)(x + 13)","(x + 10)(x + 13)","(x − 10)(x − 13)"],"correct":2,"answer":null,"hint":"Find two numbers whose product is the constant and whose sum is the x coefficient.","solution":"10 × 13 = 130 and 10 + 13 = 23.","id":"x031-10","subject":"maths","topic":"Factorising quadratics","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Find 2a² − b when a = 10 and b = 13.","answer":187,"hint":"Square a before multiplying by 2.","solution":"2 × 10² − 13 = 187.","id":"x032-10","subject":"maths","topic":"Substitution","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The formula is y = 12x − 10. If y = 122, find x.","answer":11,"hint":"Add the constant to y, then divide by the coefficient of x.","solution":"x = (y + 10)/12 = 132/12 = 11.","id":"x033-10","subject":"maths","topic":"Changing the subject","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the smallest integer satisfying 3x + 10 > 40.","answer":11,"hint":"Subtract the constant, divide by 3, then respect the strict inequality.","solution":"3x > 30, so x > 10. The smallest integer is 11.","id":"x034-10","subject":"maths","topic":"Linear inequalities","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Solve x + y = 31 and x − y = 11. Give x.","answer":21,"hint":"Add the two equations to eliminate y.","solution":"2x = 42, so x = 21.","id":"x035-10","subject":"maths","topic":"Simultaneous linear equations","group":"Algebra","tier":"Both","calculator":false,"marks":3},{"prompt":"The graphs y = x² and y = 100 meet. Give the positive x-coordinate.","answer":10,"hint":"Substitute to obtain x² equal to the constant.","solution":"x² = 100, so x = ±10. The positive value is 10.","id":"x036-10","subject":"maths","topic":"Simultaneous nonlinear equations","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"Write x² + 20x + 112 as (x + a)² + b. Find b.","answer":12,"hint":"Half the x coefficient gives a. Subtract a² from the constant.","solution":"a = 10. Subtract 100 from the constant 112 to get b = 12.","id":"x037-10","subject":"maths","topic":"Completing the square","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"Use the quadratic formula to find the positive root of x² + x − 110 = 0.","answer":10,"hint":"Identify a, b and c. Use x = (−b ± √(b² − 4ac))/(2a).","solution":"a=1, b=1, c=−110. The discriminant is 1 + 440 = 441. The positive root is (−1 + 21)/2 = 10.","id":"x038-10","subject":"maths","topic":"Quadratic formula","group":"Algebra","tier":"Higher","calculator":true,"marks":3},{"prompt":"Simplify (12x)/(24x²) for x ≠ 0, then evaluate at x = 10.","answer":0.05,"hint":"Cancel the common numerical factor and one factor of x.","solution":"The expression simplifies to 1/(2x). At x = 10, it is 1/20.","id":"x039-10","subject":"maths","topic":"Algebraic fractions","group":"Algebra","tier":"Higher","calculator":false,"marks":3},{"prompt":"The difference (k + 1)² − k² simplifies to 2k + 1. Use this identity to find the difference between the squares of 14 and 15.","answer":29,"hint":"Expand the square before cancelling k².","solution":"Expanding proves (k + 1)² − k² = 2k + 1. Set k = 14: the difference is 29.","id":"x040-10","subject":"maths","topic":"Algebraic proof","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x − 10. Find f(12).","answer":26,"hint":"Replace every x with the specified input.","solution":"f(12) = 3(12) − 10 = 26.","id":"x041-10","subject":"maths","topic":"Function notation","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"f(x) = 2x + 1 and g(x) = x². Find f(g(10)).","answer":201,"hint":"Apply the inside function first.","solution":"g(10) = 100; f(100) = 201.","id":"x042-10","subject":"maths","topic":"Composite functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"f(x) = 3x + 10. Find f⁻¹(40).","answer":10,"hint":"Undo the addition, then undo the multiplication.","solution":"f⁻¹(y) = (y − 10)/3. With y = 40, this gives 10.","id":"x043-10","subject":"maths","topic":"Inverse functions","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"x₀ = 10. Use x_(k+1) = (x_k + 4)/2 to calculate x₂.","answer":5.5,"hint":"Calculate x₁ first and substitute that new value again.","solution":"x₁ = (10 + 4)/2 = 7.0. Then x₂ = (7.0 + 4)/2 = 5.5.","id":"x044-10","subject":"maths","topic":"Iteration","group":"Algebra","tier":"Higher","calculator":true,"marks":2},{"prompt":"A geometric sequence starts at 11 and has common ratio 3. Find its fourth term.","answer":297,"hint":"Multiply by 3 three times after the first term.","solution":"The fourth term is 11 × 3³ = 297.","id":"x045-10","subject":"maths","topic":"Geometric sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"The nth term is n² + 10n + 2. Find the fifth term.","answer":77,"hint":"Replace each occurrence of n (the position variable) with 5.","solution":"5² + 10 × 5 + 2 = 77.","id":"x046-10","subject":"maths","topic":"Quadratic sequences","group":"Algebra","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sequence begins 10, 11. Each new term is the sum of the preceding two. Find the fifth term.","answer":53,"hint":"Build the third and fourth terms before the fifth.","solution":"The terms are 10, 11, 21, 32, 53.","id":"x047-10","subject":"maths","topic":"Fibonacci-type sequences","group":"Algebra","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the x-coordinate of the midpoint of (10, 2) and (32, 8).","answer":21,"hint":"Average the two x-coordinates.","solution":"(10 + 32)/2 = 21. The full midpoint is (21, 5).","id":"x048-10","subject":"maths","topic":"Midpoints","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the distance between (0, 0) and (30, 40).","answer":50,"hint":"Use the horizontal and vertical differences in Pythagoras.","solution":"√(30² + 40²) = 50 units.","id":"x049-10","subject":"maths","topic":"Distance between coordinates","group":"Coordinate geometry","tier":"Both","calculator":true,"marks":3},{"prompt":"A line is parallel to y = 11x − 4 and passes through (0, 10). Give its gradient.","answer":11,"hint":"Parallel non-vertical lines have equal gradients.","solution":"The given line has gradient 11, so the parallel line does too.","id":"x050-10","subject":"maths","topic":"Parallel lines","group":"Coordinate geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the gradient of a line perpendicular to y = 11x + 2. Give a fraction or decimal.","answer":-0.0909090909,"hint":"For non-zero gradients, the perpendicular gradient is the negative reciprocal.","solution":"The negative reciprocal of 11 is −1/11.","id":"x051-10","subject":"maths","topic":"Perpendicular lines","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A line passes through (1, 21) and (3, 41). Write it as y = mx + c. Find c.","answer":11,"hint":"Find the gradient from the two points, then substitute a point.","solution":"m = (41 − 21)/2 = 10. Then c = 21 − 10 = 11.","id":"x052-10","subject":"maths","topic":"Equation of a line through points","group":"Coordinate geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"A pack of 13 notebooks costs £143. Find the price per notebook in pounds.","answer":11,"hint":"Divide cost by number of items.","solution":"£143 ÷ 13 = £11 per notebook.","id":"x053-10","subject":"maths","topic":"Best buys and unit pricing","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"£1 exchanges for €1.20. How many euros are exchanged for £250?","answer":300,"hint":"Multiply the pound amount by the euros-per-pound rate.","solution":"250 × 1.20 = €300.","id":"x054-10","subject":"maths","topic":"Currency conversion","group":"Proportion and rates","tier":"Both","calculator":true,"marks":2},{"prompt":"A recipe for 4 people uses 280 g of rice. How many grams are needed for 6 people?","answer":420.0,"hint":"Scale every ingredient by 6/4.","solution":"280 × 6/4 = 420.0 g.","id":"x055-10","subject":"maths","topic":"Scaling recipes","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"A map has scale 1:50 000. Two places are 10 cm apart on the map. Find their real distance in kilometres.","answer":5.0,"hint":"Convert the scaled centimetres into kilometres using 100 000 cm = 1 km.","solution":"10 × 50 000 = 500000 cm = 5.0 km.","id":"x056-10","subject":"maths","topic":"Map scales","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is directly proportional to x. When x = 3, y = 33. Find y when x = 8.","answer":88,"hint":"Find k in y = kx.","solution":"k = 33/3 = 11; hence y = 11 × 8 = 88.","id":"x057-10","subject":"maths","topic":"Direct proportion","group":"Proportion and rates","tier":"Both","calculator":false,"marks":2},{"prompt":"y is inversely proportional to x. When x = 2, y = 60. Find y when x = 3.","answer":40,"hint":"The product xy stays constant.","solution":"k = 2 × 60 = 120. Thus y = 120/3 = 40.","id":"x058-10","subject":"maths","topic":"Inverse proportion","group":"Proportion and rates","tier":"Higher","calculator":false,"marks":2},{"prompt":"£1000 earns 5% compound interest each year. Find the balance after 2 years in pounds.","answer":1102.5,"hint":"Multiply by 1.05 for each year.","solution":"£1000 × 1.05² = £1102.50.","id":"x059-10","subject":"maths","topic":"Compound interest","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A bicycle worth £2500 loses 20% of its value each year. Find its value after 2 years in pounds.","answer":1600,"hint":"Retain 80% each year, using the multiplier 0.8 twice.","solution":"£2500 × 0.8² = £1600.","id":"x060-10","subject":"maths","topic":"Depreciation","group":"Finance","tier":"Both","calculator":true,"marks":3},{"prompt":"A culture begins with 2000 cells and increases by 10% each hour. Find the modelled count after 2 hours.","answer":2420,"hint":"Use the growth multiplier 1.1 twice.","solution":"2000 × 1.1² = 2420 cells.","id":"x061-10","subject":"maths","topic":"Repeated percentage growth","group":"Finance","tier":"Both","calculator":true,"marks":2},{"prompt":"A block has mass 1320 g and volume 120 cm³. Find its density in g/cm³.","answer":11,"hint":"Density = mass ÷ volume.","solution":"1320 ÷ 120 = 11 g/cm³.","id":"x062-10","subject":"maths","topic":"Density","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A force of 1800 N acts on an area of 30 m². Find pressure in N/m².","answer":60,"hint":"Pressure = force ÷ area.","solution":"1800 ÷ 30 = 60 N/m².","id":"x063-10","subject":"maths","topic":"Pressure","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"Convert 11 m² into cm².","answer":110000,"hint":"Square the linear conversion: 1 m = 100 cm.","solution":"1 m² = 100² = 10 000 cm². Therefore 11 m² = 110000 cm².","id":"x064-10","subject":"maths","topic":"Metric area conversions","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A journey starts at 09:20 and ends at 11:45. Find its duration in minutes.","answer":145,"hint":"Count the full hours and the remaining minutes.","solution":"From 09:20 to 11:20 is 120 minutes, then another 25. Total = 145 minutes.","id":"x065-10","subject":"maths","topic":"Time calculations","group":"Measures","tier":"Both","calculator":false,"marks":2},{"prompt":"A rectangle is 18 cm by 14 cm. A 2 cm by 2 cm square is cut from one corner. Find the perimeter of the remaining L-shape in cm.","answer":64,"hint":"The two removed edge lengths are replaced by two equal inner edge lengths.","solution":"The perimeter stays equal to the original rectangle: 2(18 + 14) = 64 cm.","id":"x066-10","subject":"maths","topic":"Perimeter of compound shapes","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 11 cm. Express its circumference as kπ cm. Find k.","answer":22,"hint":"Circumference is 2πr.","solution":"2π × 11 = 22π cm.","id":"x067-10","subject":"maths","topic":"Circle circumference","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A circle has radius 12 cm. Its area is kπ cm². Find k.","answer":144,"hint":"Square the radius and multiply by π.","solution":"Area = π × 12² = 144π cm².","id":"x068-10","subject":"maths","topic":"Area of circles","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A semicircle has radius 12 cm. Its perimeter is πr + d. Find the straight-edge length d in cm.","answer":24,"hint":"The straight edge is the diameter, not the radius.","solution":"d = 2r = 2 × 12 = 24 cm. The complete perimeter is 12π + 24 cm.","id":"x069-10","subject":"maths","topic":"Semicircle perimeter","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 60° and radius 30 cm. Its arc length is kπ cm. Find k.","answer":10,"hint":"Take 60/360 of the circumference.","solution":"(60/360) × 2π × 30 = 10π cm.","id":"x070-10","subject":"maths","topic":"Arc length","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A sector has angle 90° and radius 20 cm. Its area is kπ cm². Find k.","answer":100,"hint":"Take one quarter of the full circle area.","solution":"(90/360) × π × 20² = 100π cm².","id":"x071-10","subject":"maths","topic":"Sector area","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A triangular prism has triangular cross-section base 12 cm, height 6 cm, and prism length 10 cm. Find its volume in cm³.","answer":360,"hint":"Find the triangle area, then multiply by the prism length.","solution":"Cross-section = ½ × 12 × 6 = 36 cm². Volume = 360 cm³.","id":"x072-10","subject":"maths","topic":"Volume of prisms","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A cylinder has radius 11 cm and height 5 cm. Its volume is kπ cm³. Find k.","answer":605,"hint":"Multiply the circular base area by the height.","solution":"πr²h = π × 11² × 5 = 605π cm³.","id":"x073-10","subject":"maths","topic":"Volume of cylinders","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A cone has radius 11 cm and perpendicular height 9 cm. Its volume is kπ cm³. Find k.","answer":363,"hint":"A cone has one third of the corresponding cylinder volume.","solution":"V = πr²h/3 = π × 11² × 9/3 = 363π cm³.","id":"x074-10","subject":"maths","topic":"Volume of cones","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A sphere has radius 30 cm. Its volume is kπ cm³. Find k.","answer":36000,"hint":"Use V = 4πr³/3.","solution":"(4/3) × 30³ = 36000, so V = 36000π cm³.","id":"x075-10","subject":"maths","topic":"Volume of spheres","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A cuboid measures 11 cm by 3 cm by 4 cm. Find its total surface area in cm².","answer":178,"hint":"There are two faces of each of the three different rectangular areas.","solution":"2[3(11) + 4(11) + 3×4] = 178 cm².","id":"x076-10","subject":"maths","topic":"Surface area of cuboids","group":"Geometry","tier":"Both","calculator":false,"marks":3},{"prompt":"A closed cylinder has radius 11 cm and height 4 cm. Its total surface area is kπ cm². Find k.","answer":330,"hint":"Include two circular ends and the curved surface.","solution":"2r² + 2rh = 2(11²) + 2(11)(4) = 330.","id":"x077-10","subject":"maths","topic":"Cylinder surface area","group":"Geometry","tier":"Higher","calculator":false,"marks":3},{"prompt":"Two similar shapes have length scale factor 3 from small to large. A small side is 12 cm. Find the matching large side.","answer":36,"hint":"Multiply corresponding lengths by the length scale factor.","solution":"12 × 3 = 36 cm.","id":"x078-10","subject":"maths","topic":"Similarity of lengths","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Two similar shapes have length scale factor 2. The smaller area is 13 cm². Find the larger area.","answer":52,"hint":"Square the length scale factor for areas.","solution":"Area factor = 2² = 4. Larger area = 13 × 4 = 52 cm².","id":"x079-10","subject":"maths","topic":"Similarity of areas","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"Two similar solids have length scale factor 3. The smaller volume is 11 cm³. Find the larger volume.","answer":297,"hint":"Cube the length scale factor for volumes.","solution":"Volume factor = 3³ = 27. Larger volume = 297 cm³.","id":"x080-10","subject":"maths","topic":"Similarity of volumes","group":"Geometry","tier":"Higher","calculator":false,"marks":2},{"prompt":"A triangle has two angles 50° and 70°. Find the third angle in degrees.","answer":60,"hint":"Interior angles in a triangle total 180°.","solution":"180 − 50 − 70 = 60°.","id":"x081-10","subject":"maths","topic":"Triangle angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A regular polygon has 14 sides. Find its exterior angle in degrees, to 3 decimal places if needed.","answer":25.714,"hint":"The exterior angles total 360°.","solution":"Each exterior angle is 360/14 = 25.714°.","id":"x082-10","subject":"maths","topic":"Exterior angles of polygons","group":"Geometry","tier":"Both","calculator":true,"marks":2},{"prompt":"A transversal crosses two parallel lines. One of a pair of co-interior angles is 90°. Find the other angle in degrees.","answer":90,"hint":"Co-interior angles on parallel lines sum to 180°.","solution":"180 − 90 = 90°.","id":"x083-10","subject":"maths","topic":"Angles in parallel lines","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the sum of the interior angles of a polygon with 13 sides.","answer":1980,"hint":"Use (number of sides − 2) × 180°.","solution":"(13 − 2) × 180 = 1980°.","id":"x084-10","subject":"maths","topic":"Polygon interior-angle sums","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"The bearing of B from A is 070°. Find the bearing of A from B as a number of degrees.","answer":250,"hint":"A reverse bearing differs by 180°.","solution":"70 + 180 = 250°.","id":"x085-10","subject":"maths","topic":"Three-figure bearings","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"A right-angled triangle has hypotenuse 24 cm and an angle of 30°. Find the side opposite that angle in cm.","answer":12,"hint":"Use sin(angle) = opposite/hypotenuse.","solution":"Opposite = 24 × sin30° = 12 cm.","id":"x086-10","subject":"maths","topic":"Right-angle trigonometry","group":"Trigonometry","tier":"Both","calculator":true,"marks":3},{"prompt":"In a triangle, side a = 12 cm is opposite 30°, and side b is opposite 90°. Find b in cm.","answer":24,"hint":"Use a/sin A = b/sin B.","solution":"b = 12 × sin90°/sin30° = 24 cm.","id":"x087-10","subject":"maths","topic":"Sine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides of a triangle are 12 cm each, with included angle 60°. Find the opposite side in cm.","answer":12,"hint":"Use c² = a² + b² − 2ab cos C.","solution":"c² = 2(12²) − 2(12²)cos60° = 144, so c = 12 cm.","id":"x088-10","subject":"maths","topic":"Cosine rule","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"Two sides are 12 cm and 8 cm, with included angle 30°. Find the triangle area in cm².","answer":24,"hint":"Use area = ½ab sin C.","solution":"½ × 12 × 8 × sin30° = 24 cm².","id":"x089-10","subject":"maths","topic":"Triangle area using sine","group":"Trigonometry","tier":"Higher","calculator":true,"marks":3},{"prompt":"An angle at the circumference is 30°. The central angle subtended by the same arc is less than 180°. Find it.","answer":60,"hint":"The angle at the centre is twice the angle at the circumference on the same arc.","solution":"2 × 30 = 60°.","id":"x090-10","subject":"maths","topic":"Angles at the centre","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"One angle of a cyclic quadrilateral is 110°. Find its opposite angle.","answer":70,"hint":"Opposite angles in a cyclic quadrilateral total 180°.","solution":"180 − 110 = 70°.","id":"x091-10","subject":"maths","topic":"Cyclic quadrilaterals","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"A tangent and chord form an angle of 45°. Find the angle subtended by that chord in the alternate segment.","answer":45,"hint":"The tangent-chord angle equals the angle in the alternate segment.","solution":"By the alternate segment theorem, the required angle is 45°.","id":"x092-10","subject":"maths","topic":"Alternate segment theorem","group":"Circle theorems","tier":"Higher","calculator":false,"marks":2},{"prompt":"Vectors a = (10, 3) and b = (12, −1). Find the x-component of a + b.","answer":22,"hint":"Add corresponding components.","solution":"a + b = (22, 2), so the x-component is 22.","id":"x093-10","subject":"maths","topic":"Adding vectors","group":"Vectors","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the magnitude of the vector (30, 40).","answer":50,"hint":"Use Pythagoras on the two components.","solution":"√(30² + 40²) = 50.","id":"x094-10","subject":"maths","topic":"Vector magnitude","group":"Vectors","tier":"Higher","calculator":true,"marks":2},{"prompt":"Rotate (10, 12) by 90° anticlockwise about the origin. Find the new x-coordinate.","answer":-12,"hint":"The rule for 90° anticlockwise is (x,y) → (−y,x).","solution":"The image is (−12, 10), so its x-coordinate is −12.","id":"x095-10","subject":"maths","topic":"Rotations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Enlarge (10, 2) by scale factor 3 about the origin. Find the new x-coordinate.","answer":30,"hint":"Multiply both coordinates by the scale factor.","solution":"The image is (30, 6).","id":"x096-10","subject":"maths","topic":"Enlargements","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Translate (10, 4) by the vector (−3, 2). Find the new x-coordinate.","answer":7,"hint":"Add the x-component of the vector to the x-coordinate.","solution":"The image is (7, 6).","id":"x097-10","subject":"maths","topic":"Translations","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Reflect (10, 13) in the line y = x. Find the new x-coordinate.","answer":13,"hint":"Reflection in y = x swaps the coordinates.","solution":"The image is (13, 10).","id":"x098-10","subject":"maths","topic":"Reflections","group":"Transformations","tier":"Both","calculator":false,"marks":2},{"prompt":"Points must be exactly 12 cm from a fixed point P. What is their locus?","kind":"choice","options":["A straight line through P","A perpendicular bisector through P","A circle centred at P with radius 12 cm","A circle centred at P with diameter 12 cm"],"correct":2,"answer":null,"hint":"A fixed distance from one point defines a circle.","solution":"All points on a circle of radius 12 cm are exactly 12 cm from its centre P.","id":"x099-10","subject":"maths","topic":"Loci and constructions","group":"Geometry","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the median of 17, 10, 13, 19, 11.","answer":13,"hint":"Order the values, then choose the middle one.","solution":"The ordered list is 10, 11, 13, 17, 19. Its middle value is 13.","id":"x100-10","subject":"maths","topic":"Finding the median","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the mode of 10, 12, 12, 14, 12, 16.","answer":12,"hint":"Look for the value occurring most frequently.","solution":"12 occurs three times; every other value occurs once.","id":"x101-10","subject":"maths","topic":"Finding the mode","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"Find the range of −10, 2, 14, 0.","answer":24,"hint":"Subtract the minimum from the maximum.","solution":"14 − (−10) = 24.","id":"x102-10","subject":"maths","topic":"Finding the range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A data set has lower quartile 13 and upper quartile 47. Find its interquartile range.","answer":34,"hint":"IQR = upper quartile − lower quartile.","solution":"47 − 13 = 34.","id":"x103-10","subject":"maths","topic":"Interquartile range","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A grouped table has 2 values in 0 ≤ x < 10 and 12 values in 10 ≤ x < 20. Estimate the mean, to 3 decimal places.","answer":13.571,"hint":"Use class midpoints 5 and 15, multiply by frequencies, then divide by total frequency.","solution":"Estimated total = 2×5 + 12×15 = 190. Divide by 14 to get 13.571.","id":"x104-10","subject":"maths","topic":"Estimated mean from grouped data","group":"Statistics","tier":"Both","calculator":true,"marks":3},{"prompt":"A histogram class has width 5 and frequency 60. Find its frequency density.","answer":12,"hint":"Frequency density = frequency ÷ class width.","solution":"60 ÷ 5 = 12.","id":"x105-10","subject":"maths","topic":"Frequency density","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"Class frequencies, in ascending order, are 10, 12, 14, 16. Find the cumulative frequency at the end of the third class.","answer":36,"hint":"Add all frequencies up to and including the third class.","solution":"10 + 12 + 14 = 36.","id":"x106-10","subject":"maths","topic":"Cumulative frequency","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A box plot has minimum 10, lower quartile 13, median 16, upper quartile 19, maximum 25. Read off its median.","answer":16,"hint":"The median is the line inside the box.","solution":"The median line is at 16. The ends of the box are the quartiles.","id":"x107-10","subject":"maths","topic":"Box plots","group":"Statistics","tier":"Both","calculator":false,"marks":2},{"prompt":"A school has 600 pupils; 300 are in a chosen group. In a proportional sample of 40 pupils, how many should come from that group?","answer":20,"hint":"Multiply the sample size by the group proportion.","solution":"40 × 300/600 = 20 pupils.","id":"x108-10","subject":"maths","topic":"Stratified sampling","group":"Statistics","tier":"Higher","calculator":false,"marks":2},{"prompt":"An experiment succeeds 13 times out of 20 trials. Find the relative frequency as a fraction or decimal.","answer":0.65,"hint":"Divide the number of successes by the number of trials.","solution":"Relative frequency = 13/20 = 0.65.","id":"x109-10","subject":"maths","topic":"Relative frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"An event has probability 0.3. It is tested 200 times. Find its expected frequency.","answer":60,"hint":"Multiply probability by number of trials.","solution":"0.3 × 200 = 60. This is an expectation, not a guarantee.","id":"x110-10","subject":"maths","topic":"Expected frequency","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Two independent events have probabilities 1/2 and 10/12. Find the probability that both occur.","answer":0.4166666667,"hint":"Multiply the probabilities of independent events.","solution":"1/2 × 10/12 = 10/24.","id":"x111-10","subject":"maths","topic":"Independent events","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A bag has 12 red counters and 3 blue counters. Two counters are drawn without replacement. Find P(both red), to 3 decimal places.","answer":0.629,"hint":"The second draw has one fewer red counter and one fewer counter altogether.","solution":"P = (12/15) × (11/14) = 0.629.","id":"x112-10","subject":"maths","topic":"Sampling without replacement","group":"Probability","tier":"Higher","calculator":true,"marks":3},{"prompt":"Of 15 club members who play tennis, 10 also swim. A member is chosen from the tennis players only. Find P(swims), as a fraction or decimal.","answer":0.6666666667,"hint":"Use the restricted tennis group as the denominator.","solution":"Given that the person plays tennis, P(swims) = 10/15.","id":"x113-10","subject":"maths","topic":"Conditional probability","group":"Probability","tier":"Higher","calculator":false,"marks":2},{"prompt":"Set A contains 38 people including 12 in A ∩ B. How many are in A only?","answer":26,"hint":"Subtract the intersection from the total in A.","solution":"38 − 12 = 26 people.","id":"x114-10","subject":"maths","topic":"Venn diagram regions","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"n(A) = 20, n(B) = 22, and n(A ∩ B) = 13. Find n(A ∪ B).","answer":29,"hint":"Add the two set sizes and subtract the overlap once.","solution":"20 + 22 − 13 = 29.","id":"x115-10","subject":"maths","topic":"Set union","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"A fair coin is tossed, then a fair 13-sided die numbered 1 to 13 is rolled. Find P(heads and a 1).","answer":0.0384615385,"hint":"Multiply the branch probabilities along the path.","solution":"(1/2) × (1/13) = 1/26.","id":"x116-10","subject":"maths","topic":"Tree diagrams","group":"Probability","tier":"Both","calculator":false,"marks":2},{"prompt":"Plot the listed points for y = x³ + 5. Use x = -2, -1, 0, 1, 2. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[-2,-3],[-1,4],[0,5],[1,6],[2,13]],"curve":"quadratic","range":[-3,3,-14,14],"expression":"y = x³ + 5","hint":"Cube each x, preserving its sign, then add the constant.","solution":"The coordinates are (-2, -3), (-1, 4), (0, 5), (1, 6), (2, 13). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x117-10","subject":"maths","topic":"Cubic graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 12/x + 9 for 1 ≤ x ≤ 6. Use x = 1, 2, 3, 4, 6. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[1,21.0],[2,15.0],[3,13.0],[4,12.0],[6,11.0]],"curve":"quadratic","range":[0,7,0,23],"expression":"y = 12/x + 9 for 1 ≤ x ≤ 6","hint":"Divide 12 by x, then add the constant; x = 0 is not allowed.","solution":"The coordinates are (1, 21.0), (2, 15.0), (3, 13.0), (4, 12.0), (6, 11.0). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x118-10","subject":"maths","topic":"Reciprocal graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"Plot the listed points for y = 2^x + 9. Use x = 0, 1, 2, 3. Join them with the smooth-curve tool.","kind":"graph","answer":null,"points":[[0,10],[1,11],[2,13],[3,17]],"curve":"quadratic","range":[-1,4,0,18],"expression":"y = 2^x + 9","hint":"Calculate the power of 2 first, then add the constant.","solution":"The coordinates are (0, 10), (1, 11), (2, 13), (3, 17). Use a smooth curve through them. The drawing tool interpolates between points.","marks":5,"id":"x119-10","subject":"maths","topic":"Exponential graphs","group":"Graphs","tier":"Higher","calculator":false},{"prompt":"The graph y = x² is translated upward by 12 units. Find the new y-coordinate of its turning point.","answer":12,"hint":"An upward translation adds the same amount to every y-coordinate.","solution":"The old turning point is (0, 0); the new one is (0, 12).","id":"x120-10","subject":"maths","topic":"Translating graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A straight segment on a distance-time graph runs from (0 hours, 0 km) to (2 hours, 120 km). Find the speed in km/h.","answer":60,"hint":"Speed is the gradient: distance change divided by time change.","solution":"120 km ÷ 2 h = 60 km/h.","id":"x121-10","subject":"maths","topic":"Distance-time graphs","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A velocity-time graph rises in a straight line from 0 m/s to 50 m/s in 5 seconds. Find acceleration in m/s².","answer":10,"hint":"Acceleration is change in velocity divided by time.","solution":"(50 − 0)/5 = 10 m/s².","id":"x122-10","subject":"maths","topic":"Velocity-time gradients","group":"Graphs","tier":"Both","calculator":false,"marks":2},{"prompt":"A tangent to a curve passes through (1, 10) and (3, 32). Estimate the gradient of the curve at the contact point.","answer":11,"hint":"Use the gradient of the tangent, not a chord through two curve points.","solution":"(32 − 10)/(3 − 1) = 11.","id":"x123-10","subject":"maths","topic":"Tangents and rates of change","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"A velocity-time graph forms a triangle with base 6 seconds and maximum velocity 20 m/s. Find the displacement in metres.","answer":60,"hint":"Displacement is the signed area under a velocity-time graph.","solution":"Area = ½ × 6 × 20 = 60 m.","id":"x124-10","subject":"maths","topic":"Area under velocity-time graphs","group":"Graphs","tier":"Higher","calculator":false,"marks":2},{"prompt":"The lines y = x + 10 and y = 3x intersect. Find the x-coordinate of the intersection.","answer":5.0,"hint":"At the intersection, both expressions for y are equal.","solution":"x + 10 = 3x, so 2x = 10 and x = 5.0.","id":"x125-10","subject":"maths","topic":"Graphical simultaneous equations","group":"Graphs","tier":"Both","calculator":false,"marks":3},{"prompt":"Which point satisfies both x > 10 and y < 3?","kind":"choice","options":["(11, 4)","(9, 0)","(11, 2)","(10, 2)"],"correct":2,"answer":null,"hint":"Test both strict inequalities for each coordinate pair.","solution":"Only (11, 2) has x strictly greater than 10 and y strictly less than 3.","id":"x126-10","subject":"maths","topic":"Regions satisfying inequalities","group":"Graphs","tier":"Higher","calculator":false,"marks":2}];
